  FT["PH-H16667"] = {"id":"PH-H16667","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MAL AC AT ANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES AMENDING PARAGRAPH FIVE OF EXECTTIVE ORDER NO. 111, DATED AUGUST 30, 1937, ENTITLED \"PROFIBITING AND RESTRICTING THE PRACTICE OF NEPOTISM\",","orig":"MAL AC AT ANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES AMENDING PARAGRAPH FIVE OF EXECTTIVE ORDER NO. 111, DATED AUGUST 30, 1937, ENTITLED \"PROFIBITING AND RESTRICTING THE PRACTICE OF NEPOTISM\","},"level":"law","status":"active","docNumber":"Executive Order No. 21","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00021_1954.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00021_1954.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16667-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"hereof shall not also he applicable to the\ncase of a member of any family who, after his or her\nappointment to any position in an office or bureau, con-\ntracts marriage with scene emnloved in the same office\nor bureau, in which event the employment or retention\ntherein of hoth hushand and wife may he allowed. \"\nDone in the City of Manila, this 23rd day of March,\nIn the year of Our Lord, nineteen hundred and fifty-four,\nand of the Independence of the Philippines, the eighth.\n(SGD.) RAMON MAGSAYSAY\nPresident of the Philippines\nBy the President:\n(SCD.) FEED RUIZ CASTRO\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H16668"] = {"id":"PH-H16668","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES DECLARING THE PROPOSED SAN FERNANDO AIR- PORT ROAD IN LA UNION, FROM THE JUNC- TION WITH THE PORO POINT ROAD TO THE TERMINAL OFFICE OF THE AIRPORT AS N- TIONAL SECONDARY ROAD","orig":"MALACAÑANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES DECLARING THE PROPOSED SAN FERNANDO AIR- PORT ROAD IN LA UNION, FROM THE JUNC- TION WITH THE PORO POINT ROAD TO THE TERMINAL OFFICE OF THE AIRPORT AS N- TIONAL SECONDARY ROAD"},"level":"law","status":"active","docNumber":"Executive Order No. 21","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00021_1962.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00021_1962.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16668-A1","no":1,"noLabel":{},"text":{"en":"to the terminal office of the airport, from km. 268.909\nto km. 269.878 or a distance of .969 kms., as national\nsecondary road.\nDone in the City of Manila, this 17th day of September,\nin the year of Our Lord, nineteen hundred and sixty-two.\nDIOSDADO MACAPAGAL\nPresident of the Philippines\nBy the President:\nSALVADOR L. MARIÑO\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H16669"] = {"id":"PH-H16669","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF DID FRESIDENT OF TE PHILIPPINES BY THO PROSIDINT OF THO PHILIPPINES EXECUTIVE OADER NO. 21 REQUIRING ALL CFFIGERS AND EMPLOYELS OF THE GCVERN- WENT VISITING BUSIMESS ESTABLISHNENTS FOR PUR- POSDS OF EXAMINING BOOKS OF ASCOUNTS, RECORDS, OR OTHERWISE INSPECTING THD FRIMISES THEREOF IN CONNECTION WITH THE PERFORIANCE OF TIDIR DUTIES TO SIGN A REGISTRY BOOK.","orig":"MALACANANG RESIDENCE OF DID FRESIDENT OF TE PHILIPPINES BY THO PROSIDINT OF THO PHILIPPINES EXECUTIVE OADER NO. 21 REQUIRING ALL CFFIGERS AND EMPLOYELS OF THE GCVERN- WENT VISITING BUSIMESS ESTABLISHNENTS FOR PUR- POSDS OF EXAMINING BOOKS OF ASCOUNTS, RECORDS, OR OTHERWISE INSPECTING THD FRIMISES THEREOF IN CONNECTION WITH THE PERFORIANCE OF TIDIR DUTIES TO SIGN A REGISTRY BOOK."},"level":"law","status":"active","docNumber":"Executive Order No. 21","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00021_1966.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00021_1966.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16669-A1","no":1,"noLabel":{},"text":{"en":"Done in the City of Manila, this 23rd day of\nApril, in the year of Our Lord, nineteen hundred\nand sixty-six.\n(SGD.) FORDINAND D. MARCOS\nFronident of the Philippines\nBy the Freaident:\n(SGD.) RAPADL M. SALAS\nExecutive Seoretary"}}],"pack":"ph-p157"};
