  FT["PH-H16707"] = {"id":"PH-H16707","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MAL AC AJ ANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE CONSULTATIVE COUNCIL OF STUDENTS","orig":"MAL AC AJ ANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE CONSULTATIVE COUNCIL OF STUDENTS"},"level":"law","status":"active","docNumber":"Executive Order No. 24","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00024_1954.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00024_1954.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16707-A1","no":1,"noLabel":{},"text":{"en":"- 2 -\nmend them for scholarships; and\nc. To study and discuss such other problems con-\ncerning youth and student affairs as the President may\nassign to it and to recommend appropriate sclution\n3. The Council shall maintain a Secretariat, under the\nChairman, which shall be responsible for the administration\nof the affairs of the Council.\n- 4. All departrents, bureaus, offices, agencies and\ninstrumentalities of the government, including government-\nowned or controlled corporations, shall extend such neces-\nsary assistance and cooperation as may be recuested by the\nCouncil through its Chairman.\nDone in the City of Manila, this 8th day of April, in the\nyear of Our Lord, nineteen hundred and fifty-four, and of the\nIndependence of the Philippines, the eighth.\n(SGD.) RATION MAGSAYSAY\nPresident of the Philippines\nBy the President:\n(SGD.) FRED RUIZ CASTRO\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H16708"] = {"id":"PH-H16708","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES A DECORATION TO BE KNm,TN AS THE ORDER OF SIKATUNA","orig":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES A DECORATION TO BE KNm,TN AS THE ORDER OF SIKATUNA"},"level":"law","status":"active","docNumber":"Executive Order No. 24","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00024_1962.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00024_1962.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16708-A1","no":1,"noLabel":{},"text":{"en":"\"5. i.lfuJw,.N/w-To be awarded to junior officers of\nthe Department of Foreign Affairs, whether in the\nHome OHice 01\" in the Foreign Service, to other govern-\ntrtent officials of the Philippines and of foreign coun-\ntries, and to private citizens deserving of such honor.\nBefore any Filipino gov~rnment official or employee\nmay be entitled to the award, he must have served at\nleast four years in the government.\"\nDone in the City of Manila, this 19th day 6f October,\nin the year of Our Lord, nineteen hundred and sixty-two.\nBy the President:\nDIOSDADO MACAPAGAL\npl'f'esident of the Philippines\nSALVADOR L. MARINO\nExecutive Secretary"}}],"pack":"ph-p157"};
