  FT["PH-H16827"] = {"id":"PH-H16827","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"EXECUTIVE ORDER NO. ..3 5 THE NATIONAL COMPUTER CENTER (NCC) TO DESIGN AND BUILD AN INTEGRATED GOVERNMENT INFORMATION INFRASTRUCTURE","orig":"EXECUTIVE ORDER NO. ..3 5 THE NATIONAL COMPUTER CENTER (NCC) TO DESIGN AND BUILD AN INTEGRATED GOVERNMENT INFORMATION INFRASTRUCTURE"},"level":"law","status":"active","docNumber":"Executive Order No. 35","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00035_1998.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00035_1998.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16827-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Design and build an integrated government information infrastructure (GII);"}},{"id":"PH-H16827-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Integrate all existing computer systems of government entities to make themcom\nwith the GII;"}},{"id":"PH-H16827-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Connect all government entities to the GII."}},{"id":"PH-H16827-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"All orders, directories, issuances, resolutions, rules or regulations or parts\nthereof inconsistent with the provisions of this executive order are hereby repealed or modified\naccordingly."}},{"id":"PH-H16827-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Executive Order shall take effect immediatcly.\nDone in the City of~~his\nof Oc.:ro,se,e., ;t1t1i\n~\nc::===::::~~-:-~ ~~~ITO ESTRADA\nBy authority of the President:\n-~~-\nRONALDOZAMORA\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H16828"] = {"id":"PH-H16828","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY TRANSFERRING THE FUNCTION OF ISSUING LICENSES OR PERMITS FOR TREASURE HUNTING AND SHIPWRECK RECOVERY PERMITS FROM THE OFFICE OF THE PRESIDENT TO THE DEPARTMENT OF ENVIRONMENT AND NATURAL RESOURCES","orig":"MALACAÑANG PMS LIBRARY TRANSFERRING THE FUNCTION OF ISSUING LICENSES OR PERMITS FOR TREASURE HUNTING AND SHIPWRECK RECOVERY PERMITS FROM THE OFFICE OF THE PRESIDENT TO THE DEPARTMENT OF ENVIRONMENT AND NATURAL RESOURCES"},"level":"law","status":"active","docNumber":"Executive Order No. 35","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00035_2001.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00035_2001.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16828-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The function of issuing licenses/permits for treasure hunting and\nshipwreck recovery is hereby reverted to the Department of Environment and Natural"}},{"id":"PH-H16828-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"The Secretary of Environment and Natural Resources shall take the steps\nnecessary to effect this transfer of function and shall issue such guidelines and rules and\nregulations concerning the issuance of such permits and licenses.\nPOMA Outgoing r 05336\n\naccordingly.\nAll executive issuances, rules and regulations or parts thereof\ninconsistent with this Executive Order are hereby repealed, amended or modified"}},{"id":"PH-H16828-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 17th day of SEP, in the year of Our Lord, two\nthousand and one.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY\nPOMA Outgoing * 05337\nPMS LIBRARY BCODE002036"}}],"pack":"ph-p157"};
  FT["PH-H16829"] = {"id":"PH-H16829","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAI$AN PALACE BY THE PRESIDENT OF THE PHTLIPPINES TRANSFERRING THE CONTROL AND SUPERVISION OF THE PHILIPPINE CENTER ON TRANSNATIONAL CRIME FROM THE DEPARTMENT THE INTERIOR AND LOCAL GOVERNMENT TO THE OFFICE OF THE","orig":"MALACAI$AN PALACE BY THE PRESIDENT OF THE PHTLIPPINES TRANSFERRING THE CONTROL AND SUPERVISION OF THE PHILIPPINE CENTER ON TRANSNATIONAL CRIME FROM THE DEPARTMENT THE INTERIOR AND LOCAL GOVERNMENT TO THE OFFICE OF THE"},"level":"law","status":"active","docNumber":"Executive Order No. 35","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00035_2011.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00035_2011.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16829-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Transferof PGTG from DILG to OP. The direct control and\nsupervision\nover PCTC is hereby transferred\nfrom DILG to Op."}},{"id":"PH-H16829-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Repealing Clause. All executive\norders, issuances,\nol rle $rerftaf ot rte Frililpinrt\nilil il flilil\nililililil\nltilflililil|\n\nregulations\nor pafts thereof which are inconsistent\nthis Executive\nhereby repealed\nor modified\naccordingly.\n3. Effectivity. This Executive\nOrder shall take effect immediately\nupon publication\nin a newspaper\ncirculation\nDONE in the City of Manila,\nthis l lthflsy ef April\nin the year of our\nLord, Two Thousand and Eleven.\n4,0-,\n@tliie ol tle $rerilnrt ot tle Sbitippiner\nilil il l|ilil\nBy the President:"}}],"pack":"ph-p157"};
  FT["PH-H16830"] = {"id":"PH-H16830","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ORDER OF LAPU-LAPU","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ORDER OF LAPU-LAPU"},"level":"law","status":"active","docNumber":"Executive Order No. 35","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00035_2017.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00035_2017.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16830-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Section 2 of EO No. 17 is hereby amended to read as follows:\n\"SECTION 2. Medals. The Order of Lapu-Lapu shall comprise\nfour (4) medals, which shall be ranked in the following order of\nprecedence:\nMagalong Medal - Awarded to officials and personnel of the\ngovernment and private individuals who have rendered extraordinary\nservice or have made exceptional contributions to the success of an\nactivity pursuant to a campaign or advocacy of the President;\nTHE PRESIDENT OF THE PHILIPPINES\n\nKalasag Medal - Awarded to officials and personnel of the\ngovernment and private individuals who lost their lives as a direct\nresult of their participation in an activity pursuant to a campaign or\nadvocacy of the President;\nKampilan Medal - Awarded to officials and personnel of the\ngovernment and private individuals who were seriously wounded or\ninjured or suffered great loss of property as a direct result of their\nparticipation in an activity pursuant to a campaign or advocacy of the\nPresident; and\nKamagi Medal - Awarded to officials and personnel of the\ngovernment and private individuals who, not falling under any of the\nabovementioned Order of Lapu-Lapu Medals, actively participated in\nand contributed significantly to an activity pursuant to a campaign or\nadvocacy of the President.\nIn all cases, the nominees shall be recommended by the\nHeads of Agencies involved in the abovementioned activities"}},{"id":"PH-H16830-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Except for the foregoing amendment, all other provisions of E0\nNo. 17 shall remain unchanged"}},{"id":"PH-H16830-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"This Executive Order shall take effect immediately upon its\npublication in a national newspaper of general circulation.\nDONE, in the City of Manila this 28thday of July\nLord, Two Thousand and Seventeen.\nin the vear of Our\nBy the President:\nSALVADOR C. MEDIALDEA\nExecutive Secretary\n^\nREPUBLIC OF THE PHILIPPINES\nOffice of the President\nMALACAÑANG RECORDS OFFICE\nCERTIMED COPY\nATTY. CONCEPCION ZENY E. FERROETNO-ENAD\n, 8-2-207\nDIRECTOR III"}}],"pack":"ph-p157"};
  FT["PH-H16831"] = {"id":"PH-H16831","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CONSTITUTING THE INTER-AGENCY COUNCIL FOR THE PASIG RIVER URBAN DEVELOPMENT","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CONSTITUTING THE INTER-AGENCY COUNCIL FOR THE PASIG RIVER URBAN DEVELOPMENT"},"level":"law","status":"active","docNumber":"Executive Order No. 35","issuingBody":"President of the Philippines","completenessNote":"全文，共 8 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00035_2023.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00035_2023.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16831-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Inter-Agency Council for the Pasig River Urban Development.\nThe Inter-Agency Council for the Pasig River Urban Development (\"Inter-Agency\nCouncil\") is hereby created, to be composed of the following:\nChairperson\nSecretary, DHSUD\nVice-Chairperson : Chairperson, MMDA\nSecretary, DPWH\nSecretary, DENR\nSecretary, DILG\nSecretary, Department of Tourism\nSecretary, Department of Transportation\nSecretary, Department of Finance\nSecretary, Department of Budget and Management\nChairperson, National Historical Commission of the\nPhilippines\nChairperson, National Commission for Culture and the Arts\nGeneral Manager, Philippine Ports Authority\nCommandant, Philippine Coast Guard\nGeneral Manager, Laguna Lake Development Authority\nChief Executive Officer, Tourism Infrastructure and Enterprise\nZone Authority\nThe National Housing Authority shall serve as the Secretariat of the\nInter-Agency Council, and shall provide administrative support to the\nmember-agencies thereof.\nThe Chairperson, Vice-Chairperson, and members of the Inter-Agency Council\nmay designate their alternates, with ranks not lower than an Assistant Secretary or its\nequivalent, who are fully authorized to decide for or on their behalf."}},{"id":"PH-H16831-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Powers and Functions. The Inter-Agency Council shall have the\ngeneral function and responsibility of facilitating and ensuring the full rehabilitation of\nthe banks along the Pasig River water system and nearby water systems in order to\nprovide alternative transportation, propel economic opportunities, and boost tourism\nactivities. For this purpose, the Inter-Agency Council shall perform the following\na. Formulate a Pasig River Urban Development Plan which shall serve as the\nblueprint for the rehabilitation of the banks along the Pasig River, its tributaries,\nand surrounding communities, with the end in view of realizing its full potential for\nmixed-use development, transportation, recreation, tourism, and sustainable\nhuman settlement, taking into consideration its historic and cultural value;\n2\n\nb. Implement a coordinated and integrated rehabilitation of the Pasig Riverbanks\nsystem and nearby water systems, and the construction of necessary\ninfrastructures in accordance with the Pasig River Urban Development Plan;\nc. Ensure that easements provided under Republic Act No. 386 or the \"Civil Code of\nthe Philippines\" and other relevant laws or issuances are observed, including all\nthe esteros and waterways that drain into the Pasig River;\nd. Study, prepare, and implement a comprehensive shelter plan for massive\nrelocation of informal settler families (ISFs) and other unauthorized or unlawful\noccupants along the Pasig Riverbanks, which shall include: (i) identification of\nsuitable relocation sites; (¡i) strategies for economic and social integration of ISFs\nin the area; and (i) long-term solutions to address ongoing migration into the Pasig\nRiverbanks;\ne. Accept grants, contributions, donations, endowments, bequests, or gifts in cash or\nin kind from local and foreign sources in support of the formulation and\nimplementation of the Pasig River Urban Development Plan, subject to existing\nlaws, rules and regulations;\nf. In coordination with concerned national government agencies and local\ngovernment units (LGUs), conduct a review of existing Presidential issuances\nrelative to the rehabilitation and development of the Pasig River, and recommend\nto the Office of the President the repeal and/or amendment of the same; and\ng. Perform such other functions as may be directed by the President.\nAs may be necessary, the Inter-Agency Council may call upon any government\ndepartment, agency, bureau, or instrumentality, including government-owned\nor -controlled corporations, and invite LGUs and representatives from the private\nsector, to provide assistance in attaining its objectives. Subject to compliance with\nexisting laws, rules and regulations, the Inter-Agency Council may facilitate\npublic-private partnerships to ensure the effective and efficient implementation of this\nOrder, as well as the Pasig River Urban Development Plan."}},{"id":"PH-H16831-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Funding. The initial funding requirements necessary for the\nimplementation of the Order shall be charged against the respective appropriations of\nthe member-agencies of the Inter-Agency Council. Thereafter, the funding\nrequirements necessary for the continued implementation of this Order shall be\nincluded in the budget proposals of said agencies, subject to the usual budget\npreparation process."}},{"id":"PH-H16831-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Implementing Guidelines. The Inter-Agency Council shall\nformulate and issue quidelines as may be necessary for the effective implementation\nof this Order."}},{"id":"PH-H16831-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Reporting. The Inter-Agency Council, through the DHSUD, is\nhereby directed to submit to the Office of the President, through the Office of the\nExecutive Secretary, a quarterly status report on the implementation of this Order.\n3"}},{"id":"PH-H16831-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Separability. If any section or part of this Order is declared\nunconstitutional or invalid, the other sections or provisions not otherwise affected shall\nremain in full force and effect."}},{"id":"PH-H16831-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Repeal. All issuances, orders, rules and regulations, or parts thereof\nthat are inconsistent with this Order, are hereby repealed or modified accordingly."}},{"id":"PH-H16831-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDONE, in the City of Manila, this 25th day of\nyear of Our Lord, Two Thousand and Twenty-Three.\nBy the President:\nLUCAS P. BERSAMIN\nExedutive Secretary\nOffice of the President\nMALACAÑANG RECORDS OFFICE\nATTY. CORICEPCION LAY E. FERROLINO-ENAD\nDIRECTOR IV\nREPUBLIC OF THE PHILIPPINES\n4"}}],"pack":"ph-p157"};
  FT["PH-H16832"] = {"id":"PH-H16832","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"THE GOVERNMENT OF THE PHILIPPINE ISLANDS, EXECUTIVE BUREAU. EXECUTIVE ORDER \\","orig":"THE GOVERNMENT OF THE PHILIPPINE ISLANDS, EXECUTIVE BUREAU. EXECUTIVE ORDER \\"},"level":"law","status":"active","docNumber":"Executive Order No. 36","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00036_1913.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00036_1913.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16832-A1","no":1,"noLabel":{},"text":{"en":"and is 150 meters upstream from the steel bridge on which\nthe street car line crosses the Pasig River.\nW. CAMEROn FORBES,\nGovernor-General."}}],"pack":"ph-p157"};
  FT["PH-H16833"] = {"id":"PH-H16833","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1936/eo_36_1936.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Cordage Allotment for 1936-1937","orig":"Cordage Allotment for 1936-1937"},"level":"law","status":"active","docNumber":"Executive Order No. 36","issuingBody":"President of the Philippines","promulgatedDate":"1936-06-03","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00036_1936_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00036_1936_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16833-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 36, June 03, 1936 ]\nCORDAGE ALLOTMENT FOR 1936-1937\nWHEREAS, in Executive Order Numbered Eight hundred ninety-eight, dated October twenty eighth, nineteen\nhundred and thirty-five, the cordage quota of six million pounds which may enter the United States from the\nPhilippines during any twelve-month period beginning May first, except the twelve-month period beginning\nMay first, nineteen hundred and thirty-five, was allocated among the producers or manufacturers thereof in the\nfollowing manner:\n(a) To Johnson-Pickett Rope Co., thirty-four and six hundred seventy-four thousand eight hundred forty-seven\nmillionths per centum of six million pounds, or two million eighty thousand four hundred ninety-one pounds;\n(b) To Elizalde Rope Factory, Inc., sixty-three and four hundred twenty thousand nine hundred twenty-three\nmillionths per centum of six million pounds, or three million eight hundred five thousand two hundred\nfifty-five pounds;\n(c) To Manila Cordage Company, one and four hundred thirty-five thousand six hundred twenty-one\nmillionths per centum of six millionths per centum of six million pounds, or eighty-six thousand one hundred\nthirty-seven pounds; and\n(d) To General Manufacturing Co., Inc., four hundred sixty-eight thousand six hundred eight millionths per\ncentum of six million pounds, or twenty-eight thousand one hundred seventeen pounds;"}}],"pack":"ph-p157"};
  FT["PH-H16834"] = {"id":"PH-H16834","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE TX ICTTI S ORDER No. 36 CA POTICUS 204 JUDICIAI PUTTIPTO D 1B ISIAPURE AD ROPE POSITINT'S OF DISGAICT","orig":"MALACAÑAN PALACE TX ICTTI S ORDER No. 36 CA POTICUS 204 JUDICIAI PUTTIPTO D 1B ISIAPURE AD ROPE POSITINT'S OF DISGAICT"},"level":"law","status":"active","docNumber":"Executive Order No. 36","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00036_1945.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00036_1945.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16834-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"of Commonwealth act No. 343, Sections 1 and\n2 of Commonwealth Act No. 545 and Commonwealth Acts Nos. 544 and\n661 are hereby repealed.\n2. Sections 153, 134, 155, 156, 157, and 161 of the\nRevised Administrative Code, as mended by act No. 4007\nof the Philimpire Legislature, are hereby revived and -\nshall have full force and effect from the date of this\n3. All Acts or parts of Acts which are inconsistent\nwith the provisions of this Eecutive Order are hereby\nDone at the City of Landla, this joch _ day of\nMarch, in the year of our Lord, nineseen hundred and\nforty-five, and of the Comronwealth of the Philippines,\nSERGIO OSMENA\npresident of the Philippines\n5.\notary to the President"}}],"pack":"ph-p157"};
  FT["PH-H16835"] = {"id":"PH-H16835","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1947/eo_36_1947.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Annexing the Barrio of Marco of the Municipality of Allacapan, Province of Cagayan, to Barrio Centro, the Poblacion of Said Municipality","orig":"Annexing the Barrio of Marco of the Municipality of Allacapan, Province of Cagayan, to Barrio Centro, the Poblacion of Said Municipality"},"level":"law","status":"active","docNumber":"Executive Order No. 36","issuingBody":"President of the Philippines","promulgatedDate":"1947-01-04","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00036_1947_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00036_1947_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16835-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 36, January 04, 1947 ]\nANNEXING THE BARRIO OF MARCO OF THE MUNICIPALITY OF ALLACAPAN , PROVINCE OF\nCAGAYAN, TO BARRION CENTRO, THE POBLACION OF SAID MUNICIPALITY.\nUpon the recommendation of the Secretary of the Interior, and pursuant to the provisions of section sixty-eight\nof the Revised Administrative Code, the barrio of Marco in the municipality of Allacapan, Province of\nCagayan, is hereby annexed to and made a part of Barrio Centro, the Poblacion of the said municipality.\nThe change herein made shall take effect immediately.\nDone at the City of Manila, this 4th day of January, in the year of Our Lord, nineteen hundred and\nforty-seven, and of the Independence of the Philippines , the first.\n(Sgd.) MANUEL ROXAS\nPresident of the Philippines\nBy the President:\n(Sgd.) EMILIO ABELLO\nChief of the Executive Office"}}],"pack":"ph-p157"};
  FT["PH-H16836"] = {"id":"PH-H16836","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE LOANS AND INVESTMENT COUNCIL","orig":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE LOANS AND INVESTMENT COUNCIL"},"level":"law","status":"active","docNumber":"Executive Order No. 36","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00036_1963.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00036_1963.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16836-A1","no":1,"noLabel":{},"text":{"en":"to revew and coordinate the annual program of sources and\napplications of the funds of the member institutions, so as t\"\nshape them into an integl'ated annual program of captal transfer\nin full support of the Program;\n(d) To perform such other functions as 'will contribute\ntowards the attainment of the goals set .in the program.\n3. The Council is hereby authorized to have such per-\nsonnel as may be assigned or detailed ~o it fl'om member\ninstitutions, and to draw upon such amount as may ba\nneeded to carry out its duties and functio ns from such\navailable funds as may be needed for the JPurpose under\nexisting rules and regulations, subject to the approval'.\nof the President of the Philippines.\nDone in the City of Manila, this 19th day of March,\nin the year of Our Lord,. nineteen hundl:ed and· sixty-\n! \"\nBy the President:\nDroSDADO lVlA CAPAGAL\nPresident oj the Philippines\nSALVADOR L. 1v'IARINO\nExecu,tive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H16837"] = {"id":"PH-H16837","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1966/eo_36_1966.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating a Committee to Study the Rules and Regulations and Problems of Horse Racing","orig":"Creating a Committee to Study the Rules and Regulations and Problems of Horse Racing"},"level":"law","status":"active","docNumber":"Executive Order No. 36","issuingBody":"President of the Philippines","promulgatedDate":"1966-07-28","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00036_1966_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00036_1966_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16837-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 36, July 28, 1966 ]\nCREATING A COMMITTEE TO STUDY THE RULES AND REGULATIONS AND PROBLEMS OF\nHORSE RACING\nWHEREAS, many problems and controversies have arisen under the existing rules and regulations on horse\nWHEREAS, there is a need to study the present rules and regulations on horse racing, with a view to\nup-dating and improving the same so as to find a solution to those problems and controversies.\nNOW, THEREFORE, I, FERDINAND E. MARCOS, President of the Philippines, by virtue of the powers\nvested in me by law, do hereby create a committee to study the rules and regulations and problems on horse\nracing, composed of the following:\nPress Secretary Jose Aspiras\nGovernor Isidro Rodriguez\nAsst. Exec. Sec. Jose J. Leido, Jr.\nDirector Eduardo Cojuangco\nDirector Leonilo Ocampo\nJudge Antonio Paredes\nGovernor Manuel Barretto\nMr. Ramon Bagatsing\nThe Committee shall submit its report and recommendation to the President as soon as possible.\nThe Committee is hereby empowered to call upon any department, bureau, office, agency or instrumentality\nof the government for such assistance as it may need in the discharge of its functions.\nDone in the City of Manila, this 28th day of July, in the year of Our Lord, nineteen hundred and sixty-six.\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) RAFAEL M. SALAS\nExecutive Secretary"}}],"pack":"ph-p157"};
