  FT["PH-H16848"] = {"id":"PH-H16848","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"RESIDENCE {)F THE PRESIDEN'r OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE OREDER No. 37 FIXING OFFICE HOURS DURING THE HOT SEASON","orig":"RESIDENCE {)F THE PRESIDEN'r OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE OREDER No. 37 FIXING OFFICE HOURS DURING THE HOT SEASON"},"level":"law","status":"active","docNumber":"Executive Order No. 37","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00037_1963.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00037_1963.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16848-A1","no":1,"noLabel":{},"text":{"en":"afternoon. The provisions of this Order shall not apply\nto the offices in the City of Baguio, whether National,\nprovincial, or municipal.\nHowever, in the interest of the service, the heads of\ndepartments, bureaus, offices, agencies, and instrumenta-\nlities of the Government, including the provincial and\nmunicipal governments and all corporations owned or\ncontrolled by the Government, are enjoined to require at\nleast one-half of their personnel to be on duty in the\nDone in the City of Manila, this 20th day of March,\nin the year of Our Lord, nineteen hundred and sixty.\nBy the President:\nDIOSDADO MACAPAGAL\nPresident of the Philippines\nSALVADOR L. MARI:RO\nExecutive Secretary"}}],"pack":"ph-p157"};
