  FT["PH-H16990"] = {"id":"PH-H16990","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE PRESIDENT OF THO PILLIPPINES BY THE PROSIDDIT OS MUD PHILIPPINES EXECUTIVE ORDER IO. 50 REVOKING EXECUTIVE ORDER MO. 62 SATO? JANUARY 15,","orig":"MALACANANG RESIDENCE OF THE PRESIDENT OF THO PILLIPPINES BY THE PROSIDDIT OS MUD PHILIPPINES EXECUTIVE ORDER IO. 50 REVOKING EXECUTIVE ORDER MO. 62 SATO? JANUARY 15,"},"level":"law","status":"active","docNumber":"Executive Order No. 50","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00050_1966.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00050_1966.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16990-A1","no":1,"noLabel":{},"text":{"en":"have something to do with rice and corn production\nactively participate and cooperate in the implemen-\ntation of the Rice and Corn Froduction Program,\nThe Rice and Corn Production Coordinating\nCouno1 shell submit to the President regularly a\nreport on its activitios and accomplistents.\nDone in the City of Lanila, this 17th day of\nOctober, in the year of our Lord, nineteen hundred\nand sixty-six.\n(sGa,) FERDITAND D. MARCOS\nPresident of the Philippinga\nBy the President:\n(SGD.) RAPABL IS. SALAS\nExecutive Secretary\n103"}}],"pack":"ph-p157"};
