  FT["PH-H17054"] = {"id":"PH-H17054","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG EXECUTIVE ORDER NO. RULES APPLICABLE TO PROPERTY THAT CAN BE SOLD THROUGH PUBLIC AUCTION BY THE BUREAU OF CUSTOMS","orig":"MALACANANG EXECUTIVE ORDER NO. RULES APPLICABLE TO PROPERTY THAT CAN BE SOLD THROUGH PUBLIC AUCTION BY THE BUREAU OF CUSTOMS"},"level":"law","status":"active","docNumber":"Executive Order No. 56","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00056_1999.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00056_1999.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17054-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"All articles subject to sale under Sec. 2601 to 2612 of the\nCustoms and Tariff Code shall be sold in accordance with\nsection and with\nthe provisions\nof this Executive"}},{"id":"PH-H17054-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"No article\nto sale shall\nCommissioner\nhad submitted\nand their minimum\nbid price for the approval of\nthe Secretary of Finance."}},{"id":"PH-H17054-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Items/Lots\nunder Sec. 2 with minimum\nbid price of f)50\nMillion shall be subject to further approval by the President.\nOnly two public bid dings within ten (10)' days of each other,\nshall be held for the items/lots\napproved by the Secretary of\nFinance and/or the President for sale.\nAny change in the\nbid price shall be subject to the approval of the\nSecretary of Finance."}},{"id":"PH-H17054-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Within\nevery public\nCommissioner\nof Customs shall prepare and submit to the\nSecretary of Finance a list of items/lots\nthat were not sold\nafter two public auctions with a recommendation\ndistribution\nor further sale or disposition in accordance with\nthe Tariff and Customs Code.\nten (10) days from\nreceipt of the list and recommendation,\nthe Secretary of\nFinance shall submit its recommendation\nto the Office of\nthe President for approval.\n..\"\n\nSection 6~ REPEALI~G\n.All executive orders, administratiye\norders,' proclamations~ rules and regulations or parts thereof\nthat are inconsistent\nwith this Order are hereby repealed or\nmodified accordingly.'"}},{"id":"PH-H17054-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"SEPARABILITY\nIf any provision of this Executive\nOrder shall be held unconstitutional,\nthe other provisions\nshall not be affected."}},{"id":"PH-H17054-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"EFFECTIVITY.\nimmediately.\nThis Executive\nOrder shall take effect\nDone in the City of Manila this -day\nyear of our Lord Nineteen Hundred and Ninety-Nine.\n(==~:~:2~:=~\nJOSEPH EJERCITO ESTRADA\nPresident of the Republic of the Philippines\nBy the President:\n\"'-\n~\n--~\nRAMON B. CARDENAS\nActing Executive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H17055"] = {"id":"PH-H17055","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS• LIBRARY BY THE PRESIDENT OF THE PHILIPPINES ADOPTING THE COMPREHENSIVE PROGRAM FRAMEWORK FOR CHILDREN IN ARMED CONFLICT AND DIRECTING NATIONAL GOVERNMENT AGENCIES AND LOCAL GOVERNMENT UNITS TO IMPLEMENT THE SAME","orig":"MALACAÑANG PMS• LIBRARY BY THE PRESIDENT OF THE PHILIPPINES ADOPTING THE COMPREHENSIVE PROGRAM FRAMEWORK FOR CHILDREN IN ARMED CONFLICT AND DIRECTING NATIONAL GOVERNMENT AGENCIES AND LOCAL GOVERNMENT UNITS TO IMPLEMENT THE SAME"},"level":"law","status":"active","docNumber":"Executive Order No. 56","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00056_2001.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00056_2001.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17055-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Program Framework. The Comprehensive Program Framework\nfor Children in Armed Conflict, as approved by the CWC Board, is hereby adopted."}},{"id":"PH-H17055-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Lead Agency. The Office of the Presidential Adviser on the Peace\nProcess (OPAPP) is hereby directed to serve as lead agency in coordinating and\nmonitoring the implementation of this Program. The formulation of the implementing\nguidelines shall be done in coordination with involved government agencies."}},{"id":"PH-H17055-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Other Agencies & Organizations. National government agencies shall\ndevelop their respective annual plans, programs and projects consistent with the\nComprehensive Program Framework and in accordance with their mandates. The\nOPAPP shall periodically review these plans for purposes of policy and program\nsynchronization.\nLocal Government Units of areas affected by armed conflict may also develop\nand implement complementary programs to carry out the Comprehensive Program\nFramework in coordination with the OPAPP.\nThe involvement and participation of the private/business sector, NGOs, civil\norganizations, church-based organizations and private volunteer organizations with\nservices for children shall also be encouraged."}},{"id":"PH-H17055-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Funding. Funds for the implementation of this Program and its\ncomponents shall be taken from the existing funds of involved agencies. All agencies\ninvolved shall ensure that actual funds, services and/or activities equivalent to at least one\npercent (1%) of their annual MOO budget shall be appropriated for the implementation\nof this program.\nThe OPAPP shall likewise assist in providing funding assistance for the\nimplementation of specific program components and other related activities consistent\nwith its mandate, and in accordance with existing accounting and auditing regulations."}},{"id":"PH-H17055-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDone in the City of Manila, this 26th day of November\nof Our Lord, two thousand and one.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\n- /\nPMS LIBRARY\nPOMA Outgoing , 06870\nPMS LIBRARY BCODE002098"}}],"pack":"ph-p157"};
  FT["PH-H17056"] = {"id":"PH-H17056","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AUTHORIZING THE SECRETARY OF FINANCE TO ORDER THE OPENING OF INCOME TAX RETURNS OF SPECIFIC TAXPAYERS FOR INSPECTION TO EFFECTIVELY IMPLEMENT REPUBLIC ACT NUMBER 10021, OTHERWISE KNOWN AS THE \"EXCHANGE OF INFORMATION ON TAX MATTERS ACT OF 2009","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AUTHORIZING THE SECRETARY OF FINANCE TO ORDER THE OPENING OF INCOME TAX RETURNS OF SPECIFIC TAXPAYERS FOR INSPECTION TO EFFECTIVELY IMPLEMENT REPUBLIC ACT NUMBER 10021, OTHERWISE KNOWN AS THE \"EXCHANGE OF INFORMATION ON TAX MATTERS ACT OF 2009"},"level":"law","status":"active","docNumber":"Executive Order No. 56","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00056_2011.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00056_2011.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17056-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Delegated Authority. The authority to order the opening for\ninspection of the income tax returns of specific taxpayers subject of a request for\nexchange of information by a foreign tax authority pursuant to an international\nconvention or agreement on tax matters to which the Philippines is a signatory or\nparty thereof, is hereby delegated to the Secretary of Finance."}},{"id":"PH-H17056-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Issuance of Rules. The specific rules and regulations that\nshall govern the opening for inspection of income tax returns of specific\ntaxpavers subiect of a request for exchange of information by a foreign tax\nauthority shall be issued by the Secretary of Finance, upon the recommendation\nof the Commissioner of Internal Revenue."}},{"id":"PH-H17056-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Use and Confidentiality. Any information received by a\nforeign tax authority as a result of the opening for inspection of the income tax\nreturns of specific taxpayers subject of its request shall be treated by the\nauthority as absolutely confidential in nature in the same manner as information\nobtained by the latter under its laws and regulations and shall be disclosed only\nto persons or authorities, including courts and administrative bodies, involved in\nthe assessment or collection of, the enforcement or prosecution in respect of, or\nthe determination of appeals in relation to, the taxes covered by such\nconventions or agreements."}},{"id":"PH-H17056-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Separability Clause. If any provision of this Executive Order\nis declared invalid or unconstitutional, the other provisions not affected thereby\nshall remain valid and subsisting."}},{"id":"PH-H17056-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Repealing Clause. All orders, rules, regulations, and\nissuances, or parts thereof, which are inconsistent with this Executive Order, are\nhereby repealed, amended, or modified accordingly.\n@flice ofthe Prestbent otthe Philippines\n2"}},{"id":"PH-H17056-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Effectivity. This Executive Order shall take effect\nimmediately upon publication in a newspaper of general circulation.\nDONE, in the City of Manila, this 6th\nyear of Our Lord, Two Thousand and Eleven.\nday of September\n4\nBy the President:\nPAQUITO N_ /OCHOA, JR.\nExecutive Secretary\n@flice of the Present of the Philippines\n¡ CERTIFIED COPY:\nMARIANITO M. DIMAANDAL\nDIRECTOR IV\n41:1.9:11 99. 9, 204 MALACANANG RECOROS OFFICE\n3"}}],"pack":"ph-p157"};
  FT["PH-H17057"] = {"id":"PH-H17057","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":17,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES INSTITUTIONALIZING THE EMERGENCY 911 HOTLINE AS THE NATIONWIDE EMERGENCY ANSWERING POINT, REPLACING PATROL 117, AND FOR OTHER PURPOSES","orig":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES INSTITUTIONALIZING THE EMERGENCY 911 HOTLINE AS THE NATIONWIDE EMERGENCY ANSWERING POINT, REPLACING PATROL 117, AND FOR OTHER PURPOSES"},"level":"law","status":"active","docNumber":"Executive Order No. 56","issuingBody":"President of the Philippines","completenessNote":"全文，共 17 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00056_2018.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00056_2018.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17057-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Institutionalizing the Use of 911 as the Nationwide\nEmergency Hotline Number. The number \"911\" is hereby institutionalized as the\nNationwide Emergency Hotline Number, to be known as the Emergency 911 Hotline,\nreplacing the number \"117\""}},{"id":"PH-H17057-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"The Emergency 911 National Program. The Emergency 911\nNational Program shall consist of the following:\nThe Emergency 911 National Hotline Public Safety Answering Center\n(National Call Center) under the direction and control of the Department of the\nInterior and Local Government (DILG). The local government units (LGUs) are\nenjoined to establish and run local 911 call centers within their area of\njurisdiction using their own funds. These local 911 call centers shall, however,\nbe under the supervision of the National Call Center;\nThe Primary Service Responders composed of -\n1.\nBureau of Fire Protection (BFP) as the lead agency in conducting fire\nsuppression operations and providing the public with emergency medical\nservices, hazardous materials protection, and technical search and\nrescue services; and\n2. Philippine National Police (PP) as the lead agency in providing police\nassistance in relation to public safety and crime prevention;\nThe Major Support Service Responders, which shall provide appropriate and\nnecessary assistance and support to the Emergency 911 National Program,\nconsistent with their respective mandates, composed of -\n1.\nDepartment of Public Works and Highways (DPWH);\n2. Department of Health (DOH);\n3. Department of Transportation (DOTr);\n4. Armed Forces of the Philippines;\n5. National Bureau of Investigation;\n6. Bureau of Immigration;\n7. Philippine Coast Guard;\n8. Philippine Drug Enforcement Agency;\n9. Metropolitan Manila Development Authority (MMDA);\n2\n\n11. Accredited non-government organizations (NGOs), hospital and medical\ninstitutions and facilities, public safety volunteers, and such other\ninstitutions and facilities recommended by the Emergency 911\nCommission, as defined hereunder;\nThe respective roles and functions of the members of the Primary Service\nResponders and Major Support Service Responders shall be specified in the\nImplementing Rules and Regulations of this Order;\nThe establishment of the National Call Center shall be with the participation of\nexisting private communication carriers and telecommunications companies;\nAll private communication carriers and telecommunications companies shall\nensure and provide uninterrupted connectivity and integration of all calls made\nby their subscribers to the Emergency 911 Hotline: and\nIn addition to the Emergency 911 Hotline, the Emergency 911 Commission\nmay set-up such other relevant communication channels (e.g., short\nmessaging service, online platform and social media) to be integrated and/or\ninterconnected with the National Call Center."}},{"id":"PH-H17057-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Free Service to the Calling Public. The Emergency 911\nCommission shall ensure that all calls made to the Emergency 911 Hotline shall be\nfree of charge and other fees."}},{"id":"PH-H17057-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"The Emergency 911 Commission. The PATROL \"117\"\nCommission created under EO No. 226 and AO No. 36 is hereby replaced by the\nEmergency 911 Commission, which shall serve as the policy-making body and\noverseer of the Emergency 911 National Program, and shall be composed of the\nfollowing members:\nDILG Secretary, as Chairperson;\nDepartment of Information and Communications Technology (DICT)\nSecretary, as Vice Chairperson;\nRepresentatives of the following government agencies and organizations, with\na rank not lower than Director IV or its equivalent, as members:\n1. Office of the President:\n2. Department of Justice;\n3. Department of National Defense;\n4. Department of Social Welfare and Development;\n7. Presidential Communications Operations Office;\n3\n\nd. President of the Union of Local Authorities of the Philippines; and\nTwo (2) other members, with a term of two (2) years, to be selected by the\nChairperson from the private sector upon recommendation of the Emergency\n911 Commission."}},{"id":"PH-H17057-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Functions of the Emergency 911 Commission. The following\nare the functions of the Emergency 911 Commission:\nProvide policy direction and formulate necessary guidelines in the\nimplementation and supervision of the Emergency 911 National Program;\nPrepare and recommend to the President, through the Executive Secretary,\npolicies, measures, thrusts, and solutions that are responsive to crime\nprevention, and public order and safety issues;\nSubmit to the President, through the Executive Secretary, a semi-annual\nreport on the implementation of this Order; and\nPerform such other duties and functions as the President may direct."}},{"id":"PH-H17057-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"The Emergency 911 National Office. The existing PATROL\n\"117\" Development Office shall be renamed as the Emergency 911 National Office.\nUnder the direction of the Emergency 911 Commission, the Emergency 911\nNational Office shall function as the primary implementing office of the Emergency\n911 National Program. It shall be headed by an Executive Director with the rank of\nDirector IV, to be appointed by the President, upon recommendation of the DILG\nEmergency 911 Regional Offices may be established, as may be deemed\nnecessary by the Emergency 911 Commission, for the effective implementation of\nThe Emergency 911 National Office and, whenever necessary, its Regional\nOffices, shall have an organizational structure and staffing pattern that is appropriate\nto its functions and necessary for its operability."}},{"id":"PH-H17057-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Functions of the Emergency 911 National Office. The\nEmergency 911 National Office shall have the following functions:\nAct as the Secretariat of the Emergency 911 Commission;\nServe as the implementing arm of the Emergency 911 Commission in carrying\nout the objectives of this Order;\n\nInstitutionalize localized networks of service responders upon the direction of\nthe Emergency 911 Commission;\nConduct reviews and readiness tests, and monitor and evaluate the response\ncapabilities of various aspects of the Emergency 911 National Program;\nDevelop and implement training programs for emergency communications\npersonnel and responders;\nProcess accreditation of NGOs, hospital and medical institutions and facilities,\nand other civic sector institutions, facilities, and volunteers in line with the\nobjectives of this Order; and\ng. Undertake such other duties as the Emergency 911 Commission may direct."}},{"id":"PH-H17057-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Cooperation of all Government Agencies and LGUs. All\nagencies and instrumentalities of the Government are hereby directed and LGUs are\nhereby enjoined to provide the necessary assistance for the effective implementation\nof this Order."}},{"id":"PH-H17057-A9","no":9,"noLabel":{"en":"SECTION 9"},"text":{"en":"Participation of the Private Sector. The private sector is\nencouraged to actively participate in whatever capacity in the implementation of this\nOrder, and to advocate crime prevention, public order, and public safety."}},{"id":"PH-H17057-A10","no":10,"noLabel":{"en":"SECTION 10"},"text":{"en":"Fraudulent, Hoax or Prank Reports. All fraudulent, hoax, or\nprank reports shall be dealt with in accordance with existing and applicable laws,\nrules, regulations and the implementing rules and regulations of this Order."}},{"id":"PH-H17057-A11","no":11,"noLabel":{"en":"SECTION 11"},"text":{"en":"Implementing Rules and Regulations. The DILG, with the\nassistance of the other members of the Emergency 911 Commission, shall formulate\nand issue the appropriate Implementing Rules and Regulations within sixty (60) days\nafter the issuance of this Order."}},{"id":"PH-H17057-A12","no":12,"noLabel":{"en":"SECTION 12"},"text":{"en":"New Organizational Structure and Staffing Pattern. The\nEmergency 911 National Office shall review and modify, as may be necessary, its\nexisting organizational structure and staffing pattern to effectively and efficiently\ncarry out the functions prescribed herein, subject to the approval by the Department\nof Budget and Management (DBM).\nPending the approval and setting up of the new organizational structure and\nstaffing pattern, the Emergency 911 National Office shall retain all existing positions\nof the Patrol \"117\" Development Office."}},{"id":"PH-H17057-A13","no":13,"noLabel":{"en":"SECTION 13"},"text":{"en":"Funding. Subject to pertinent laws, rules, and regulations, the\ninitial funding requirements for the implementation of this Order shall be chargeable\nto the Fiscal Year 2018 budget of the 911 Emergency Services, and may be\naugmented upon recommendation of the DBM. Appropriations for the succeeding\nyears shall be incorporated in the budget proposal of the DILG.\n5\n\nSubject to Section 3, the operations of local 911 call centers established by\nLGUs shall be chargeable to their respective budgets.\nThe service responders shall shoulder their own expense in support of the\nEmergency 911 National Program."}},{"id":"PH-H17057-A14","no":14,"noLabel":{"en":"SECTION 14"},"text":{"en":"Transitory Provision. The members of the Patrol \"117\"\nCommission shall ensure the smooth and complete transition to the above-stated\ncomposition of the Emergency 911 Commission, and of the Patrol 4117%\nDevelopment Office to the Emergency 911 National Office, within sixty (60) days\nfrom the effectivity of this Order. In no case shall the delivery of services under the\nEmergency 911 Hotline be disrupted by reason of such transition.\nNevertheless, pending approval of arrangements necessary for the full\nimplementation of this Order, the existing rates and fees charged on calls to existing\n911 platforms, if any, shall continue to apply."}},{"id":"PH-H17057-A15","no":15,"noLabel":{"en":"SECTION 15"},"text":{"en":"Repeal. EO No. 226 and AO No. 36 and all other issuances,\norders, rules and regulations or parts thereof which are inconsistent with the\nprovisions of this Order are hereby amended, repealed, or modified accordingly."}},{"id":"PH-H17057-A16","no":16,"noLabel":{"en":"SECTION 16"},"text":{"en":"Separability. If any provision of this Order is declared invalid or\nunconstitutional, the other provisions not affected thereby shall remain valid and\nsubsisting."}},{"id":"PH-H17057-A17","no":17,"noLabel":{"en":"SECTION 17"},"text":{"en":"Effectivity. This Order shall take effect immediately upon its\npublication in a newspaper of general circulation.\nDONE in the City of Manila, this 25thday of May\nLord, Two Thousand and Eighteen.\nin the year of our\nBy the President:\nMICHAEL P. ONG\nActing Executive Secretary\n6\nOffice of the President\nMALACAÑANG RECORDS OFFICE\n•\nATTY. CONCEPCIONZSAY E. FERROLTO-ERAD\n4 820-2581\nDIRECTOR NO\nREPUBLIC OF THE PHILIPPINES"}}],"pack":"ph-p157"};
  FT["PH-H17058"] = {"id":"PH-H17058","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo2024/eo_56_2024.html","fetchedAt":"2026-10-28","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"Strengthening the Philippines Maritime Security and Maritime Domain Awareness (Ferdinand Marcos, Jr. Bongbong)","orig":"Strengthening the Philippines Maritime Security and Maritime Domain Awareness (Ferdinand Marcos, Jr. Bongbong)"},"level":"law","status":"active","docNumber":"Executive Order No. 56","issuingBody":"President of the Philippines","promulgatedDate":"2024-03-25","completenessNote":"全文，共 8 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00056_2024_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00056_2024_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17058-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Government Officials Authorized to Use Protocol License Plates. The following government\nofficials are hereby authorized to use protocol license plates:\nASSIGNED NUMBER\nPresident of the Republic of the Philippines\n1 and/or PANGULO\nVice President of the Republic of the Philippines\n2\nSenate President\n3\nSpeaker of the House of Representatives\n4\nChief Justice of the Supreme Court\n\n5\nCabinet Secretaries\n6\n7\nMembers of the House of Representatives\n8\nAssociate Justices of the Supreme Court\n9\nPresiding Justice of the Court of Appeals (CA), Court of Tax Appeals (CTA) and Sandiganbayan, and\nSolicitor General\n10\nChairpersons of Constitutional Commissions and Ombudsman\n11\nChief of Staff of the Armed Forces of the Philippines and Chief of Philippines National Police\n14\nAll other officials with equivalent rank as the above authorized officials may be allowed to use protocol\nlicense plates, upon the recommendation of the Land Transportation Office (LTO), approval of the Secretary\nof the Department of Transportation (DOTr), and based on the list of all officials with equivalent rank as the\nabove authorized officials of the Department of Budget and Management.\nThe Associate Justices of the CA, CTA, and Sandiganbayan may also be allowed to use protocol license plates\nupon the recommendation of the LTO and approval of the Secretary of the DOTr. However, this shall not be\nconstrued to authorize all other officials with equivalent rank as the Associate Justices of the CA, CTA and\nSandiganbayan and below to use protocol license plates."}},{"id":"PH-H17058-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Validity. Protocol license plates issued to authorized officials shall be valid only during their\nincumbency and may only be used for motor vehicles duly registered in their name and/or officially assigned\nto them. For this purpose, all protocol license plates issued to authorized government officials shall be\nsurrendered to the LTO upon retirement, resignation, separation from office, or end of term or tour of duty.\nAll previously-issued protocol license plates issued pursuant to EO No. 400, as amended, except those issued\nto incumbent authorized officials under Section 1 hereof, are deemed expired. The LTO in coordination with\nconcerned agencies, is hereby directed to revoke and/or confiscate all expired protocol license plates, subject\nto existing laws, rules and regulations.\nThe assignment and/or transfer of protocol license plates to unauthorized persons and/or motor vehicles is\nstrictly prohibited. Violation of this prohibition, as well as the unauthorized use of protocol license plates,\nshall be sufficient cause for the revocation of the herein granted authority, confiscation of issued protocol\nlicense plates, and imposition of appropriate penalty, including administrative sanction, pursuant to existing\nlaws, rules and regulations."}},{"id":"PH-H17058-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Quantity. All authorized government officials may be allowed a maximum of two (2) pairs of\nprotocol license plates. However, the President, Vice President, Senate President, Speaker of the House of\nRepresentatives, and Chief Justice of the Supreme Court may be allowed a maximum of three (3) pairs of\nprotocol license plates."}},{"id":"PH-H17058-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Registry of Protocol License Plates. The DOTr is hereby directed to develop and maintain a\n\nregistry of protocol license plates issued to all authorized government officials and/or motor vehicles."}},{"id":"PH-H17058-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Implementing Guidelines. Within thirty (30) days from the effectivity of this Order, the DOTr\nand LTO shall formulate and issue guidelines for the effective implementation hereof, which shall include the\nrequirements and process for application, approval, issuance, return, and confiscation of protocol license\nplates, among other. The DOTr and LTO shall ensure that the Implementing Guidelines will not in any way\nexpand the list of officials authorized to use protocol license plates."}},{"id":"PH-H17058-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Separability. If any any section or part of this Order is declared unconstitutional or invalid, the\nother sections or provisions not otherwise affected shall remain in full force and effect."}},{"id":"PH-H17058-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Repeal. EO NO. 400, as amended, is hereby repealed. All other issuances, orders, rules and\nregulations, or parts thereof that are inconsistent with this Order, are hereby repealed or modified accordingly."}},{"id":"PH-H17058-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Effectivity. This Order shall take effect immediately after its publication in the Official Gazette\nor in a newspaper of general circulation.\nDONE, in the City of Manila, this 25th day of March, in the year of our Lord, Two Thousand and\nTwenty-Four.\n(Sgd.) FERDINAND R. MARCOS, JR.\nBy the President:\n(Sgd.) LUCAS P. BERSAMIN\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H17059"] = {"id":"PH-H17059","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1936/eo_57_1936.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Establishing Reserve Officers Training Units in the Philippines","orig":"Establishing Reserve Officers Training Units in the Philippines"},"level":"law","status":"active","docNumber":"Executive Order No. 57","issuingBody":"President of the Philippines","promulgatedDate":"1936-10-14","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00057_1936_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00057_1936_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17059-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 57, October 14, 1936 ]\nESTABLISHING RESERVE OFFICERS’ TRAINING UNITS IN THE PHILIPPINES\nBy virtue of the powers vested in me by the National Defense Act, I, Manuel L. Quezon, President of the\nPhilippines, hereby authorize the establishment and maintenance of Reserve Officers’ Training Units in the\nuniversities and colleges indicated below:\nAdamson School of Industrial Chemistry and Engineering, Manila\nDe la Salle College, Manila\nPhilippine Normal School, Manila\nPhilippine School of Arts and Trades, Manila\nSan Beda College, Manila\nSilliman University, Dumaguete, Negros Oriental\nUniversity of Santo Tomas, Manila"}}],"pack":"ph-p157"};
  FT["PH-H17060"] = {"id":"PH-H17060","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MAL AC AT ANG RESIDENCE OF THE PRESIDENT OF THE PEILIPPINES BY THE PRESIDEIT OF THE PRILIPPINES EXECUTIVE OKDER NO. 57 CREATI G THE COMMUNITY DEVELOPMENT PLANNING COM CIL AND DEFINING ITS FUNCTIOL'S AND ACTIVITIES.","orig":"MAL AC AT ANG RESIDENCE OF THE PRESIDENT OF THE PEILIPPINES BY THE PRESIDEIT OF THE PRILIPPINES EXECUTIVE OKDER NO. 57 CREATI G THE COMMUNITY DEVELOPMENT PLANNING COM CIL AND DEFINING ITS FUNCTIOL'S AND ACTIVITIES."},"level":"law","status":"active","docNumber":"Executive Order No. 57","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00057_1954.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00057_1954.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17060-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"There is horchy created an advisory body to ho\nknown as the Community Development Planning Council.\nThe Council\nshall he composed of the Chairman of the Naticol Eernomic Council,\nas Chairman, the Executive Secretary, the Secretary of Agriculture\nand Natural Rescurces, the Secretary of Health, the Secretary of\nEducation, the Secretary of Public Works and Communications, the\nSecretery of Natical Defense, the Social Telfore Administrator,\nand three (3) private citizons who shall he appcinted by the Presi-\ndent and who sholl hold their positions at his pleasure, as members,\nThe Chairman shall preside at the meetings of the\nCouncil, and in his absence, the member prosent who is the ranking\nSecretary of Department shall preside,\nIn his absence the Chairman\nmay desimate his representative to attend the meetings of the\nEach Secretary or Head of Department or other office of the\nGovernment who is an ex-officio member of the Council may desimate\nhis representative to attend the meetings of the Council in his absence,"}},{"id":"PH-H17060-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"The Council shall have the following functions and\nactivities:\n(1) To formulate short and long range plans and institute\nmossures in cooperation with existing agencies, colculated to\n1mprove the rural economy and the proper utilization of manprver;\nImprove health and promote healthful livinz; promote community\norganization; develop youth and rural leadership; promote spirit\nof self-help, self-reliance and self-respect; and' improvo com-\nmunity facilities.\n(2) To coordinate and, if feasihlo,\n, Integrate the activities\nof the different branches, instrumentalitios and agencies of the\ngovernment er cored in rural development projects in order to achiere\n\n- 2 -\nmaximum benefits, effect economy, avoid duplication and overlapping\nof activities and loss of time.\n(3) To bring as much as possible every facility of the govern-\nment and of civic organizations into play for the effective im-\nplementation of a natich-wide program for rural community development,\n(4) To study and recommend legislation tending to improve the\nrural areas and pecple, especially that relating to the financing of\nrural projects and the strengthening of local government.\n(5) To promote and facilitate the organization of community\ndevelopment ccuncils at provincial, municipal and barrio levels\nand to help promote their growth and development,\n(6) To submit annual reports of Its activities cr any other\nreports which the President may require from time to time,\n(7) To administer wisely and judiciously the funds assigned\nto it by the Fresident.\n(8) To organize an administrative machinery for the proper\nfunctioning of the Council,\nThe Council shall coordinate its community develonment\nactivities with the nation-wide development program of the National\nEconomic Council and shall solicit the advice of the latter in mat-\nters Invclving policy, planning, programming and finencing of projects.\nThe Council Is hereby authorized to create local Councils\nto assist in the performance of its functions and to adopt such rules\nand regulations as it may deem necessary to carry out the purposes\nof this Order.\nIt may secure the services of officers and emplovees\nof any department, bureau, office, agency, or instrumentality of the\nGovernment, Including corporations owned or controlled by it, whose\nassistance it may require in accomplishing its task.\nDone in the City of Manila, this 16th day of August, in the\nyear of Our Lord, nineteen hundred and fifty-four, and of the\nIndependence of the Philippines, the ninth.\n(SGD.) RAMON MAGSAYSAY\nPresident of the Philippines\nBy the President:\n(SGD.) FRED RUIZ CASTRO\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H17061"] = {"id":"PH-H17061","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE PRESIDENT","orig":"MALACANANG RESIDENCE OF THE PRESIDENT"},"level":"law","status":"active","docNumber":"Executive Order No. 57","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00057_1963.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00057_1963.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17061-A1","no":1,"noLabel":{},"text":{"en":"4. The Vice-President shall represent the President in\nsocial functions requiring the present:e of the latter and\nshall preside over official ceremonies, receive and return\nthe official calls of foreign dignitaries in behalf and in\nrepresentation of tha President, and on such occasions the\n028752\nVice-President shall be entitled to the honors and court-\nesies due the President of the Philippines.\nDone in the City of Manila, this 24th day of November,\nin the year of Our Lord, nineteen hundred and sixty-three.\nBy the President:\nSALVADOR L. MARINO\nDrosDADo MACAPAGAL\nPre8ident of the Philippines\nActing Executive Secr'eta,ry"}}],"pack":"ph-p157"};
