  FT["PH-H17401"] = {"id":"PH-H17401","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"EXECUTIVE ORDER NO. AMENDING EXECUTIVE","orig":"EXECUTIVE ORDER NO. AMENDING EXECUTIVE"},"level":"law","status":"active","docNumber":"Executive Order No. 88","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00088_1993.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00088_1993.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17401-A1","no":1,"noLabel":{},"text":{"en":"103\n1986\ncoordinate\nReconciliation\nDevelopment\ntheGovernme\nimplementation\nWHEREAS, the\nPresidential\nthe mandate of the NRDC.\nPhilippines,\n1.\ntransferred\nNa1:.ional Reconciliation\nand Development\nfrom the ~~jonal\nUnification\nCommission:\n4,000\napplicants\napplications\nforamnesty,\n31\n1992,\nundergoing\nprocessing;\n(} ') , 82\n(\nvoluntarily\nsought amnesty:\napplicants\nperformance\n2.\nassistfunctions.\n3.immediately.\nDONE in the city\n~~\nday of May in the\nyear of Our Lord,\nNineteen Hundred and Ninety-Three.\n1~~\n,,; ,\nPresidential\nPMS lIBRARY\n..."}}],"pack":"ph-p157"};
  FT["PH-H17402"] = {"id":"PH-H17402","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER N°.8 8 RICE ALLOWANCE TO SOLDIERS COMBAT DUTY IN MINDANAO","orig":"BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER N°.8 8 RICE ALLOWANCE TO SOLDIERS COMBAT DUTY IN MINDANAO"},"level":"law","status":"active","docNumber":"Executive Order No. 88","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00088_1999.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00088_1999.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17402-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The NFA, DBM and the AFP shall jointly formulate the\nguidelines\nto implement\nidentification\nto the rice allowance and the system of\ndistribution.\n, ..,\n\n."}},{"id":"PH-H17402-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This order shall'take effect immediately.\nDone in the City of Manila, this ~\nday of April in the year of o~r\nLord, Nineteen Hundred and Ninety Nine.\n~~\n\"\n\"'\nEJERCITO ESTRADA\nBy the President:\nIIIIIIIIIIIIIIII!IIIIIIIIIIIII\nPJEEHologram'4100\n~\nRONALDO B. ZAMORA\nExecu tive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H17403"] = {"id":"PH-H17403","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES PMS LIBRARY MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE PREFERENTIAL TARIFF RATES ON CERTAIN PRODUCTS UNDER THE ASEAN INDUSTRIAL COOPERATION (AICO) SCHEME, IN FAVOR OF MITSUBA PHILIPPINES CORPORATION (MPC)","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES PMS LIBRARY MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE PREFERENTIAL TARIFF RATES ON CERTAIN PRODUCTS UNDER THE ASEAN INDUSTRIAL COOPERATION (AICO) SCHEME, IN FAVOR OF MITSUBA PHILIPPINES CORPORATION (MPC)"},"level":"law","status":"active","docNumber":"Executive Order No. 88","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00088_2002.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00088_2002.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17403-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The articles specifically listed in Annex \"A\" hereof, as classified\nunder Section 104 of the Tariff and Customs Code of 1978, as amended, shall be\naccorded the AICO rate of 3% as specified in the Column 5 thereof."}},{"id":"PH-H17403-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"The AICO rate provided in Annex \"A\" shall be accorded to the AICO\nentity in Thailand (Thai Summit Mitsuba Mfg. Co. Ltd.) effective 04 July 2001.\nPOMA Outgoing * 09487\n\n2"}},{"id":"PH-H17403-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"In the event that any subsequent changes are made in the basic (Most\nFavored Nation) Philippine rate of duty on any of the articles listed in Annex \"A\" to a\nrate lower than the AICO rate prescribed in Column 5 of Annex \"A\", such articles shall\nautomatically be accorded the corresponding reduced rate of duty. Effective 01 January\n2003, the final CEPT rate on the article shall apply."}},{"id":"PH-H17403-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Upon the effectivity of this Executive Order, the articles specifically\nlisted in the aforesaid Annex \"A\" which are entered or withdrawn from warehouses in the\nPhilippines for consumption shall pay the applicable AICO preferential tariff rate\nspecified under Section 1 hereof, subject to qualification under the Rules of Origin for the\nCEPT, as evidenced by the Certificate of Origin - Form \"D\"."}},{"id":"PH-H17403-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"The Secretary of Finance in consultation with the National Economic &\nDevelopment Authority (NEDA) shall issue the appropriate guidelines to implement and\nrationalize the preferential tariff privilege herein granted."}},{"id":"PH-H17403-A6","no":6,"noLabel":{"en":"SEC 6"},"text":{"en":"This Executive Order shall take effect immediately.\nDONE in the Citv of Manila, this 18th.\n\" day of March\nin the year of\nOur Lord, two thousand and two.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPOMA Outgoing * 09488\nPMS LIBRARY BCODEOO\n\nARTICLES GRANTED PREFERENTIAL TARIFF UNDER\nTHE APPROVED MITSUBA AICO SCHEME\n(2)\n(4)\nAPPLICABLE\nPREFERENTIAL\n(5)\n(1)\n85.12\n(3)\nXXX; windscreen wipers; defrosters\nand demisters, of a kind used for cycles\nor motor vehicles\n8512.40 00 Wiper Assy Wiper motor components (CF)\n8512.40 00 Wiper Assy Wiper motor components (City)\n8512.90 00 WIper Assy Various component parts:\n(Thai Summit\nMitsuba Mig.\n(Thai Summit\nMitsuba Mfg.\n(Thai Summit\nMitsuba Mig.\n3"}}],"pack":"ph-p157"};
  FT["PH-H17404"] = {"id":"PH-H17404","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE JAGNA PORT ZONE AND PLACING IT UNDER THE ADMINISTRATIVE JURISDICTION OF THE PHILIPPINE PORTS AUTHORITY (PPA)","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE JAGNA PORT ZONE AND PLACING IT UNDER THE ADMINISTRATIVE JURISDICTION OF THE PHILIPPINE PORTS AUTHORITY (PPA)"},"level":"law","status":"active","docNumber":"Executive Order No. 88","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00088_2012.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00088_2012.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17404-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Port of Jagna. The territorial jurisdiction of the Port of Jagna\nsituated in the Municipality of Jagna, Province of Bohol, is hereby delineated,\nparticularl described as follows:\nBeginning at a point marked 1 on the plan, thence:\n888\n30'\n00'\n00'\n00'\n30'\n30'\n26'\n45\n41'\n20\n44'\n00'\n00'\n00'\n00'\n00'\n30'\n30'\n30'\nffice of the Bresident ofthe Bail nines\n\n00'\n00'\n00'\n10.00 m. to point of beginning,\ncontaining an area of FOUR HUNDRED SIXTY-FOUR THOUSAND SIX HUNDRED\nTHIRTY-NINE SQUARE METERS\nAND NINETY SQUARE DECIMETERS\n(464,639.90), more or less."}},{"id":"PH-H17404-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"PPA Jurisdiction. The Jagna Port Zone, as delineated, is hereby\nplaced under the administrative jurisdiction of the PPA, which shall, consistent with the\nregional industrial plans of the government, implement a program for the proper zoning,\nplanning, development and utilization of the port."}},{"id":"PH-H17404-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Repeal. All issuances, orders, rules and regulations, or parts\nthereof, which are inconsistent with this Executive Order are hereby repealed, amended\nor modified accordingly."}},{"id":"PH-H17404-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Separability. If any provision of this Executive Order is declared\ninvalid or unconstitutional, the other provisions not affected thereby shall remain valid\nand subsisting."}},{"id":"PH-H17404-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately upon\npublication in a newspaper of general circulation.\nDONE, in the City of Manila, this Ist day of October\nLord. Two Thousand and Twelve.\n, in the year of our\nBy the President:\nPAQUITO N. OCHOA, JR.\nExècutive Secretary\nCERTIFIED COPY.\n@ltice of the President of the Philipines\n2\nMARIANITO M. OIMAANDAL\nDIRECTOR IV\nMALACARANG RECORDS OFFICE"}}],"pack":"ph-p157"};
  FT["PH-H17405"] = {"id":"PH-H17405","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES REDUCTION AND CONDONATION OF REAL PROPERTY TAXES AND INTEREST/PENALTIES ASSESSED ON THE POWER GENERATION FACILITIES INDEPENDENT POWER PRODUCERS UNDER BUILD-OPERATE-TRANSFER CONTRACTS WITH GOVERNMENT-OWNED OR -CONTROLLED CORPORATIONS","orig":"MALACANAN PALACE BY THE PRESIDENT OF THE PHILIPPINES REDUCTION AND CONDONATION OF REAL PROPERTY TAXES AND INTEREST/PENALTIES ASSESSED ON THE POWER GENERATION FACILITIES INDEPENDENT POWER PRODUCERS UNDER BUILD-OPERATE-TRANSFER CONTRACTS WITH GOVERNMENT-OWNED OR -CONTROLLED CORPORATIONS"},"level":"law","status":"active","docNumber":"Executive Order No. 88","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00088_2019.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00088_2019.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17405-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Reduction and Condonation. All liabilities for real property tax,\nincluding any special levies accruing to the Special Education Fund, for calendar year\n(CY) 2018, on property, machinery and equipment actually and directly used by IPPs\nfor the production of electricity under a Build-Operate-Transfer scheme and similar\ncontracts (whether denominated Power Purchase Agreements, Energy Conversion\nAgreements or other contractual agreements) with GOCCs, assessed by LGUs and\nother entities authorized to impose real property tax for all years up to CY 2018, are\nhereby reduced to an amount equivalent to the tax due if computed based on an\nassessment level of fifteen percent (15% of the fair market value of said property,\nmachinery and equipment depreciated at the rate of two percent (2%) per annum, less\nany amounts already paid by the IPPs. All interests on such deficiency real property\ntax liabilities are also hereby condoned and the concerned IPPs are relieved from\npayment thereof."}},{"id":"PH-H17405-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Application to future real property tax liabilities. All real property\ntax payments made by the IPs over and above the reduced amount under Section 1\nof this Order shall be applied to their real property tax liabilities for the succeeding"}},{"id":"PH-H17405-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Compliance by all Government Entities. All concerned\ndepartments, agencies and instrumentalities of the government, including relevant\nGOCCs and LGUs, are hereby ordered to strictly comply with this Order."}},{"id":"PH-H17405-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Repeal. All rules and regulations, or parts thereof which are\ninconsistent with the provisions of this Order are hereby revoked, amended or modified\naccordingly."}},{"id":"PH-H17405-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Separability. If any provision of this Order is declared invalid or\nunconstitutional, the other provisions unaffected thereby shall remain valid and\nsubsisting."}},{"id":"PH-H17405-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Effectivity. This Order shall take effect immediately upon its\npublication in a newspaper of general circulation.\nDONE, in the City of Manila, this 13th day of August\nLord, Two Thousand and Nineteen.\nthe year of Our\nBy the President:\nSALVADOR C. MEDIALDEA\nExecutive Secretary\n2\nOffice of the Resident\nMALACAÑANG RECORDS OFFICE\nREPUBLIC OF THE PHILIPPINES\nVATTY. CONCEPCION ZENY E. FERROLINO-ERAD\n8845-209\nDIRECTOR IV"}}],"pack":"ph-p157"};
  FT["PH-H17406"] = {"id":"PH-H17406","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES STRENGTHENING THE NATIONAL TASK FORCE DIWALWAL","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES STRENGTHENING THE NATIONAL TASK FORCE DIWALWAL"},"level":"law","status":"active","docNumber":"Executive Order No. 88","issuingBody":"President of the Philippines","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00088_2025.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00088_2025.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17406-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Reconstitution of National Task Force Diwalwal. The National\nTask Force Diwalwal is hereby reconstituted. The Task Force shall be composed of\nthe following:\nChairperson\nSecretary, DENR\nRepresentative, Office of the President;\nSecretary, Department of National Defense;\nSecretary, Department of the Interior and Local Government; and\nChairperson, Mindanao Development Authority.\nThe Chairperson and members of the Task Force may designate their\nrespective alternates, with ranks not lower than Assistant Secretary or its equivalent,\nwho shall be fully authorized to decide for or on their behalf."}},{"id":"PH-H17406-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Duties and Functions. The Task Force shall have the primary duty\nof overseeing all mining activities in the DMA, with the end in view of creating an\nenvironment conducive to lasting peace and sustainable development in the DMRA.\nFor this purpose, the Task Force shall perform the following duties and functions,\nsubject to existing laws, rules and regulations:\nOversee the implementation of all government programs, activities and projects\nfor the rehabilitation and development of the DMRA;\nOperationalize and coordinate effective and timely execution of measures to\nregulate and rationalize all mining activities in the DMRA. For this purpose, the\nTask Force shall conduct an inventory and evaluation of all mining activities and\ntenements in the DMRA, particularly those entered into and/or under the\nmanagement of PMDC. In this regard, the Task Force shall oversee and monitor\nPMDC's mining activities in the DMRA;\nStudy and implement measures and ways forward, subject to applicable laws,\nrules and regulations, to address all issues and concerns affecting the\nrehabilitation and development of the DMRA. This may include, among others: (0)\nformulating a comprehensive plan which shall serve as the strategic framework to\npromote environmental and ecological protection of the area and raise awareness\namong stakeholders regarding issues and concerns in the DMRA, as well as the\nefforts of the government to address the same; (il) as may be necessary,\ntransferring the remaining mining tenements in DMRA, if any, from PMDC to the\nNatural Resources and Development Corporation; and (I) issuing the necessary\nimplementing guidelines for the effective implementation of this Order;\nInvite, collaborate, and establish institutional partnerships with concerned\ngovernment agencies and the private sector, including non-government\norganizations and other stakeholders, to ensure the effective performance of its\nduties and functions;\nAs may be necessary, create, convene, and reorganize committees or technical\nworking groups to assist in the implementation of this Order;\n2\n\nSubmit to the Office of the President, through the Office of the Executive\nSecretary, annual reports on the implementation of this Order; and\ng. Perform such other functions as may be directed by the President and/or the\nExecutive Secretary."}},{"id":"PH-H17406-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Convergence. All concerned government agencies are hereby\ndirected, and all local government units within the Province of Davao de Oro and the\nprivate sector are hereby encouraged, to render full support to and cooperation with\nthe Task Force to ensure the effective implementation of this Order."}},{"id":"PH-H17406-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Funding. The funding requirements for the initial implementation of\nthis Order shall be charged against the existing appropriations of the\nmember-agencies of the Task Force, subject to relevant budgeting, accounting, and\nauditing laws, rules and regulations. Thereafter, the subsequent funding requirements\nfor the purpose shall be included in the budget proposals of said member-agencies,\nsubiect to the usual budget preparation process."}},{"id":"PH-H17406-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Separability. If any part or provision of this Order is held invalid or\nunconstitutional, the provisions not affected thereby shall remain in full force and"}},{"id":"PH-H17406-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Repeal. All issuances, orders, rules and regulations, or parts\nthereof, that are inconsistent with this Order, are hereby repealed or modified\naccordingly."}},{"id":"PH-H17406-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Effectivity. This Order shall take effect immediately upon its\npublication in the Official Gazette or a newspaper of general circulation.\nDONE, in the City of Manila, this\nyear of Our Lord, Two Thousand and Twenty-Five.\nBy the President:\nShermilair\nLUCAS P. BERSAMIN\nExecutive Secretary\n3\nMALE TIGERS HEIGHNEI\nPOTENTINO-NAVA\nMEA 670925 DIRECTOR IV"}}],"pack":"ph-p157"};
  FT["PH-H17407"] = {"id":"PH-H17407","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1937/eo_89_1937.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Prescribing Regulations Regarding Transportation Allowances of Provincial and City Government Officials and Employees and Revoking Executive Order No. 457 Series of 1933.","orig":"Prescribing Regulations Regarding Transportation Allowances of Provincial and City Government Officials and Employees and Revoking Executive Order No. 457 Series of 1933."},"level":"law","status":"active","docNumber":"Executive Order No. 89","issuingBody":"President of the Philippines","promulgatedDate":"1937-01-23","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00089_1937_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00089_1937_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17407-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 89, January 23, 1937 ]\nPRESCRIBING REGULATIONS REGARDING TRANSPORTATION ALLOWANCES OF PROVINCIAL\nAND CITY GOVERNMENT OFFICIALS AND EMPLOYEES AND REVOKING EXECUTIVE ORDER\nNO. 457 SERIES OF 1933\nBy virtue of the powers vested in me by law, I, MANUEL L. QUEZON, President of the Philippines, do\nhereby promulgate the following rules and regulations regarding allowances of automobiles and other means\nof transportation privately owned by provincial and city officials and employees, effective as of January first,\nnineteen hundred and thirty-seven:\na) For provinces and cities having 300 kilometers or longer of declared first- and second-class roads-\nGovernors, mayors, treasurers, and engineers\nHealth officers, auditors, and other provincial and city officials\nb) For provinces and cities having 200 kilometers or longer of declared first- and second-class roads but\nshorter than 300 kilometers-\nGovernors, mayors, treasurers, and engineers\nHealth officers, auditors, and other provincial and city officials\nc) For provinces and cities having 100 kilometers or longer of declared first- and second-class roads but\nshorter than 200 kilometers-\nGovernors, mayors, treasurers, and engineers\nHealth officers, auditors, and other provincial and city officials\n2. For the other means of transportation, the maximum monthly rates will be follows:\nFor motor launch\nFor motorcycle\n3. The rates of such transportation allowances shall not exceed the following:\nFor automobile\nper kilometer\nFor motor launch\n.04\nFor motorcycle\n.02\n.02\n4. The distance covered in going from residence to office and vice versa shall not be included in the claim for\nthe allowance.\n5. The maximum monthly allowances and rates fixed in this Order shall govern in those cases where such\nmeans of transportation are owned and operated by provinces and chartered cities.\n6. This Order shall apply only to provinces and chartered cities, and hereafter, no other government entity or\ninstrumentality shall be allowed to grant transportation allowances to any of its officers and employees.\n7. Executive Order Numbered Four hundred fifty-seven, series of nineteen hundred and thirty-three, and all\nother orders, rules, and regulations which are inconsistent herewith are hereby revoked.\nDone at the City of Manila, this twenty-third day of January, in the year of Our Lord, nineteen hundred and\nthirty-seven, and of the Commonwealth of the Philippines, the second.\n(Sgd.) MANUEL L. QUEZON\nPresident of the Philippines"}}],"pack":"ph-p157"};
  FT["PH-H17408"] = {"id":"PH-H17408","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AMENDING SECTIONS 153, 154, 156, 157 AND 161 OF THE RIVISED AIMINIS- GISLATURE AND AS ENVIVED BY EXECULIVE OFDER NO. 36, DATED MARCE 10, 1945, SO AS TO RESTORE THE NUMBER OF JUDGES OF FIRST INS TANCE BEFOE THE JAPANESE OCCUPATION, APPROPRIATING THE NICES. SARY FUNDS THEREFOR, AND FOR OTHER PURPOSES.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AMENDING SECTIONS 153, 154, 156, 157 AND 161 OF THE RIVISED AIMINIS- GISLATURE AND AS ENVIVED BY EXECULIVE OFDER NO. 36, DATED MARCE 10, 1945, SO AS TO RESTORE THE NUMBER OF JUDGES OF FIRST INS TANCE BEFOE THE JAPANESE OCCUPATION, APPROPRIATING THE NICES. SARY FUNDS THEREFOR, AND FOR OTHER PURPOSES."},"level":"law","status":"active","docNumber":"Executive Order No. 89","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00089_1946.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00089_1946.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17408-A1","no":1,"noLabel":{},"text":{"en":"• 2 =\nlaws of the Philippines, do hereby order that:\n1. Sections 153, 154, 156, 157 and 161 or the Revised Adminis.\ntrative Code, as amended, be further amended so as to read as fol.\n\"Sec. 153. Judicial districts.- Judid al districts for courts\nof first instance in the Fhilippines are constituted as follows:\n*he First Judicial District shall consist of the Province\nof Cagayan and the Province of Batanes.\n\"The Second Judicial Distriet, of the Province of Isabela\nand the Province of Nuera Vizcaya.\n\"The Third Judicial District, of the Province of Ilocos Nor-\nte, the Province of Abra, and the Province of Ilocos Sur.\n\"The Fourth Judicial District, of the Province of La Union\nand the Mountain Province.\n*The FirthJudicial District, of the Province of Pangasinan\nand the Province of Zambales.\n\"The Sixth Judicial District, of the Province of Tarlac and\nthe Province of Nueva Ecija.\n\"The Seventh Judicial District, of the Province of Pampange,\nthe Province of Bulacan, and the Province of Bataan.\nThe Eighth Judicial District, of the Province of Cavite and\nthe Province of Palawan.\nThe Ninth Judicial District, of the City of Manila.\n\"The Tenth Judicial District, of the Province of Rizal.\nThe Eleventh Judicial District, of the Province of Laguna.\n\"The Twelfth Judicial District, of the Provinee of Batangas,\nthe Province of Mindoro, the Province of Marindugie, and the Prov-\nince of Remblon.\n*The Thirteenth Judicial District, of the Province of Taya.\n\"The Fourteenth Judicial District, of the Province of Came\nrines Norte and the Province of Camarines Sur.\n• 3\n\"The Fifteenth Judicial District, of the Province of Albay,\nthe Province of Sorsogon, the Province of Masbate, and the Province\nof Catanduanes.\nThe Sixteenth Judicial District; of the Provinee of Capizo\nThe Seventeenth Judicial District, of the Province of Ilo-\nilo and the Province of Antique.\n\"The Eighteenth Judicial District, of the Province of Oeci-\ndental Negros.\nThe Nineteenth Judicial District, of the Province of Oren-\ntai Negros and the Subprovince of siquijor.\n\"The Iwentieth Judicial District, of the Province of Samaro\n\"The Twenty-first Judicial District, of the Province or Leyte.\n\"The Iwenty-second Judicial District, of the Province of Cebu.\n*The Twenty-third Judicial District, or the Province of Bohol.\n\"The Twenty-fourth Judicial Distriet, of the Province o' Ague\nsan, the Province of Surigao, the Province of Oriental Misamis,\nthe Province or Occidental Misanis, the Prorince of Bukianon, and\nthe Province of Ianao.\n\"The Twenty-fifth Judieial District, of the Province of Zam-\nboanga and the Province or Suluo\n\"The Twenty-sixth Judicial District, of the Province or Davao\nand the Province of Cotabato. *\n\"Sec. 15%. Judges or First Instance tor Judicial District.\nOne Judge of First Instance shall be conissioned for each judicial\ndistrict, except the second, third, fourth, fifth, sixth, seventh,\neighth, ninth, tenth, eleventh, twelfth, thirteenth, rourteenth,\nfifteenth, seventeenth, eighteenth, twentieth, twenty-first, twenty-\nsecond, twenty-fourth, and twenty-sixth.\n*For the Second Judicial District, there shall be two judges,\none or whom shall preside over the Court of First Instance or Isa-\nbela and the other over that of Nueva Vizeava.\n*For the Third Judicial District, there shall be two judges,\none of whom shall preside over the Court of First Instance of Ilo-\ncos Norte and the other over the Courts of Tirst Instance of Ila\ncos Sur and Abra.\n\"For the Fourth Judicial District, there shall be two judges\nwho shall be known as judges of the first and second branch, re-\nspectively.\n\"For the Fifth Judicial District, there shall be three Judges\nwho shall be known as judges of the first, second and third branch,\nrespectively, the judge of the third branch to preside, also, over\nthe Court of First Instance of Zambales.\n\"For the Sixth Judicial District, there shall be three judges,\ntwo of whom shall preside over the Court of First Instance of Nueva\nEci la and shall be known as judges of the first and second branch\nthereof, respectively, and one shall preside over the Court of First\n• Instance of Tarlac.\n*For the Seventh Judicial District, there shall be four judges,\ntwo of whom shall preside over the Courts of First Instance of Pam.\npanga, and shall be known as judges or the first and second branch\nthereof, respectively, the judge of the second branch to preside,\nalso, over the Court of first Instance of Bataan, and two shall pre-\nside over the Court of First Instance of Bulacan and shall be known\nas judges of the first and second branch thereof, respectively.\nFor the Bighth Judicial District, there shall be two judges\nwho shall be known as judges or the first and second branch, rew\nspectively, the judge or the second branch to preside, also; over\nthe Court of First Instance of Palawan.\nFor the Ninth Judicial District, there shall be nine judges\nwho shall be known as judges or the first, second, third, fourth,\nfifth, sixth, seventh, eighth and ninth branch, respectively.\n*For the Tenth Judicial District, there shall be two judges\nwho shall be known as judges of the first and second branch, rg\nspectively.\nWot the Eleventh Judicial District, there shall be two judges\nwho shall be known as judges or the first and second branch,\nspectively.\n\"For the Iwelfth Judicial District, there shall be two judges,\none or whom shall preside over the Court a First Instance of Ba\ntangas, and the other over the Courts of First Instance or Mindoro,\nMarinduque and Romblon.\n\"For the Thirteenth Judicial District, there shall be two\njudges who shall be known as judges of the first and second branch,\nrespectively.\n- 5 =\n\"For the Fourteenth Judicial District, there shall be three\njudges, two of whom shall preside over the Court of First Instance\nof Camarines Sur and shall be known as judges of the first and\nsecond branch thereof, respectively, and one shall preside over\nthe Court of First Instance of Camarines Norte.\n*For the Fifteenth Judicial District, there shall be two Judges,\none of' whom shall preside over the Courts of First Instance of Albay\nand Catanduanes, and the other over those of Sorsogon and Masbate.\n*For the Seventeenth Judicial District, there shall be three\njudges who shall be known as judges of the first, second and third\nbranch, respectively, the judge of the third branch to preside, al-\nso, over the Court of First Instance of Antique.\nFor the Eighteenth Judicial District, there shall be two judges\nwho shall be known as judges of the first and second branch, respecte\nWFor the Twentieth Judicial District, there shall be two judges\nwho shall be known as judges of the first and second branch, respects\nively, the judge of the first branch to preside over the Court of\nFirst Instance at Catbalogan, Samar, and the judge of the second\nbranch over the Court of First Instance at Borongan, same province.\n\"For the Twenty-first Judicial District, there shall be two\njudges who shall be known as judges of the first and second branch,\nrespectively, the judge of the first branch to preside over the\nCourt of First Instance at Tacloban, Leyte, and the judge of the\nsecond branch over the Court of First Instance at Maasin, same\n\"For the Iwenty-second Judicial District, there shall be three\njudges who shall be known as judges or the first, second and third\nbranch, respectively.\nFor the Iwenty-fourth Judicial District, there shall be two\njudges, one or whom shall preside over the Courts of First Instance\nof Surigao and Agusan, and the other over those of Occidental Misgo\nmis, Oriental Misanis, Bukidnon and Lanao.\n\"For the Iwenty-sixth Judicial District, there shall be two\njudges who shall be known as judges of the first and second branch,\nrespectively, the judge of the second branch to preside, also, over\nthe Court of First Instance of Cotabato.\"\n\"Sec. 156. Permanent stations of judges. The permanent sta\ntion of judges of the Ninth Judicial District shall be in the City\nExcept as herein otherwise provided, in districts com~\nprising only one province, the permanent official station of the\njudge shall be at the capital of the province.\n\"In other Judicial districts, the permanent stations of the\njudges shall be as follows:\n#For the First District, in the municipality of Tuguegarao,\nProvince of Cagayan.\n\"For the Second District, one Judge shall be stationed in the\nmunicipality of Ilagan, Province of Isabela, and the other in the\nmunicipality of Bayombong, Province of Nueva Vizcaya.\n\"For the Third District, one judge shall be stationed in the\nmunicipality of Vigan, Province of Ilocos Sur, and the other in the\nmunicipality of Laas, Province of Ilocos Norte.\n*For the Fourth District, one judge shall be stationed in the\nCity of Baguio, Mountain Provinco, and the other in the municipality\nof San Fernando, Province of La Union.\n*For the Fifth District, in the municipality of Lingayen, Prov-\nince of Pangasinan.\n\"For the Sixth District, two Judges shall be stationed in the\nmunicipality of Cabanatuen, Province of Nueva Eci ja, and the other\nin the municipality of Tarlac, Province of Tariac.\nFor the Seventh District, two judges shall be stationed in\nthe municipality of San Fernando, Province of Pampanga, and the\nother two in the municipality of Malolos, Province or Bulacan.\n\"For the Eighth District, in the City of Cavite, Province of\n\"For the Twelfth District, one judge shall be stationed in\nthe municipality of Batangas, Province of Batangas, and the other\nin the municipality of Calapan, Province of Mindoro.\n\"For the Fourteenth District, two Judges shall be stationed\nin the municipality of Naga, Province of Camarines sur, and the\nother in the municipality of Daet, Province of Camarines Norte.\n*For the Fifteenth District, one judge shall be stationed in\nthe municipality of Legaspi, Province of Albay, and the other in\nthe municipality of Sorsogon, Province of Sorsogon.\n*For the Seventeenth District, in the City of Iloilo, Province\n- 7.\n\"For the Nineteenth District, in the municipality of Dumaguete,\nProvince of Oriental Negros.\n\"For the Twentieth District, the judge of the first branch shall\nbe stationed in the municipality of Catbalogan, Province of Samar,\nand the judge or the second branch in the municipality of Borongan,\nsame province.\n\"For the Iwenty-first District, the Judge of the first branch\nshall be stationed in the municipality of Tacloban, Province of' Ley.\nte, and the judge of the second branch in the municipality of Maasin,\nsame province.\nFor the Twenty-fourth District, one judge shall be stationed\nin the municipality of Surigao, Province of Surigao, and the other\nin the municipality of Cagayan, Province of Oriental Missmis.\n\"For the Iventy-fifth District, in the City of Zamboanga, Plot\nince of Zamboanga.\n\"For the Iwenty-sixth District, one judge shall be stationed\nin the City of Davao, Province of Davao, and the other in the ma-\nnicipality of Cotabato, Province of Cotabato.*\n\"Sec. 157. Judges-at-large. -In addition to the Judges men\ntioned in section one hundred and fifty-four hereof, there shall,\nalso, be appointed twelve judges who shall not be assigned perma\nnently to any judicial district and who shall render duty in such\ndistricts or provinces as may, from time to time, be designated\nby the Department Head.\"\n\"Sec. 161. Places and times of holding court. For the Ninth\nJudicial District, court shall be held in the City of Manila. In\nother districts, court shall be held at the places in which the\nrespective judges are pemanently stationed, except as hereinaiter\nprovided. Sessions of court shall be convened on all working days\nwhen there are cases ready for trial or other court business to be\ndispatchede\nWIn the following districts, court shall, also, be held at the\nplaces and times hereinbelow specified:\n\"First District: At Aparri, Province of Cagayan, on the first\nTuesday of January of each year; and at Santo Domingo de Basco,\nProvince of Batanes, on the first Tuesday of March of each year.\nA special term of court shall, also, be held, once a year, in the\nmunicipalities of Ballesteros and Tuao, both of the Province or Ca-\ngayan, in the discretion of the district judge.\nnihird District: At Bangued, Province of Abra, on the first\nTuesday of March, June and October of each year\nFourth District: The first brand, at Bontoo, Mountain Prov-\nince, on the first Tuesday of March and November of each year; and,\nwhenever the interests of justice so require, a special tem or\ncourt shall be held at Lubuagan, Subprovince of Kaling; and the\nsecond branch, at Kiangan, Mountain Province, on the rirst Tuesday\nof March and November of each year.\n\"Firth District: At Tayug, Province of Pangasinan, on the\nfirst Tuesday of February of each year; and at Iba, Province of\nZambales, on the first Tuesday of February and October of each\n\"Seventh District: At Balanga, Province of Bataan, on the\nfirst Tuesday of January and Jure of each year.\n\"Eighth District: At Coron, Province of Palawan, on the first\nMonday of March and August of each year; at Guyo, same province,\non the second Thursday of March and August of each year; and at\nPuerto Princesa, same province, on the fourth Wednesday of March\nand August of each year.\n*Twelfth District: The judge shall hold special tem at Lu\nbang Island and San Jose, Province of Mindoro, once every year,\nas may be determined by him; at Romblon, Province of Pomblon, on\nthe first Tuesday of January, May and October, and at Badajos,\nsame province, on the third Tuesday of January, May and October\nof each year; and at Boa, Province of Marindugue, on the first\nTuesday of March and July of each year.\nThirteenth DIstrict: At Infanta, Province of Tayabas, for\nthe municipalities of Infanta, Casiguran, Baler and Polillo, On\nthe first Tuesday of June of each year.\nWFifteenth District: At Virac, Province of Catanduanes, on\nthe first Tuesday of March and September of each year; and at Mag-\nbate, Province of Masbate, on the first Tuesday of l'ebruary, June\nand October or' each year.\n\"Sixteenth District: At Kalibo, Province of Capiz, not to ex-\nceed two months in each year, to be set at the discretion of the\ndistrict judge, with the approval of the Secretary or Justice.\n\"Seventeenth District: At San Jose, Province or Antique, on\n- 9 -\nthe first Tuesday of February, June and October of each year; and\nat Culasi, same province, on the first Tuesday of December of each\n\"Nineteenth District: At Larena, Subprovince of Siquijor, on\nthe first Tuesday of August of each year.\n*wentieth District: The first branch, at Catarman, Province\nof Samar, on the first Tuesday of March of each year; and at Cal.\nbayog, same province, on the first luesday of September of each\nyear; and the second branch, at Guiwan, same province, on the first\nTuesday of February of each year; and at Laoang, same province, on\nthe first Tuesday of October of each year.\nMwenty-first District: The second branch, at Oroc, Province\nof Leyte, on the first Tuesday of December of each year.\n\"Iwenty-fourth District: At Cantilan, Province of Surigao, On\nthe first Tuesday of August of each year; at Butuan, Province of\nAgusan, on the first Tuesday of March and October of each year; a\nspecial term of court shall, also, be held once a year in either\nthe municipality of Tandag or the municipality of Hinatuan, Pro-\nince of Surigao, in the discretion of the district Judge; at Or\nquieta, Province of Occidental Misemis, on the first Tuesday of\nNovember and June of each year; at Mambajao, Province of Oriental\nMisamis, on the first Tuesday of March of each year; and at Malay.\nbalay, Province of Bukidnon, on the first Tuesday of December of\neach year. A special term of court shall, likewise, be held, once\na year, either in the municipality of Talisayan or in the munic-\n1pality of Gingoog, Province of Oriental Misanis, in the discre-\ntion of the district judge; at Iligan, Province of Lanao, on the\nfirst Tuesday of September of each year, but the September term\nfor the Province of Lana may be held at Dansalan, same province,\nin the discretion of the district judge.\n\"Twenty-fifth Distriet: At Dipolog, Province of Zamboanga,\non the first Tuesday of January and June of each year; and at Jo-\n1o, Province of Sulu, on the first Tuesday of March and October\nof each year. The office of the clerk of Court of First Instance\nat Dapitan, Province of Zamboanga, is hereby transferred to Dipo-\nlog, same province.\n#wenty-sixth District: The second branch, at Davao, Province\nof Davao, on the first Tuesday of March and November of each year.\nAt Baganga and Mati, Province of Davao, and at Glan, Province of\nCotabato, terms of court shall be held at least once a year on the\ndates to be fixed by the district judges of the first and second\nbranch, respectively.\n- 10 &\n\"Notwithstanding the provisions of this section, whenever wear\nther conditions, the condition of the roads or means of transporta.\ntion, the number of cases or the interest of the administration of\njustice require it, the Secretary of Justice may advance or post…\npone the term of court or transfer the place of holding the same to\nanother municipality within the same judicial district; and, in land\nregistration cases, to any other place more convenient to the par-\n2. Any district Judge of First Instance, judgewat-large or\nCadastral judge, appointed to the People's Court, as provided in\nCommonwealth Act Numbered Six hundred and eighty two, may be ap-\npointed to any position of district judge or judge-at-large of\nFirst Instance, and his acceptance of such appointment shall not\nconstitute a relinquishment of his office as judge or the People's\n3. There is appropriated out of any funds in the National\nTreasury, not otherwise appropriated, the sum of one hundred and\ntwo thousand pesos, for the payment of the salaries of the addi.\ntional judges herein provided.\n4 This Order shall take effect upon its issuance.\nDone at the City of Manila, this 31st day of January, in the\nyear of Our Lord, nineteen hundred and forty-six, and of the Com\nmonwealth of the Philippines, the eleventh.\nSERGIO OSMEÑA\nPresident of the Philippines\nBy the President:\nJOSE S. REYES\nSecretary to the President"}}],"pack":"ph-p157"};
  FT["PH-H17409"] = {"id":"PH-H17409","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1947/eo_89_1947.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Executive Order No. 73, Dated August 12, 1947","orig":"Amending Executive Order No. 73, Dated August 12, 1947"},"level":"law","status":"active","docNumber":"Executive Order No. 89","issuingBody":"President of the Philippines","promulgatedDate":"1947-09-03","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00089_1947_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00089_1947_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17409-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 89, September 03, 1947 ]\nAMENDING EXECUTIVE ORDER NO. 73, DATED AUGUST 12, 1947\nThe fourth, seventh, and eight paragraphs of Executive Order No. 73, dated August 12, 1947, are hereby\namended to read, respectively, as follows:\n“NOW, THEREFORE, I, MANUEL ROXAS, President of the Philippines, by virtue of the powers vested in\nme by the Constitution and section 2 of Republic Act No. 33, do hereby create and constitute an office to be\nknown as the Radio Broadcasting Board which shall be composed of the Chief of Executive Office as\nChairman, the Press Secretary of the Office of the President as Vice-Chairman, and three other members to be\nappointed by the President of the Philippines. The Chairman, Vice-Chairman, and members of the Radio\nBroadcasting Board shall not receive any additional compensation but may be allowed to collect a per diem of\ntwenty-five pesos for each day of actual attendance at the meeting of the Board. For administrative purposes,\nthe board shall be under the control and supervision of the Chief of the Executive Office.”\n“Subject to the approval of the President of the Philippines, the Radio Broadcasting Board shall appoint a\ngeneral manager and fix his compensation. The manager shall, with the approval of the Radio Broadcasting\nBoard, appoint such technical, clerical, and other employees as may be necessary: Provided, That all\nappointments for positions with compensation of two thousand four hundred pesos per annum or more shall\nbe subject to the approval of the President.”\n“There is appropriated out of the funds in the National Treasury not otherwise appropriated, the sum of two\nhundred thousand pesos as a revolving fund for the operation and maintenance of the office created therein. In\naddition to and as part of the revolving fund herein created, the Board is hereby authorized to appropriate by\nspecial budget and with the approval of the President for its operation and maintenance all the income or\nreceipts from its operation.”"}}],"pack":"ph-p157"};
  FT["PH-H17410"] = {"id":"PH-H17410","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES MINISTRATIVE ORDER NO. 64, BOTH DATED SEPTEMBER 27, 1954, CREATING AND ORGAN- TING THE ASIAN GOOD NEIGHBOR RELATIONS COMMISSION","orig":"MALACAÑANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES MINISTRATIVE ORDER NO. 64, BOTH DATED SEPTEMBER 27, 1954, CREATING AND ORGAN- TING THE ASIAN GOOD NEIGHBOR RELATIONS COMMISSION"},"level":"law","status":"active","docNumber":"Executive Order No. 89","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00089_1955.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00089_1955.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17410-A1","no":1,"noLabel":{},"text":{"en":"I also amend Administrative Order No. 64 dated Sep-\ntember 27, 1954, organizing the Asian Neighbor Relations\nCommission, by changing the designation of Mr. Modesto\nFarolan from Executive Vice-Chairman to Vice-Chairman\ndesignating Dr. Juan O. Orendain as Executive Secretary;\nand including Mr. Oscar Arellano as an additional member\nof said Commission.\nDone in the City of Manila, this 7th day of January,\nin the vear of Our Lord, nineteen hundred and fifty-five,\nand of the Independence of the Philippines, the ninth.\nRAMON MAGSAYSAY\nPresident of the Philippines\nBy the President:\nFRED RUIZ CASTRO\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H17411"] = {"id":"PH-H17411","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE SUGAR DEVELOPMENT COMMIT- TEE UNDER THE OFFICE OF THE PRESIDENT","orig":"MALACAÑANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE SUGAR DEVELOPMENT COMMIT- TEE UNDER THE OFFICE OF THE PRESIDENT"},"level":"law","status":"active","docNumber":"Executive Order No. 89","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00089_1964.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00089_1964.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17411-A1","no":1,"noLabel":{},"text":{"en":"4414\nOFFICIAL GAZETTE\n2. The Committee shall be composed of eleven members:\n... Mr. Jose Mana Gomez\nOther Members:\na. President, National Federation of Sugar\nDr. Trino Montinola\nb. President, Philippine Sugar Associa\nMr. Manuel Elizalde\nc. Administrator, Sugar Quota Adminis.\nMr. Conrado Manalansan\nd. Chairman, Philippine Sugar Institute.... Mr. Marciano Dizon\ne. Department Head in\nEconomic Affairs,\nDepartment of Foreign Affairs ......\nMr. Agustin Mangila\nf. Executive Director, National Economic\nMr. Rizalino Pablo\ng. Deputy Director General, Program Im-\nplementation Agency ....… Mr. Placido Mapa, Jr.\nh. Executive Vice-President, Philippine Na-\ntional Bank\n......... Mr. Carlos Sobreviñas\n%. Governor, Agricultural, Loanse DeveloP: Dr. Eugenio Eusebio\nment Bank of the Philippines ......\nj. Group Chairman, General Program Ad-\nministrators/Consultants\nMr. Noel Araneta\n. Deputy Governor, Central Bank\nMr. Amado Briñas\n3. The Committee shall be headed by its Chairman who\nshall be the chief executive officer of the Committee, and\nwill be empowered to appoint. such persons or entities\nand to issue such rules and regulations for the purposes\nof assisting him in the discharge of his duties and re-\nsponsibilities and of implementing the objectives and\nprograms of the committee.\n4. The Chairman is also authorized to call directly upon\nany department, bureau, or office in the executive branch\nof the government or upon any government-owned or\ncontrolied entity or agency for such assistance as the Com-\nmittee may need, and subject to approval of the President,\nto requisition for, utilize, and make use of, the services\nof their personnel.\nDone in the City of Manila, this 10th day of July, in\nthe vear of Our Lord, nineteen hundred and sixty-tour.\nDIOSDADO MACAPAGAL\nPresident of the Philippines\nBy the President:\nCALIXTO O. ZALDIVAR\nActing Executive Secretary"}}],"pack":"ph-p157"};
