  FT["PH-H17619"] = {"id":"PH-H17619","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Increasing the subsistence allowance of all Police Commissioned Officers and Police Non-Commissioned Officers of the Philippine National Police (PNP) including cadets of the Philippine National Police Academy and those PNP recruits undergoing training at PNP training institutes (Joseph Ejercito-Estrada)","orig":"Increasing the subsistence allowance of all Police Commissioned Officers and Police Non-Commissioned Officers of the Philippine National Police (PNP) including cadets of the Philippine National Police Academy and those PNP recruits undergoing training at PNP training institutes (Joseph Ejercito-Estrada)"},"level":"law","status":"active","docNumber":"Executive Order No. 108","issuingBody":"President of the Philippines","promulgatedDate":"1999-06-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00108_1999_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00108_1999_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17619-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The subsistence allowance for Police Commissioned Officers and Police Non-Commissioned\nOfficers of the Philippine National Police, including cadets of the Philippine National Academy and the PNP\nrecruits undergoing training at PNP training institutes, is hereby increase from Thirty Pesos (P30.00) to Sixty\nPesos (P60.00) per day, effective January 1, 1999;"}},{"id":"PH-H17619-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"For CY 1999, funds needed to implement this Order shall come from the Miscellaneous\nPersonnel Benefits Fund. For CY 2000 and beyond, the budgetary requirements shall be included in the\nAnnual Appropriations of the Philippine National Police;"}},{"id":"PH-H17619-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"The Secretary of the Interior and Local Government shall issue such implementing\ninstructions as necessary and proper to carry out the intent of this Order;"}},{"id":"PH-H17619-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"All rules and regulations and other issuances, or parts thereof, that are in conflict with this\nOrder are hereby repealed or modified accordingly;"}},{"id":"PH-H17619-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"This Order takes effect immediately.\nDONE in the City of Manila, this 10th day of June in the year of Our Lord, Nineteen Hundred and\nNinety-Nine.\n(Sgd.) JOSEPH EJERCITO ESTRADA\nPresident of the Philippines\n\nBy the President:\n(Sgd.) RONALDO B. ZAMORA\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H17620"] = {"id":"PH-H17620","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING A PORTION OF THE GOVERNMENT SERVICE INSURANCE SYSTEM (GSIS) PROPERTY LOCATED IN PAROLA, TONDO AND BINONDO, MANILA AS SOCIAL HOUSING SITE AND PROVIDING FOR THE DISPOSITION THEREOF TO QUALIFIED OCCUPANTS AND BENEFICIARIES","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES DECLARING A PORTION OF THE GOVERNMENT SERVICE INSURANCE SYSTEM (GSIS) PROPERTY LOCATED IN PAROLA, TONDO AND BINONDO, MANILA AS SOCIAL HOUSING SITE AND PROVIDING FOR THE DISPOSITION THEREOF TO QUALIFIED OCCUPANTS AND BENEFICIARIES"},"level":"law","status":"active","docNumber":"Executive Order No. 108","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00108_2002.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00108_2002.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17620-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Declaration as Social Housing Site. - In view of the need of\ninformal settlers to acquire home ownership and shelter security, the aforesaid property\nof GSIS in Parola, Manila is hereby declared as social housing site open for disposition to\nqualified occupants and beneficiaries.\nIt shall be strictly understood that the development of the area as a social housing\nproject shall be pursued without obstructing the on-going clearing project being\nundertaken by the Department of Public Works and Highways and subject to compliance\nwith the pertinent provisions of the Sanitation Code (P.D. 856) and its implementing\nrules and regulations.\nPOMA Outgoing * 12097\n\n2"}},{"id":"PH-H17620-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Mode of Disposition, Pricing and Payment Scheme and\nBeneficiary Guidelines. - The mode of disposition, qualification of beneficiaries,\nproposed lot pricing, payment scheme, and beneficiary guidelines and other\nconditions shall be established, evaluated and implemented by an Executive\nCommittee composed of the GSIS, as chair, with the following as members:\nHousing and Urban Development Coordinating Council (HUDCC), Presidential\nAdviser for Special Concerns, National Anti-Poverty Commission (NAPC),\nDepartment of Environment and Natural Resources (DENR) and Non\nGovernment Organizations (NGO) as may be identified by the chair. The\nCommittee shall ensure that a fair pricing and payment scheme for the\nbeneficiaries shall be instituted."}},{"id":"PH-H17620-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Separability Clause. - In the event that any provision hereof is\ndeclared invalid by any competent court or tribunal, the other provisions hereof\nunaffected thereby shall remain in full force and effect."}},{"id":"PH-H17620-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Effectivity. - This Executive Order shall take effect immediately.\nDone in the City of Manila, this 4TH day of June\nLord, two thousand and two.\n, in the year of Our\nPOMA Outgoing * 12098\nBy the President:\nAVELINO J. CRUZ, JR.\nOIC, Office of the Executive Secretary\nPMS LIBRARY BCODE002506\nCERTIFIED COPY:\nLAMBERTO R. BARBIN\nthe-In-Charge"}}],"pack":"ph-p157"};
  FT["PH-H17621"] = {"id":"PH-H17621","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE TUBOD PORT ZONE AND PLACING IT UNDER THE ADMINISTRATIVE JURISDICTION OF THE PHILIPPINE PORTS AUTHORITY (PPA)","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE TUBOD PORT ZONE AND PLACING IT UNDER THE ADMINISTRATIVE JURISDICTION OF THE PHILIPPINE PORTS AUTHORITY (PPA)"},"level":"law","status":"active","docNumber":"Executive Order No. 108","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00108_2012.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00108_2012.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17621-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Port of Tubod. The territorial jurisdiction of the Port of Tubod\nsituated in the Municipality of Tubod, Province of Lana del Norte, is hereby delineated\nand established, particularly described as follows:\nBeginning at a point marked 1 on the plan, being N. 54 deg. 18' W., 452.21 m.\nfrom BLLM No. 157, PLS-13, thence:\n11'\n26'\n26'\n09'\n22'\n30'\n19'\n19'\n111\n11'\n12.00 m. to point of beginning,\nContaining a total area of SEVEN HUNDRED TWENTY-FIVE THOUSAND NINE\nHUNDRED SEVENTY (725,970) SQUARE METERS, more or less.\n@ítico oltho Brocitont oftho 291"}},{"id":"PH-H17621-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"PPA Jurisdiction. The Tubod Port Zone, as delineated, is hereby\nplaced under the administrative jurisdiction of the PA, which shall, consistent with the\nregional industrial plans of the government, implement a program for the proper zoning,\nplanning, development and utilization of the port."}},{"id":"PH-H17621-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Repeal. All issuances, orders, rules and regulations, or parts\nthereof, which are inconsistent with this Executive Order are hereby repealed, amended\nor modified accordingly."}},{"id":"PH-H17621-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Separability. If any provision of this Executive Order is declared\ninvalid or unconstitutional, the other provisions not affected thereby shall remain valid\nand subsisting."}},{"id":"PH-H17621-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately upon\npublication in a newspaper of general circulation.\nDONE, in the City of Manila, this 4th day of December, in the year of our\nLord, Two Thousand and Twelve.\nBy the President:\nPAQUITO N. OCHOA, JR.\nExecutive Secretary\nOffice of the Brendent ofthe Philippines\nCERTIFIED COpY.\n2\nMARIANITO M. DIMAANDAL\nDIRECTOR IV\nMALACAÑANG RECORDS OFFICE"}}],"pack":"ph-p157"};
  FT["PH-H17622"] = {"id":"PH-H17622","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DIRECTING THE PHILIPPINE CHARITY SWEEPSTAKES OFFICE TO SET ASIDE A PORTION OF THE STANDBY FUND UNDER EXECUTIVE 2003) TO COVER THE FINANCIAL REQUIREMENTS OF THE NATIONAL GOVERNMENT'S RESPONSE TO CASES OF COVID-19 IN THE COUNTRY, AMENDING EO NO. 201 AND FOR OTHER PURPOSES","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DIRECTING THE PHILIPPINE CHARITY SWEEPSTAKES OFFICE TO SET ASIDE A PORTION OF THE STANDBY FUND UNDER EXECUTIVE 2003) TO COVER THE FINANCIAL REQUIREMENTS OF THE NATIONAL GOVERNMENT'S RESPONSE TO CASES OF COVID-19 IN THE COUNTRY, AMENDING EO NO. 201 AND FOR OTHER PURPOSES"},"level":"law","status":"active","docNumber":"Executive Order No. 108","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00108_2020.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00108_2020.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17622-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The PCSO is hereby directed to set aside the amount of\nP420,585,000.00, corresponding to fifty percent (50%) of the remainder of the standby\nfund under Section 4 of EO No. 201, to cover the financial requirements for the treatment,\ncontainment, prevention and management of COVID-19 cases in the country. The other\n50% shall continue to cover the funding necessary to respond to future cases of SARS in\nthe Philippines.\nThe IATF-MEID, through the DOH, shall coordinate with the PCSO relative to the\nrelease of the abovementioned funds, subject to applicable budgeting, accounting and\nauditing laws, rules and regulations."}},{"id":"PH-H17622-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Except for the foregoing amendment, all other provisions of EO No.\n201 shall remain in full force and effect."}},{"id":"PH-H17622-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"This Order shall take effect immediately.\nDONE, in the City of Manila, this 14th day of\nyear of Our Lord, Two Thousand Twenty.\nBy the President:\nSALVADOR C. MEDIALDEA\nExecutive Secretary ^\nREPUBLIC OF THE PHILIPPINES\n- 014387\n2\nOffice of the President\nMALACAÑANG RECORDS OFFICE\nATTY. CONCEPCION ZEN ME. FERTIOLINO-EMAD\n# 3-18-1620\nDIRECTOR IV"}}],"pack":"ph-p157"};
  FT["PH-H17623"] = {"id":"PH-H17623","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES STREAMLINING THE INITIATIVES OF THE OFFICE OF THE PRESIDENT ON INVESTMENT AND ECONOMIC AFFAIRS","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES STREAMLINING THE INITIATIVES OF THE OFFICE OF THE PRESIDENT ON INVESTMENT AND ECONOMIC AFFAIRS"},"level":"law","status":"active","docNumber":"Executive Order No. 108","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00108_2026.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00108_2026.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17623-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Abolition. The OSAPIEA is hereby abolished. The powers, duties,\nand functions of OSAPIEA, except those that are within the powers, duties, and\nfunctions of other concerned agencies in accordance with their respective mandates,\nshall now be integrated into the Office of the Executive Secretary (OES).\nAll records, documents, resources, office spaces, and other properties in\ncustody of or are being used by the OSAPIE shall be turned over to the OES, subject\nto existing laws, rules, and regulations. As may be necessary, the existing personnel\nin OSAPIEA shall be transferred to the OES, subject to existing laws, rules, and\nregulations."}},{"id":"PH-H17623-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"EDCom. The Secretary of Department of Finance shall serve as\nChairperson of the EDCom, and as such, shall continue to exercise oversight over\nstrategic investment priorities and agenda.\nThe Secretary of the Department of Economy, Planning, and Development shall\nserve as Vice Chairperson of the EDCom.\nPursuant to RA No. 12145, a representative designated by the OP shall remain\nas Member of the EDCom."}},{"id":"PH-H17623-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"SEIA Council. The Executive Secretary shall now serve as the\nChairperson of the SEIA Council. The Vice Chairperson and Members of the SEIA\nCouncil shall remain consistent with AO No. 31."}},{"id":"PH-H17623-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Separability. If any section or part of this Order is declared\nunconstitutional or invalid, the other sections or provisions not otherwise affected shall\nremain in full force and effect."}},{"id":"PH-H17623-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Repeal. All issuances, orders, rules and regulations, or parts thereof\nthat are inconsistent with this Order, are hereby repealed or modified accordingly."}},{"id":"PH-H17623-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Effectivity. This Order shall take effect immediately upon its\npublication in the Official Gazette or a newspaper of general circulation.\n2\n\nDONE, in the City of Manila, this 26th day of January\nyear of Our Lord, Two Thousand and Twenty-Six\nBy the President:\nRALPH G. RESTO\nActing Execytive Secretary\n18 2-1-30707\nOffice of the President\nRECORDS OFFICE\n•TOLENTINO-NAVA\nDIRECTOR IV\nREPUBLIC OF THE PHILIPPINES\n3"}}],"pack":"ph-p157"};
  FT["PH-H17624"] = {"id":"PH-H17624","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1937/eo_109_1937.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Procedure to Be Followed in the Repair of Typewriters and Similar Equipment of the Various Offices of the National, Provincial, City, and the Municipal Governments.","orig":"Procedure to Be Followed in the Repair of Typewriters and Similar Equipment of the Various Offices of the National, Provincial, City, and the Municipal Governments."},"level":"law","status":"active","docNumber":"Executive Order No. 109","issuingBody":"President of the Philippines","promulgatedDate":"1937-08-24","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00109_1937_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00109_1937_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17624-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 109, August 24, 1937 ]\nPROCEDURE TO BE FOLLOWED IN THE REPAIR OF TYPEWRITERS AND SIMILAR EQUIPMENT\nOF THE VARIOUS OFFICES OF THE NATIONAL, PROVINCIAL, CITY, AND THE MUNICIPAL\nGOVERNMENTS\nPursuant to the provisions of Act Numbered Forty-one hundred and eleven, the following procedure is hereby\nadopted in the repair of typewriters and similar equipment of the various offices of the National, provincial,\ncity, municipal government:\n1. In the case of typewriters of government offices falling under Exception One of Executive Order Numbers\nFour hundred seventy-three, series of nineteen hundred and thirty-four (see paragraph four hereof), repairs not\nexceeding a total cost of ten pesos for each typewriter (including cost of new parts) may be execute\nimmediately by any repair shop or mechanic in the locality or nearby town, without referring the same to the\ncity Government Marine Railway and Repair Shops: Provided, however, That a report shall be submitted to\nthe Government Marine Railway and Repair Shops giving the nature of the work done and a list of new parts\nfurnished together with their cost.\n2. In the case of typewriters of Government offices falling under Exception One of Executive Order\nNumbered Four hundred seventy-three, and involving repairs estimated to cost in excess of ten pesos on one\ntypewriter (including cost of new parts) before the work is done, the matter shall first be referred, for\ncomment and recommendation, to the Government Marine Railway and Repair Shops, together with the\noriginal offer or offers of one or more repair shops of the locality or nearby town, such offers to specify\nclearly the work to be done, the parts to be renewed, and the price charged.\n3. If there are a sufficient number of typewriters in one provincial government office and neighboring\nmunicipal government offices requiring repairs, a request for a typewriter service mechanic may be made by\nthe provincial treasurer concerned to the Government Marine Railway and Repair Shops. In such case, the\nsaid Government Shops will detail an experienced mechanic to that province for such length of time as may\nbe necessary to do work, traveling expenses to be a proper charge to the province concerned in addition to the\nactual cost of undertaking the repair work including materials and labor.\n4. For the purpose of compliance with Exception One of Executive Order Numbered Four hundred\nseventy-three, government offices located within the following provinces are considered as not falling under\nsaid Exception:\n5. This Order shall take effect on August first, nineteen hundred and thirty-seven, and all supersede all other\nexecutive orders or parts of executive orders inconsistent herewith.\nDone at the City of Manila, this twenty-fourth day of August, in the year of Our Lord, nineteen hundred and\nthirty-seven, and of the Commonwealth of the Philippines, the second.\n(Sgd.) MANUEL L. QUEZON\nPresident of the Philippines\nBy the President:\n(Sgd.) ELPIDIO QUIRINO\nSecretary of the Interior"}}],"pack":"ph-p157"};
  FT["PH-H17625"] = {"id":"PH-H17625","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1946/eo_109_1946.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Transferring the Seat of the Municipal Government of San Pablo, Province of Isabela, From Its Present Location At San Pablo to the Barrio of Auitan","orig":"Transferring the Seat of the Municipal Government of San Pablo, Province of Isabela, From Its Present Location At San Pablo to the Barrio of Auitan"},"level":"law","status":"active","docNumber":"Executive Order No. 109","issuingBody":"President of the Philippines","promulgatedDate":"1946-05-24","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00109_1946_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00109_1946_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17625-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 109, May 24, 1946 ]\nTRANSFERRING THE SEAT OF THE MUNICIPAL GOVERNMENT OF SAN PABLO, PROVINCE OF\nISABELA, FROM ITS PRESENT LOCATION AT SAN PABLO TO THE BARRIO OF AUITAN\nUpon the recommendation of the Provincial Board of Isabela, concurred in by the Secretary of the Interior,\nand pursuant to the provisions of section 68 of the Revised Administrative Code, the seat of the municipal\ngovernment of San Pablo, of said province, is hereby transferred from its present location at San Pablo to the\nbarrio of Auitan.\nThe transfer herein made shall take effect as of April 25, 1946.\nDone at the City of Manila, this 24th day of May, in the year of Our Lord, nineteen hundred and forty-six, and\nof the Commonwealth of the Philippines, the eleventh.\n(Sgd.) SERGIO OSMEÑA\nPresident of the Philippines\nBy the President:\n(Sgd.) JOSE S. REYES\nSecretary to the President"}}],"pack":"ph-p157"};
  FT["PH-H17626"] = {"id":"PH-H17626","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1947/eo_109_1947.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Further Amending Executive Order No. 320, Dated January 27, 1941, as Amended By Executive Order No. 99, Dated March 11, 1946, and Executive Order No. 87, Dated September 3, 1947, Entitled \"Regulating the Maintenance and Operation of Race Track and Horse Racing","orig":"Further Amending Executive Order No. 320, Dated January 27, 1941, as Amended By Executive Order No. 99, Dated March 11, 1946, and Executive Order No. 87, Dated September 3, 1947, Entitled \"Regulating the Maintenance and Operation of Race Track and Horse Racing"},"level":"law","status":"active","docNumber":"Executive Order No. 109","issuingBody":"President of the Philippines","promulgatedDate":"1947-12-03","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00109_1947_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00109_1947_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17626-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 109, December 03, 1947 ]\nFURTHER AMENDING EXECUTIVE ORDER NO. 320, DATED JANUARY 27, 1941, AS AMENDED\nBY EXECUTIVE ORDER NO. 99, DATED MARCH 11, 1946, AND EXECUTIVE ORDER NO. 87,\nDATED SEPTEMBER 3, 1947, ENTITLED “REGULATING THE MAINTENANCE AND OPERATION\nOF RACE TRACK AND HORSE RACING.”\nPursuant to the powers vested in me by law, I, MANUEL ROXAS, President of the Philippines, do hereby\nfurther amend paragraph 5 of Executive Order No. 320, dated January 27, 1941, as amended by Executive\nOrder No. 99, dated March 11, 1946, and Executive Order No. 87, dated September 3, 1947, to read as\n“5. Automatic electric totalizator or other mechanical device for selling pari mutual tickets.- No person, race\ntrack, racing club, nor any other entity holding horse races the gross crossings of which on any race day\nexceeds fifty thousand pesos, shall be allowed to hold races unless such person, race track, racing club, or\nentity is provided with an automatic, electrically operated public indicator system and ticket selling machines,\nby means of which every ticket purchased on every horse in any race, shall be automatically and\ninstantaneously recorded by electrical impulse on a prominently displayed bulletin board, each figure, letter,\nor symbol of which shall be readable from a distance. However, any such person, race track, racing club, or\nentity may, upon proper application, be provisionally licensed by the Board on Races to hold horse races even\nwithout the required automatic electric totalizator, provided that it shall provide itself with mechanical or\nother devices by which every ticket purchased on every horse in any race shall be recorded on a prominently\ndisplayed bulletin board readable from a distance in lieu of the required automatic electric totalizator which\nshall be subject to the approval of the Board on Races after they have been tested and found by the Board to\nbe satisfactory; and provided, further, That such person, race track, racing club, or entity shall acquire and\ninstall within its premises the required automatic electric totalizator within such period as may be determined\nby the Board but not beyond June 30, 1948, and failure to comply with this requirement will cause the\ncancellation of their respective licenses.”"}}],"pack":"ph-p157"};
  FT["PH-H17627"] = {"id":"PH-H17627","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF MAGUING IN THE PROVINCE OF LANAO DEL SUR","orig":"MALACAÑANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF MAGUING IN THE PROVINCE OF LANAO DEL SUR"},"level":"law","status":"active","docNumber":"Executive Order No. 109","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00109_1964.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00109_1964.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H17627-A1","no":1,"noLabel":{},"text":{"en":"Done in the City of Manila, this Ist day of October, in\nthe year of Our Lord, nineteen hundred and sixty-four.\nDIOsDaDo MACAPAGAL\nPresident of the Philippines\nBy the President:\nJUAN S. CANCIO\nActing Assistant Executive Secretary"}}],"pack":"ph-p157"};
