  FT["PH-H18021"] = {"id":"PH-H18021","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"ORDER NO. J.:iS!!.- CONSTITUTING THE GREATER METROPOLITAN MANILA SOLID WASTE MANAGEMENT COMMITTEE","orig":"ORDER NO. J.:iS!!.- CONSTITUTING THE GREATER METROPOLITAN MANILA SOLID WASTE MANAGEMENT COMMITTEE"},"level":"law","status":"active","docNumber":"Executive Order No. 146","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00146_1999.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00146_1999.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18021-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Composition.\nof the Presidential Committee on Flagship Programs and\nProjects (Flagship Committee) as its Chairman, and the following as\n\\\n;\"'1\n\nSecretary, Department of Environment and Natural Resources\nSecretary, Department of Science and Technology\nSecretary, Department of Public Works and Highways\nSecretary, Departrrient of Health\nSecretary, Department of Justice\nDirector-General, National Economic and Development Authority\nHead, Presidential Management Staff\nChairman, Metropolitan Manila Development Authority\nGovernor, Bataan\nGovernor, Batangas\nGovernor, Bulacan\nGovernor, Cavite\nGovernor, Laguna\nGovernor, Pampanga\nGovernor, Rizal\nGovernor, Zambales\nThe GMMSWMC may expand its membership\nto include officials\nof concerned\nof neighboring\nparticipation\nbe necessary."}},{"id":"PH-H18021-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Functions.\nThe GMMSWMC shall serve as the over-\nall coordinating body for the formulation and implementation\nWaste Management Plan for Metro Manila and the adjoining provinces of\nBataan, Batangas,\nCavite, Pampanga, Laguna, Rizal and\nIn the preparation of the Plan, the Committee\nshall utilize\nall the previous studies conducted by MMDA, the Presidential Task Force\nManagement,\ngovernment\nconstituting\nGMMSWMC, and other agencies.\nThe GMMSWMC may\ncreate Technical Working Groups (TWGs) consisting 'of the members of\nthe Committee to assist in the performance of its tasks.\nand Secretariat\nThe Flagship\nCommittee, with the assistance of the MMDA, shall provide\" secretariat\nand technical support to the GMMSWMC and its TWGs.\nthe first year of operation, the\nGMMSWMC shall have an operating\nbudget of Ten Million\n(PIO,OOO,OOO.OO)\nwhich shall be chargeable against the funds of the\nOffice of the President.\nThereafter,\nGMMSWMC funding\nincluded in the annual appropriations of the Office of the President. The\nCommittee shall submit a work and financial plan to the Department of\nBudget and Management."}},{"id":"PH-H18021-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Reporting Clause. The GMMSWMC shall submit semi-\nannual reports to the President on its activities and accomplishments.\nClause. This Executive\nOrder repeals\nMemorandum Order No. 19, s. 1998, and amends all other issuances\ninconsistent with this Executive Order."}},{"id":"PH-H18021-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Separability\nClause. If any of the provisions of this\nOrder shall be declared unconstitutional,\nthe other provisions of this\nOrder shall remain valid.\n10. Effectivity.\nThis Executive Order shall take effect\nimmediately.\nDONE in the City of Manila, Philippines,\nAugust, in the year of our Lord, nineteen hundred and ninety nine,\nC==:;;6~~;; ~~CITO ESTRADA\nBy the President:\n-~~.(~\nRONALDO B. ZAMORA\nExecutive Secretary\n/\n7072\nCERTIFIED COpy:\n-"}}],"pack":"ph-p157"};
  FT["PH-H18022"] = {"id":"PH-H18022","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO.","orig":"BY THE PRESIDENT OF THE PHILIPPINES EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 146","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00146_2002.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00146_2002.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18022-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The general supervision and control of PCTC is hereby transferred\nto the Office of the National Security Adviser."}},{"id":"PH-H18022-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Repealing Clause. All executive orders, rules and regulations and\nother issuances inconsistent with the provisions of this Executive Order are hereby\nrepealed or modified accordingly."}},{"id":"PH-H18022-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nCity of Manila, October 22, 2002\nBy the President:\nChe Al. Roariato\nALBERTO G. ROMULO\nPola Ongoing r 16123 Executive Secretary\nPMS LIBRARY BCODE001969"}}],"pack":"ph-p157"};
  FT["PH-H18023"] = {"id":"PH-H18023","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACARAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DELEGATING TO THE NATIONAL ECONOMIC AND DEVELOPMENT AUTHORITY BOARD THE POWER OF THE PRESIDENT TO APPROVE RECLAMATION","orig":"MALACARAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DELEGATING TO THE NATIONAL ECONOMIC AND DEVELOPMENT AUTHORITY BOARD THE POWER OF THE PRESIDENT TO APPROVE RECLAMATION"},"level":"law","status":"active","docNumber":"Executive Order No. 146","issuingBody":"President of the Philippines","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00146_2013.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00146_2013.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18023-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Approval of Reclamation Projects. The power of the President to\napprove reclamation projects is hereby delegated to the NEDA Bosrd. The PRA shall\ncontinue to process, evaluate and recommend the approval of ail Dioposed reclamation\nprojects to the NEDA Board. Proposed reclamation projects endorsed by te PRA to the\nNEDA Board should include all relevant documents as may be leguired by the NEDA\n3Giuliommes\n\n12:64\nBoard, such as but not limited to Letters of Intent, Project Proposais, Pre-reasility\nStudies. draft agreement or contract. Such delegation however shail not be construed\nas diminishing the President's authority to modify, amend or nullify NEDA Board's\nThe NEDA Board approval shall be required:\nFor reclamation projects initiated/proposed by PRA or any government\nentilv allowed under existing laws to reclaim land;\nFor reclamation projects initiated by the private sector/entity through PRA,\nLocal Government Units (LGUs) or other government agencies authorized\nto reclaim land; and\nFor reclamations / reclamation components of respective development\nprojects of such agencies mandated to reclaim under their respective\ncharters such as but not limited to the following agencies: Philippine Ports\nAuthority (PPA). Laguna Lake Development Authority (LLDA), Bases\nConversion and Development Authority (BCDA), Subic Bay Metropolitan\nAuthoritv (SBMA). Philippine Veterans Investment Development\nCorporation (PHIVIDEC). Department of Public Works and Highways\n(DPWH), and National Power Corporation (IPC)."}},{"id":"PH-H18023-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Powers, Functions, and Mandate of PRA. Except for the power to\napprove reclamation projects, all other powers, functions, and mandates of PRA shail\nbe retained and exercised by PRA."}},{"id":"PH-H18023-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Environmental Compliance Certificate (ECC). Prior to the\nimplementation of reclamation projects dulv approved pursuant to Section 1 hereo, an\nECC shall be secured from the Department of Environment and Natural Resources\n(DENR). No reclamation work shall commence without the required ECC."}},{"id":"PH-H18023-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Competitive Bidding. All reclamation projects shall undergo\ncompetitive public bidding consistent with the government's thrust to promote\ntransparency and competitiveness."}},{"id":"PH-H18023-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Transitory Provision. In accomplishing the prescribed provisions\nherein, the following transitory provisions shall be complied with:\nThis Order shall apply to all reclamation projects, including those initiated\nby LGUs and all other government agencies/government owned or\ncontrolled corporations including PA, LLDA, BCDA, SBMA, PHIVIDEC,\nDPWH, NPC and others, for which there are no contracts/agreements yet\nexecuted between the government entity concerned and a private sector\nproponent prior to the effectivity of this Order.\nrevibent of the \"abilipuites\n2\n\n21/10/2013 12:34\n7361346\nWithin two (2) months after the effectivity of this Order, the PRA shall\nprovide the NEDA Board a list of all reclamation projects approved by\nPRA and relevant information, i.e., project location, date approved by\nPRA, project proponents (government and private entities), total project\ncost/amount, and implementation period, classified as follows:\nUnder actual phvsical reclamation or implementation; and\nNot vet started with implementation or actual physical reclamation\nbut either with duly executed contracts with a private sector\nproponent or are undergoing/undergone bidding or are yet to\nundergo bidding."}},{"id":"PH-H18023-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"Implementing Rules and Regulations. NDA and PRA shail issue\nsuch rules and regulations as may be necessary to implement this Order."}},{"id":"PH-H18023-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Separability Clause. Should any provision of this Order be\ndeclared invalid or unconstitutional, the other provisions unaffected thereby shall remain\nvalid and subsisting."}},{"id":"PH-H18023-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Repealing Clause. All orders, proclamations, rules, regulations, or\nparts thereof, which are inconsistent with any of the provisions of this Order are hereby\nrepealed or modified accordingly."}},{"id":"PH-H18023-A9","no":9,"noLabel":{"en":"SECTION 9"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDONE, in the City of Manila, this\nLord, Two Thousand and Thirteen.\n, in the year of Our\nBy the President:\nPAQUITON. OCHOA, JR.\nExecutive Secretary\n3"}}],"pack":"ph-p157"};
  FT["PH-H18024"] = {"id":"PH-H18024","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ADJUSTING THE DIVIDEND RATE OF THE OVERSEAS FILIPINO BANK","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ADJUSTING THE DIVIDEND RATE OF THE OVERSEAS FILIPINO BANK"},"level":"law","status":"active","docNumber":"Executive Order No. 146","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00146_2021.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00146_2021.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18024-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Adjustment of Dividend Rate. Pursuant to Section 5 of RA No. 7656, the\npercentage of net earnings to be declared and remitted by the OFBank to the National\nGovernment for CY 2016 is adjusted from fifty percent (50%) of its annual net earnings to\n0%."}},{"id":"PH-H18024-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Coverage. The adjusted dividend rate set forth in Section 1 of this Order\nis applicable only to the OFBank for CY 2016."}},{"id":"PH-H18024-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDONE, in the City of Manila, this 5th day of August\nTwo Thousand and Twenty-One.\nin the year of Our Lord,\nBy the President:\nSALVADOR C. MEDIALDEA\nExecutive Secretarv (\nTHE PRESIDENT OF THE PHILIPPINES* I\nMOULLIC OF THE PHILIPPINES\n- 018077\nATTY. CONCEPCION\n-E. PERROLINO-ERAD\n178-4-2021\nDIRECTOR IV"}}],"pack":"ph-p157"};
  FT["PH-H18025"] = {"id":"PH-H18025","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1938/eo_147_1938.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Authorizing the Commissioner of the Budget to Take Part in the Deliberations of the Cabinet in Certain Matters","orig":"Authorizing the Commissioner of the Budget to Take Part in the Deliberations of the Cabinet in Certain Matters"},"level":"law","status":"active","docNumber":"Executive Order No. 147","issuingBody":"President of the Philippines","promulgatedDate":"1938-04-08","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00147_1938_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00147_1938_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18025-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 147, April 08, 1938 ]\nAUTHORIZING THE COMMISSIONER OF THE BUDGET TO TAKE PART IN THE DELIBERATIONS\nOF THE CABINET IN CERTAIN MATTERS\nWHEREAS, the Commissioner of the Budget is the official of the Government who is entrusted by the\nPresident, in the performance of his constitutional duty, with the task of preparing the budget of the receipts\nand expenditures of the National Government;\nWHEREAS, for the proper and effective performance of this duty, it is necessary that constant supervision\nand control be exercised over the expenditures of the Government, in general, and, in particular, over\nappointments of new personnel, increases in the salaries of personnel already existing and requisitions and\norders for furniture, equipment, and supplies;\nNOW, THEREFORE, by virtue of the powers in me vested by the Constitution and the laws, I, MANUEL L.\nQUEZON, President of the Philippines, do ordain and promulgate as follows:\nThe Commissioner of the Budget shall sit and take part in the deliberations of the Cabinet wherein matters\ninvolving the expenditure of public funds and appointments of employees for the different departments,\nbureaus, and offices of the Government, including the offices under the President, are considered. In all cases\nsubmitted to the Cabinet where the Commissioner of the Budget and the Head of the Department concerned\nshould have a difference of opinion on the expenditure of funds entailed by any proposed new appointment,\nincrease in salary, purchase of furniture or equipment, new activity or project, or expansion of any existing\nservice, the decision of the Cabinet on such proposal shall be subject to the approval of the President.\nDone at the City of Manila, this eight day of April, in the year of Our Lord, nineteen hundred and thirty-eight,\nand of the Commonwealth of the Philippines, the third.\nMANUEL L. QUEZON\nPresident of the Philippines\nBy the President:\nJORGE B. VARGAS\nSecretary to the President"}}],"pack":"ph-p157"};
  FT["PH-H18026"] = {"id":"PH-H18026","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1968/eo_147_1968.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Executive Order No. 95 Dated October 24, 1967, Entitled Amending Executive Order No. 65 Dated May 22, 1967, Entitled Creating a Permanent Cabinet Committee on Public Bidding.","orig":"Amending Executive Order No. 95 Dated October 24, 1967, Entitled Amending Executive Order No. 65 Dated May 22, 1967, Entitled Creating a Permanent Cabinet Committee on Public Bidding."},"level":"law","status":"active","docNumber":"Executive Order No. 147","issuingBody":"President of the Philippines","promulgatedDate":"1968-09-09","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00147_1968_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00147_1968_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18026-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 147, September 09, 1968 ]\nAMENDING EXECUTIVE ORDER NO. 95 DATED OCTOBER 24, 1967, ENTITLED “AMENDING\nEXECUTIVE ORDER NO. 65 DATED MAY 22, 1967, ENTITLED ‘CREATING A PERMANENT\nCABINET COMMITTEE ON PUBLIC BIDDING'”\nBy virtue of the powers vested in me by law, I, FERDINAND E. MARCOS, President of the Philippines, do\nhereby amend the second paragraph of Executive Order No. 95 dated October 24, 1967, entitled “Amending\nExecutive Order No. 65 dated May 28, 1967, entitled ‘Creating a Permanent Cabinet Committee on Public\nBidding'” to read as follows:\n“The Committee is empowered to evaluate, review and pass upon all government contracts costing more than\nP500,000; to promulgate guidelines or rules and regulations in the conduct of public bidding affecting\ngovernment contracts involving P500,000 or less; to call upon any department, bureau, office, agency or\ninstrumentality of the government for such assistance as it may need, and to create such sub-committee or\nstaff as may be necessary in the consideration of such bids, and otherwise assist the committee in the\nevaluation thereof; provided, that government contracts for infrastructure projects costing P100,000 or more\nup to P500,000 shall be evaluated and reviewed by the Presidential Economic Staff.”\nDone in the City of Manila, this 9th day of September, in the year of Our Lord, nineteen hundred and\nsixty-eight.\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) RAFAEL M. SALAS\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18027"] = {"id":"PH-H18027","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACA..NA NG EXECUTIVE ORDER NO.","orig":"MALACA..NA NG EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 147","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00147_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00147_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18027-A1","no":1,"noLabel":{},"text":{"en":"-'\n'-..1:'.'-':\":'.\"';':\n.:.. '-'---\n1-'1'::' '-=--\n=---\n...\n--,..:\n-:--.:-\n--.\"';\"'0--\n:.,.,\n-=-:-.,.,...;-.:\n0 _.:0--\n~ -'-'-\" \"'-\n:-'..;.':.\n!\\!'\"'\n11(\",\n;'~\"-==\"\"'=-\"'\"\n7/\n-\"\n,\n--'-'\n\"\"\n\"'\n--,\n,\n~,;-.:-:-::-='\n'::;\n: 0 -':\n-~,.\n--=\n0\n0 1-;\"'=-\n=.\n..~\"'---'\"-.,.-:\n.:.\n\"-.;.\n~;:\n=-:.\n-:.:\n:...=\n=--\n-'-\n'-\n-~,..; .,...\". -;\n=.-\",,-':~,..:\n0 ;=-\n:\n-~\n...~--\n~\n~\n~\n.:\n~\n0 .:\n,,\n\"'\"\n_ 0\n'!\"'-~\n0\"\"\n'.\n.-.,.'\n\"'0'.0-\n:\n;-\n~\n~~-\n-;\n;\n\"\".\n'\", ,\n'-\n,\ntbe Philippines;\ndo heraby order:\n~.~~\n~_.\n~-;...'-\n-0\n110\n24~\n1986\n0=\n-..\n, -.\n0\n;-'\n'\"\n1...\n-\"\";\n:\n-..;.:\n--\n1\n1-':>\n\"\"'---\n~ -,-'\"\n-=\n-_:..:\n_:\"_- , ~\n\",-\n--\"\"-'-';-'\n.-\n~---\n'-'---\n\"\"'\"\n...\"',..,\n..\n.!!;\"\n'\"'~..,..\n.;~!\n\\ ..-:\n-~...\n~= -.1:-\n-.\nT~=. D=.!le£i 'cS 1Jrcvi.d.ed\n,\n1 _-~\n.-::\n~.\n~~\n~~.\n:::'.:\n::.\n:. -\"1 --=-'\n-:..:\n':.-:-.\n::- --.;. :-.::::: -::;-.;: :\"':--'\n0\n1\"\".- '_.'~'\n-~\n.,.\n.'\"'-\n0:_.-\n'-\n---=-\n~\n\",,-\n-'--\n~\n~\n=.-'\n.-,\n. 1\n.-~\n.,-\n~~ 4.\n,\n--'\"'.\n1 \"\"\n::::\n,-\n-~\n--'\"\"\"'\"\n-\"\n.--\n.'\n-,.\"\n, ,,_.-\n,.,-\n-,\n1 __.\nLJOCoperations.\nthe results\nof a more comp~ehensive\ncompensation\ndone by the Department\n1:v1anagement..\nTrle amounts necessary\nto implement.\nfrom the ag5Tegate\n.\n2\n\"\nthe National\nGovernment.\nAny deficiency\nbe charged- against\nthe Compensation\nand Organizational\nAdjustment\n~987.\n1.\"\n.\n07\n\"),'..-~\n..'\n:--:\n-,\n7.\n1\"\"1 ;-,.,=.\n'-:-~=..-\n0\n;-\n, '-'-\"\"\n.--\n.\"\"\n\"\n.11\n/..,\n...,\n/\n,...,\n~~\n'\n:-\n\";.-\" -~-=\n--\n'\n-'\"-\n-.1-.\n~-=?7--\n0°;::::'-,-\n;.'-\". -\n~\n~'-\n'-"}}],"pack":"ph-p157"};
  FT["PH-H18028"] = {"id":"PH-H18028","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE 10% MARGIN OF PREFERENCE (MOP) GRANTED BY THE PHILIPPINES UNDER THE AGREEMENT ON THE GLOBAL SySTEM OF TRADE PREFERENCES AMONG DEVELOPING COUNTRIES AS SET FORTH IN THE PHILIPPINE SCHEDULE OF CONCESSIONS ANNEXED TO THE AGREEMENT","orig":"MALACAÑANG MODIFYING THE RATES OF DUTY ON CERTAIN IMPORTED ARTICLES AS PROVIDED UNDER THE TARIFF AND CUSTOMS CODE OF 1978, AS AMENDED, IN ORDER TO IMPLEMENT THE 10% MARGIN OF PREFERENCE (MOP) GRANTED BY THE PHILIPPINES UNDER THE AGREEMENT ON THE GLOBAL SySTEM OF TRADE PREFERENCES AMONG DEVELOPING COUNTRIES AS SET FORTH IN THE PHILIPPINE SCHEDULE OF CONCESSIONS ANNEXED TO THE AGREEMENT"},"level":"law","status":"active","docNumber":"Executive Order No. 147","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00147_1993.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00147_1993.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18028-A402","no":402,"noLabel":{"en":"Section 402"},"text":{"en":"of the Tariff and Customs Code of 1978, as\namended, do hereby order that:\n933698\n\n2/\nThe articles specifically listed in\nAnnex \"A\" as classified under Section 104 of the Tariff\nand Customs Code of 1978, as amended, shall be accorded\na 10% Margin of Preference (MOP) as shown in Column 9 of\nsaid Annex \"A\".\nAccordingly, such articles shall be\nsubject to the Preferential Tariffs indicated in Columns\nSEC. 2. In the event that any subsequent changes are\nmade in the basic Philippine rate of duty on any of the\narticles listed in Annex \"A\", such articles shall be\nautomatically accorded the corresponding MOP indicated in\nColumn 9 of said Annex \"A\"\nSEC. 3. The MoP indicated in Column 9 of Annex \"A\"\nshall apply only to imports from participants in the\nAgreement on the GSTP as defined in Article I (a) thereof.\nSEC. 4. After the effective date of this Order; all\nthe above-described articles entered or withdrawn from\nwarehouses in the Philippines for consumption shall be\nsubject to qualification under the Rules of Origin as\nprescribed in the Agreement on the GSTP.\nSEC. 5. This Order shall take effect on 1 January\n1994. Done in the City of Manila, this 276,\nday o£ DECEMBER\nin the year of our Lord, Nineteen Hundred an Ninety-Three.\nBy the President:\nExecutive Secretary\n\nARTICLES GRANTED MARGINS OF PREFERENCE BY THE PHILIPPINES UNDER THE AGREEMENT\nON THE GLOBAL SYSTEM OF TRADE PREFERENCES AMONG DEVELOPING COUNTRIES (GST)\nDescription\nRate of Duty\nGSTP Preferential Tariff\n:24 March: 1 July: 1 July: 1 July: 1 July:rence : 24 March: 1 July: 1 July: 1 July: 1 July\n1992\n1992: 1993 : 1994: 1995\n(1)\n(2)\n(2)\n(4)\n(5)\n(6)\n(7)\n(8)\n(9)\n31.04 300 ex 3104.30 00 Potassium sulphate\nFree Free Free Free Free\n10%\ncontaining not. more\nthan 52% by weight\n40.02 300\n4002.20 10 Butadiene rubber\n(BR), in primary\n3%\n2%\n3%\n3%\n3%\n10%\nsemi-diesel engines\nfor power tillers\n10%\nex 8408.20 90 Diesel and\nsemi-diesel engines\nfor other tractors\n20%\n10%\n10%\n10% 0%\n(10)\n(11)\n(12)\n(13) (14)\nFree Free Free Free\n2.7% 2.7% 2.7% 2.74 2.7%\n12%\n9%\n9%\n9%\n9%"}}],"pack":"ph-p157"};
  FT["PH-H18029"] = {"id":"PH-H18029","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG PMS LIBRARY CONSTITUTING THE PRESIDENTIAL CONSCIENCE TO REVIEW CASES OF DEATH CONVICTS FOR EXECUTION","orig":"MALACANANG PMS LIBRARY CONSTITUTING THE PRESIDENTIAL CONSCIENCE TO REVIEW CASES OF DEATH CONVICTS FOR EXECUTION"},"level":"law","status":"active","docNumber":"Executive Order No. 147","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00147_1999.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00147_1999.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18029-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"COMPOSITION.\nThe Conscience Committee shall be\nchaired by the Executive Secretary, with the following as members:\nOne representative\nfrom the social sciences;\nOne representative\nfrom a non-government\norganization involved in\ncampaign; and\nTwo representatives\nfrom church-based organizations.\nThe Committee may call on representatives\nfrom the families of the\naccused and the victim during its deliberations.\nThe members of the Committee from the private sector shall not be\nconsidered as public officials but rather as private sector representativesin\na consultative and recommendatory\n3.\nfollowing functions:\nThe Committee\na review of cases of death convicts tUrned over by the\nSupreme Court to the Office of the President and scheduled for\nexecution; taking into' consideration\nboth humanitarian\nand the demands of social justice; and\nSubmit a recommendation\nto the President on the possible exercise\nof the President's\npower to grant reprieve, commutations,\n4.\nThe Committee\nitsrecommend\nto the President not later than 48 hours before the\nscheduled execution of the convict.\n5.\nGOVERNMENT\nAll agencies and instrumentalities\nof govemment\ndirected to provide assistance to the Committee in the exercise of its\n\n3-\nSEPARABILITY\nIf, for any reason or\nof the provisions\nunconstitutional\nother parts or provisions\nhereof which are\nnot affected thereby shall continue to be in full force and effect.\nSECTIONimmediately-\n7.\nEFFECTIVITY.\nDONE in the City of Manila, this 27th day of August, in the Year of\nour Lord, Nineteen Hundred and Ninety-nine.\n\"}\n/\nprv1S LIBRARY\n-\nBy the President:\n-\n1111~~lllmlllllllllllll\nRONALDO B. ZAMORA\n\".\n..~"}}],"pack":"ph-p157"};
  FT["PH-H18030"] = {"id":"PH-H18030","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG EXECUTIVE ORDER NO.","orig":"MALACAÑANG EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 147","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00147_2002.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00147_2002.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18030-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Functions. The NLDPMO shall have the following\nProvide overall coordination and monitoring of the component\nprograms/projects of the Updated North Luzon Development Plan\n(2001-2004);\nContinue the refinement of the Updated North Luzon Development\nPlan (2001-2004), giving due consideration to existing development\nplans, programs and projects in the area;\nPerform such other functions and responsibilities as the President"}},{"id":"PH-H18030-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Organization and Budget. The organizational structure\nand staffing pattern of the NLDPMO shall be subject to the approval of the\nDepartment of Budget and Management (DBM).\nThe DBM shall determine the funding for the initial operations of the\nNLDPMO and obtain the same from such available sources as the DBM may\nidentify. Henceforth, funding for the operations of the NLDPMO shall be\nincluded in the annual appropriations of the Department of Trade and\nIndustry. Fiscal austerity shall be strictly observed."}},{"id":"PH-H18030-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Repealing Clause. All executive orders, instructions,\nrules and regulations or parts thereof which are contrary or inconsistent\nwith the provisions of this Executive Order are hereby modified or repealed\naccordingly."}},{"id":"PH-H18030-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity. This Executive Order shall take effect\nimmediately.\nCity of Manila, November.\n9 _, 2002.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY BCODE001971\n2"}}],"pack":"ph-p157"};
  FT["PH-H18031"] = {"id":"PH-H18031","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":12,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES \" CREATING THE PHILIPPINE EXTRACTIVE INDUSTRIES TRANSPARENCY INITIATIVE","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES \" CREATING THE PHILIPPINE EXTRACTIVE INDUSTRIES TRANSPARENCY INITIATIVE"},"level":"law","status":"active","docNumber":"Executive Order No. 147","issuingBody":"President of the Philippines","completenessNote":"全文，共 12 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00147_2013.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00147_2013.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18031-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Instituting the Philippine Extractive Industries Transparency\nInitiative. The Philippine Extractive Industries Transparency Initiative (hereinafter\nreferred to as PH-EITI) is hereby instituted."}},{"id":"PH-H18031-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Creation and Composition of the PH-EIT! Multi-stakeholder\nGroup. In accordance with the EITI International Guidelines, the PH-EITI shall be\n@fice ofthe President of the Philiopines\n\nimplemented and operationalized through a multi-stakeholder group (MSG) and\ndecision making body (hereinafter referred to as PH-EITI-MSG). It shall be headed by\nthe Secretary of the DOF as the Chairperson who will be responsible for convening the\ngroup. It shall specifically consist of the following members:\na. Five (5) Government Representatives chosen by the Mining Industry\nCoordinating Council (MICC), created pursuant to Section 9 of EO No. 79,\nwhich will include senior officials, duly deputized to represent their respective\nSecretaries; provided that, local government units shall be represented by the\nUnion of Local Authorities of the Philippines;\nb. Five (5) Business Group Representatives; and\nc. Five (5) Civil Society Organizations (CSOs) Representatives.\nThe Business Group and the CSOs shall each designate five (5) full and five (5)\nalternale representatives to the PH-EITI-MSG. Each organization, upon the decision of\nits members and through its own independent processes and governance mechanisms,\ncan at any time replace their representatives in the PH-EITI-MSG; provided that such\nreplacement shall only serve for the unexpired term of the representative replaced.\nPermanent and alternate members shall attend and participate in the PH-EITI-MSG"}},{"id":"PH-H18031-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Terms of the Members of PH-EITI MSG and Meetings. All\nmembers of the PH-EITI-MSG shall serve for a term of three (3) years. Representatives\nmay be re-appointed subject to the independent processes and governance\nmechanisms of their respective organizations. It shall be the responsibility of each\nsector to ensure the continuity of representation and institutional memory within the PH-\nThe PH-EITI-MSG shall meet quarterly or as often as it may deem necessary.\nThe quorum for such meetings shall require the presence of at least three (3)\nrepresentatives each from the Government, the Business Group and the CSOs. The\nMSG shall make decisions by consensus."}},{"id":"PH-H18031-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Mandates of the PH-EITI-MSG. The PH-EITI-MSG shall have the\nfollowing mandates:\na. Ensure sustained political commitment for the initiative and mobilize\nresources to sustain its activities and goals;\nb. Set the strategic direction required for effectively implementing the initiative in\nthe Philippines;\nc. Assess and seek the removal of barriers to its implementation;\n2\n\nd. Set the scope of the EITI process; and\ne. Ensure that the initiative is effectively integrated in the reform process\noutlined under EO No. 79 and any other related government reform agenda."}},{"id":"PH-H18031-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Powers and Functions of the PH-EITI MSG. The PH-EITI-MSG\nshall have the following powers and functions:\na. Ensure the commitment of the different stakeholders to the implementation of\nb. Define the strategic direction and scope of EITI in the Philippines;\nc. Craft, publish, review, and update a fully costed Country Work Plan in\nconsultation with key PH-EITI stakeholders and oversee the implementation\nd. Produce all regular reports with contextual information about the extractive\nindustries as may be required by PH-EITI implementation;\ne. Establish a mechanism for the EITI reconciliation process;\nSelect and appoint an independent administrator/auditor to reconcile the\ngovernment and industry reports;\ng. Direct and supervise the PH-EITI Secretariat in its various activities and\nestablish its internal rules of procedure;\nh. Through its various members, conduct outreach to, and capability-building of,\nvarious sectors in support of the PH-EITI implementation at national and sub-\nnational levels and communicate and build awareness about EITI and the\nprogress of its implementation in the Philippines; and\ni. Perform such other functions as may be germane to the purpose for which it\nwas created and consistent with this Order and the EITI Principles."}},{"id":"PH-H18031-A6","no":6,"noLabel":{"en":"SECTION 6"},"text":{"en":"PH-EITI Secretariat. The PH-EITI shall be assisted by a PH-EITI\nSecretariat whose composition shall be determined by the Secretary of Finance, in\nconsultation with the PH-EITI-MSG. It shall hold office in the DOF, or such other\ngovernment or private facilities as may be determined by the PH-EITI-MSG.\nThe PH-EITI Secretariat shall be composed of administrative and technical\npersonnel as the PH-EITI-MSG may deem necessary to assist the PH-EITI-MSG in\nefficiently and effectively carrying out its powers and functions. The creation of\nadditional plantilla positions and hiring of additional personnel to carry out the functions\nenumerated herein shall be authorized in coordination with, and subject to the approval\ndefarp al the droeident aff no sent tantros\n3\n\nof the Department of Budget and Management (DBM)."}},{"id":"PH-H18031-A7","no":7,"noLabel":{"en":"SECTION 7"},"text":{"en":"Engagement of Consultants. The PH-EITI shall have the authority\nto engage the services of consultants or advisers as it may deem necessary to\naccomplish its objectives."}},{"id":"PH-H18031-A8","no":8,"noLabel":{"en":"SECTION 8"},"text":{"en":"Creation of the PH-EITI Technical Working Group and\nAssistance to PH-EITI. PH-EITI may create Technical Working Groups composed of\ndepartments, bureaus, offices, agencies or instrumentalities of the Government,\nincluding government-owned and controlled corporations, and representatives of the\nbusiness sector and CSOs. All such agencies, offices, and representatives are hereby\ndirected to extend such assistance and cooperation as the PH-EITI may need in the\nexercise of its powers, execution of its functions, and discharge of its duties and\nresponsibilities."}},{"id":"PH-H18031-A9","no":9,"noLabel":{"en":"SECTION 9"},"text":{"en":"Funding. Upon the effectivity of this Order, the amount necessary\nto carry out its implementation shall be charged against the budget of the DOF.\nThereafter, appropriations for the PH-EITI implementation shall be included in the\nbudget of the DOF.\nThe PH-EITI shall have the authority to receive, disburse, and manage financial\naid or grants from foreign and domestic entities to be utilized for the implementation of\nits objectives subject to the usual accounting and auditing rules and regulations."}},{"id":"PH-H18031-A10","no":10,"noLabel":{"en":"SECTION 10"},"text":{"en":"Separability. If any provision of this Order is declared invalid or\nunconstitutional, the other provisions unaffected shall remain valid and subsisting."}},{"id":"PH-H18031-A11","no":11,"noLabel":{"en":"SECTION 11"},"text":{"en":"Repealing Clause. All orders, proclamations, rules, regulations, or\nparts thereof, which are inconsistent with any of the provisions of this Order are hereby\nrepealed or modified accordingly."}},{"id":"PH-H18031-A12","no":12,"noLabel":{"en":"SECTION 12"},"text":{"en":"Effectivity. This Order shall take effect immediately upon\npublication in a newspaper of general circulation.\nDONE, in the City of Manila, this 26th day of November\nour Lord, Two Thousand and Thirteen.\n, in the year of\nBy the President:/\nPAQUITO N. OCHOA, JR.\nExecutive Secretary\nCERTIFIED COPY.\nífico of the Bresivent of the Bhilinomies\n46 12-2-2013\nMARIANITO M. DIMÃANDAL\nDIKECTOR IV 212-2-013\nMALACANANG RECORDS BEFICI"}}],"pack":"ph-p157"};
  FT["PH-H18032"] = {"id":"PH-H18032","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AMENDED, TO EXTEND THE TERM OF THE BORACAY INTER- AGENCY TASK FORCE","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES AMENDED, TO EXTEND THE TERM OF THE BORACAY INTER- AGENCY TASK FORCE"},"level":"law","status":"active","docNumber":"Executive Order No. 147","issuingBody":"President of the Philippines","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00147_2021.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00147_2021.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18032-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Amendment. Section 1 of EO No. 53, as amended, is hereby further\namended to read as follows:\n\"Section 1. Creation of the Boracay Inter-Agency Task Force.\nThe Boracay Inter-Agency Task Force (\"Task Force\") is hereby created, to\nbe composed of the following:\nThe Task Force shall be deemed dissolved on 30 June 2022,\nunless extended or sooner terminated by the President.\""}},{"id":"PH-H18032-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Unaffected provisions. Except as expressly modified by this Order, all\nother provisions of EO No. 53, as amended, shall remain in full force and effect.\n2"}},{"id":"PH-H18032-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Repeal. All orders, rules and regulations, issuances, or any part thereof\ninconsistent with the provisions of this Order, are hereby repealed or modified accordingly."}},{"id":"PH-H18032-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Effectivity. This Order shall take effect immediately.\nDONE in the City of Manila, this 14th\nof our Lord, Two Thousand Twenty One.\nday of September\nBy the President:\nSALVADOR C. MEDIALDEA\nExecutive Secretary\nRRPUBLIC OF THE PHILIPPINES\nOffice of the President\nMALACASING RECORDS OFFICE\nCERTIMED COPY\nATTY. CONCEACION BATT L. TERROLITO-ENAS\nDIRECTOR. IV\n3"}}],"pack":"ph-p157"};
  FT["PH-H18033"] = {"id":"PH-H18033","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1938/eo_148_1938.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Policy Regarding Applications for Public Lands and Public Forests to Be Devoted for Pasture Purposes","orig":"Policy Regarding Applications for Public Lands and Public Forests to Be Devoted for Pasture Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 148","issuingBody":"President of the Philippines","promulgatedDate":"1938-04-22","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00148_1938_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00148_1938_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18033-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 148, April 22, 1938 ]\nPOLICY REGARDING APPLICATIONS FOR PUBLIC LANDS AND PUBLIC FORESTS TO BE\nDEVOTED FOR PASTURE PURPOSES\nWith a view to making more effective the enforcement of the provisions of the land laws on area limitations\nand in order to avoid the clandestine occupation of public lands and public forests in violation of the said\nlaws, the following rules are hereby promulgated:\n1. Small land holdings shall be interspersed between large areas of public lands which are applied for pasture\npurposes either under the Forest Law or under the Public Land Law.\n2. If a parcel of land applied for pasture purposes adjoins public lands, such adjacent public lands shall be\ndisposed of only in the form of small parcels.\n3. In case the land applied for pasture purposes abuts upon another tract of land already applied for the same\npurpose, a certain portion of the land newly applied for and immediately contiguous to the latter should\nlikewise be disposed of in the form of small land holdings.\n4. As far as practicable, the pasture lessees or permittees shall be required to fence their pastures so as to\nprevent their cattle from destroying the crops on the adjoining lands. This requirement shall be embodied as\none of conditions in pasture permits or leases that may be granted by the Department of Agriculture and"}}],"pack":"ph-p157"};
  FT["PH-H18034"] = {"id":"PH-H18034","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MaLACAÑANg RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING A NATIONAL HOUSING COUNCIL TO ADVISE THE PRESIDENT OF THE PHILIPPINES ON HOUSING MATTERS","orig":"MaLACAÑANg RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING A NATIONAL HOUSING COUNCIL TO ADVISE THE PRESIDENT OF THE PHILIPPINES ON HOUSING MATTERS"},"level":"law","status":"active","docNumber":"Executive Order No. 148","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00148_1955.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00148_1955.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18034-A1","no":1,"noLabel":{},"text":{"en":"all over the country:\n3. To advise the President on the necessity of legisle-\ntion for the raising and allocation of funds to promote\nprivate housing through aided self-help in the small com-\nmunities as well as to make passible low-rental public\nhousing for low-income groups in principal cities and\nfor research into the most effective use of local raw mate-\nrials for housing and other constructions;\n4. To assist the President in evaluating existing housing\nprojects or programs and in determining how such proj-\nects or programs may be accelerated or improved; and\n5. To make recommendations on such other matters as\nthe President may, from time to time, submit for study\nand consideration.\nThe National Housing Cauncil is hereby authorized to\ncall upon any department, bureau, office, agency, or instru-\nmentality of the Government for such assistance or in-\nformation as may be needed to carry out its duties and\nDone in the City of Manila, this 28th day of December,\nin the year of Our Lord, nineteen hundred and fifty-five,\n1\nand of the Independence of the Philippines, the tenth.\nRAMON MAgSAYSAY\nPresident of the Philippines\nBy the President:\nMARIANO YENKO, JR.\nAssistant Executive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18035"] = {"id":"PH-H18035","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1968/eo_148_1968.html","fetchedAt":"2026-10-28","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"Simplifying Export Procedures of Government Commodity","orig":"Simplifying Export Procedures of Government Commodity"},"level":"law","status":"active","docNumber":"Executive Order No. 148","issuingBody":"President of the Philippines","promulgatedDate":"1968-09-17","completenessNote":"全文，共 9 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00148_1968_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00148_1968_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18035-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"To promote the policy enunciated above it is hereby ordered that all existing procedures\ninvolved in the processing of export papers of government commodity agencies shall be conducted in one\nplace. Such place shall be located at the Bureau of Customs, Port Area, Manila."}},{"id":"PH-H18035-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"To carry out the simplification of export procedures, government commodity agencies shall\nprovide representatives who shall perform the existing functions of their respective offices, relative to export\nprocedures. Such representatives shall be deputized by the Heads of their respective offices to perform the\nfollowing duties:\na. The Inspectors shall undertake all functions pertaining to the inspection, classification, grading, or\nstandardization of export products;\nb. The Senior Examiners shall grant the proper Government Certificate of Indentification and the Certificate\nto Export local products found in order;\nc. The Cashiers shall collect the minimum permit fees and/or service fees required by law from the\nexportation of Philippine products."}},{"id":"PH-H18035-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The government commodity agencies which shall appoint and deputize representatives are:\na. Philippine Tobacco Administration\nb. Philippine Virginia Tobacco Administration\nc. Parks and Wildlife Office\nd. Bureau of Fiber Inspection\ne. Philippine Coconut Administration\nf. Philippine Fisheries Commission\ng. Bureau of Animal Industry\nh. Food and Drug Administration\ni. National Cottage Industries Development Authority\n\nj. Bureau of Plant Industry\nk. Bureau of Standards\nl. Bureau of Internal Revenue\nm. Sugar Quota Administration, other Quota Products Division"}},{"id":"PH-H18035-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The supervision of representatives shall be vested in an Officer-in-Charge who shall be\ndesignated by the National Export Coordinating Center."}},{"id":"PH-H18035-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"All fees collected shall be for the account of the corresponding government agencies which are\nlawfully entitled to such fees."}},{"id":"PH-H18035-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The Auditor General is hereby directed to designate representatives from the General Auditing\nOffice to audit the various cashiers in the collection and disposition of funds."}},{"id":"PH-H18035-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Salaries and other expenses of the personnel detailed by various agencies in accordance with the\npreceding sections shall continue to be for the account of their respective agencies."}},{"id":"PH-H18035-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Equipment and supplies necessary for the efficient performance of the representatives shall be\nprovided for by their respective offices."}},{"id":"PH-H18035-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"This order shall take effect immediately.\nDone in the City of Manila, this 17th day of September, in the year of Our Lord, nineteen hundred and\nsixty-eight.\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) RAFAEL M. SALAS\nExecutive Secretary"}}],"pack":"ph-p157"};
