  FT["PH-H18127"] = {"id":"PH-H18127","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES REDUCTION AND CONDONATION OF REAL PROPERTY TAXES AND INTEREST/PENALTIES ASSESSED ON ThE POWER GENERATION FACILITIES INDEPENDENT POWER PRODUCERS UNDER BUILD-OPERATE-TRANSFER CONTRACTS WITH GOVERNMENT-OWNED OR -CONTROLLED CORPORATIONS","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES REDUCTION AND CONDONATION OF REAL PROPERTY TAXES AND INTEREST/PENALTIES ASSESSED ON ThE POWER GENERATION FACILITIES INDEPENDENT POWER PRODUCERS UNDER BUILD-OPERATE-TRANSFER CONTRACTS WITH GOVERNMENT-OWNED OR -CONTROLLED CORPORATIONS"},"level":"law","status":"active","docNumber":"Executive Order No. 157","issuingBody":"President of the Philippines","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00157_2021.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00157_2021.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18127-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Reduction and Condonation. All liabilities for RPT for CY 2021, including\nany special levy accruing to the Special Education Fund, on property, machinery and\nequipment actually and directly used by IPs for the production of electricity under a\nBuild-Operate-Transfer scheme and similar contracts, whether denominated Power\nPurchase Agreements, Energy Conversion Agreements or other contractual agreements\nwith GOCCs, assessed by LGUs and other entities authorized to impose RPT for all years\nup to CY 2021, are hereby reduced to an amount equivalent to the tax due if computed based\non an assessment level of fifteen percent (15%⅝ of the fair market value of said property,\nmachinery and equipment depreciated at the rate of two percent (2%) per annum, less any\namount already paid by the IPs. All interests and penalties on such deficiency RPT liabilities\nare also hereby condoned and the concerned IPPs are relieved from payment thereof."}},{"id":"PH-H18127-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Application to Future PT Liabilities. All RPT payments made by the\nIPs over and above the reduced amount under Section 1 of this Order shall be applied to\ntheir RPT liabilities for the succeeding years."}},{"id":"PH-H18127-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Compliance by all Government Entities. All concerned departments,\nagencies and instrumentalities of the government, including relevant GOCCs and LGUs, are\nhereby directed to strictly comply with this Order. Any violation of this Order shall be dealt\nwith in accordance with civil service laws and regulations."}},{"id":"PH-H18127-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Repeal. All rules and regulations, or parts thereof which are inconsistent\nwith the provisions of this Order are hereby revoked, amended or modified accordingly."}},{"id":"PH-H18127-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Separability. If any provision of this Order is declared invalid or\nunconstitutional, the other provisions unaffected shall remain valid and subsisting."}},{"id":"PH-H18127-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Effectivity. This Order shall take effect immediately upon its publication\nin a newspaper of general circulation.\nDONE, in the City of Manila, this 16th\nof our Lord, Two Thousand and Twenty-One.\nday of December\nBy the President:\n8 8\nSALVADOR C. MEDIALDEA\nExecutive Secretary\n2\nREPUBLIC OF\nPHILIPPINES\nINTERERE COPE\n1 ATTY. CONCERCION ZION E. TERRORITO-GLAD\n912-14-204. DIRECTOR IV"}}],"pack":"ph-p157"};
  FT["PH-H18128"] = {"id":"PH-H18128","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1938/eo_158_1938.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Organizing the Barrio of Angono, Municipality of Binangonan, Province of Rizal, Into An Independent Municipality Under the Name of Angono","orig":"Organizing the Barrio of Angono, Municipality of Binangonan, Province of Rizal, Into An Independent Municipality Under the Name of Angono"},"level":"law","status":"active","docNumber":"Executive Order No. 158","issuingBody":"President of the Philippines","promulgatedDate":"1938-08-19","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00158_1938_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00158_1938_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18128-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 158, August 19, 1938 ]\nORGANIZING THE BARRIO OF ANGONO, MUNICIPALITY OF BINANGONAN, PROVINCE OF\nRIZAL, INTO AN INDEPENDENT MUNICIPALITY UNDER THE NAME OF ANGONO\nWHEREAS, the inhabitants of the former municipality of Angono have petitioned that the same be separated\nfrom the municipality of Binangonan, Province of Rizal, and organized into an independent municipality;\nNOW, THEREFORE, upon recommendation of the provincial board of Rizal and the Secretary of the Interior,\nand pursuant to the provisions of section sixty-eight of the Revised Administrative Code, the twenty-seven\nmunicipalities of the Province of Rizal, as established by section thirty-eight of the said Code and Executive\nOrder Numbered One hundred and eight, series of nineteen hundred and seventeen, are hereby increased to\ntwenty-eight by separating the barrio of Angono from the municipality of Binangonan and organizing the\nsame into an independent municipality under the name of Angono, with the seat of government in the barrio\nof the same name.\nThe municipality of Binangonan shall consist of its present territory less the territory comprised in the former\nmunicipality of Angono.\nThe organization herein made shall take effect on January first, nineteen hundred thirty-nine, provided that\nprior thereto the Secretary of the Interior shall have certified that the sites for the presidencia, plaza, market,\nand cemetery have acquired and the Secretary of Finance shall have certified as to the financial ability of the\nnew political subdivision to shoulder the expenses of an independent municipality.\nDone at the City of Manila, this nineteenth day of August, in the year of Our Lord, nineteen hundred and\nthirty-eight, and of the Commonwealth of the Philippines, the third.\nMANUEL L. QUEZON\nPresident of the Philippines\nBy the President:\nJORGE B. VARGAS\nSecretary to the President"}}],"pack":"ph-p157"};
  FT["PH-H18129"] = {"id":"PH-H18129","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MaLACAÑAng RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES OCTOBER 26, 1953, CREATING THE MUNICIPAL- ITY OF VICTORIA IN THE PROVINCE OF BOHOL","orig":"MaLACAÑAng RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES OCTOBER 26, 1953, CREATING THE MUNICIPAL- ITY OF VICTORIA IN THE PROVINCE OF BOHOL"},"level":"law","status":"active","docNumber":"Executive Order No. 158","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00158_1956.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00158_1956.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18129-A1","no":1,"noLabel":{},"text":{"en":"Done in the City of Manila, this 16th day of January,\nin the year of Our Lord, nineteen hundred and fifty-six,\nand of the Independence of the Philippines, the tenth.\nRÂMON MAGSAYSAY\nPresident of the Philippines\nBy the President:\nMARIANO YENKO, JR.\nAssistant Executive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18130"] = {"id":"PH-H18130","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1968/eo_158_1968.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Creating the National Intelligence Board","orig":"Creating the National Intelligence Board"},"level":"law","status":"active","docNumber":"Executive Order No. 158","issuingBody":"President of the Philippines","promulgatedDate":"1968-11-19","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00158_1968_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00158_1968_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18130-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 158, November 19, 1968 ]\nCREATING THE NATIONAL INTELLIGENCE BOARD\nPursuant to the powers vested in me by law, I, FERDINAND E. MARCOS, President of the Philippines, do\nhereby create a National Intelligence Board to supersede the National Intelligence Consultative Committee\nwhich was created on July 1, 1949, under Executive Order No. 235.\nThe Board shall be composed of the following members:\nThe Director, National Intelligence Coordinating Agency\nThe Director, National Bureau of Investigation\nThe Chief, Division of Intelligence and Research, Department of Foreign Affairs\nThe Assistant Chief of Staff, J-2, Armed Forces of the Philippines\nThe Assistant Chiefs of Staff for Intelligence of all the major services of the Armed Forces of the Philippines\nand a representative each from the Presidential Economic Staff, and the Presidential Agency for Reforms and\nGovernment Operations shall act as Technical Advisers of the Board.\nThe Board shall advise the Director of the National Intelligence Coordinating Agency on matters pertaining to\nthe integration and coordination of intelligence activities and make recommendations on such other subjects\nas the NICA Director may from time to time submit for study and consideration.\nDone in the City of Manila, this 19th day of November, in the year of Our Lord, nineteen hundred and\nsixty-eight.\n(SGD.) FERDINAND E. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) JOSE J. LEIDO, JR.\nActing Executive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18131"] = {"id":"PH-H18131","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating the \"Tulong Sa Tao Fund\" and for Other Purposes","orig":"Creating the \"Tulong Sa Tao Fund\" and for Other Purposes"},"level":"law","status":"active","docNumber":"Executive Order No. 158","issuingBody":"President of the Philippines","promulgatedDate":"1987-04-13","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00158_1987_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00158_1987_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18131-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"Creation of the Revolving Fund. There is hereby created a revolving fund to be known as the \"Tulong\nSa Tao Fund\", hereinafter referred to as the \"Fund\", which shall be administered by the Ministry of Trade and\nIndustry, hereinafter referred to as the \"Ministry.\""}},{"id":"PH-H18131-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"Composition of the Fund: purposes thereat. (1) The fund shall consist of an initial seed money in the\namount of one hundred million pesos which is hereby allocated and out of which, thirty million pesos is\nhereby released from the applicable lump-sum fund of the National Government in the 1986 General\nAppropriations Act to the Ministry, to be utilized for the Self-Employment Loan Assistance component of the\n\"Tulong Sa Tao\" Employment Generation Program. The balance of seventy million pesos shall likewise be\nreleased from the lump-sum loan fund of the National Government in the 1987 General Appropriations Act to\nthe Ministry, to be allocated among the \"Tulong Sa Tao\" Employment Generation Program's components as\nherein provided in the proportion to be determined by the Ministry, and shall be utilized for the purpose\nindicated below, as follows:\nCOMPONENT/FUND\n(1) Self-employment\nLoan Assistance\n(2) Subcontracting\nTo encourage self-employment by providing loans to enterpreneurs\nTo encourage subcontracting by providing financing for subcontracting businesses.\n(b) All income and interest earned by the Fund shall accrue to the said Fund and may be used for relending,\nconsistent with the purposes of this Executive Order, as well as to defray the operational, administrative, and\nother expenses related to the implementation of this Executive Order. The compensation of contractual and\ncasual employees hired to assist in the operations under this Executive Order may be charged to the Fund\nsubject to the rules and regulations issued by the Office of Budget and Management."}},{"id":"PH-H18131-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"Role of Financial Institutions. The initial seed money authorized for outlay under this Executive Order\nshall be remitted to the government financial institutions selected by the Ministry. It shall be constituted and\nadministered as trust funds under such terms conditions as may be agreed upon by the Ministry and the\nfinancial institutions concerned."}},{"id":"PH-H18131-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"Powers and Functions of the Minister of Trade and Industry relative to the administration of the Fund.\nThe Minister shall have the following powers and functions relative to the administration of the Fund:\n(a) To identify areas and localities that will be given priority in the implementation of the \"Tulong Sa Tao\"\nEmployment Generation Program;\n(b) To designate the units, officers, and staff of the Ministry that shall implement the \"Tulong Sa Tao\"\nEmployment Generation Program;\n(c) To select the government financial institutions that will administer the trust fund;\n(d) To determine the amount of loans to borrowers from the Fund, including the private voluntary\norganizations, rural banks and development banks; the qualifications of borrowers; and the terms and\nconditions of the loans;\n(e) To exercise such other powers and functions required for the success of the \"Tulong Sa Tao\" Employment\nGeneration Program."}},{"id":"PH-H18131-A5","no":5,"noLabel":{"en":"Sec 5"},"text":{"en":"Reports. The Ministry shall submit to the Office of Budget and Management a quarterly report of the\nincome and expenditures of the Fund."}},{"id":"PH-H18131-A6","no":6,"noLabel":{"en":"Sec 6"},"text":{"en":"Rules and Regulations. The implementing rules and regulations of this Executive Order shall be jointly\nformulated by the Ministry of Trade and Industry and the Office of Budget and Management."}},{"id":"PH-H18131-A7","no":7,"noLabel":{"en":"Sec 7"},"text":{"en":"Effectivity. This Executive Order shall take effect immediately.\nDone in the City of Manila, this 13th day of April in the year of Our Lord, nineteen hundred and eighty-seven."}}],"pack":"ph-p157"};
