  FT["PH-H18305"] = {"id":"PH-H18305","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES","orig":"MALACANANG BY THE PRESIDENT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 177","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00177_1999.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00177_1999.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18305-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"of Executive Order 76 provides the composition of the\nCommission to include, among others, the Mayor of a Negros Oriental and Cebu\nmunicipality/city along the Tafion Strait;\nWHEREAS, the coverage of the Commission includes one city and three\nmunicipalities ofNegros Occidental located along the Taiion Strait;\nWHEREAS, said city and municipalities are not represented in the Tafion Strait\nCommission;\nNOW, THEREFORE,\nI, JOSEPH EJERCITO ESTRADA, President of the\nPhilippines, by the powers vested in me by law, do hereby amend Section 3 of Executive\nOrder 76, to include as member of the Commission the Mayor of a Negros Occidental\nMunicipality/City\nalong Tallon Strait.\nThis Executive Order shall take effect immediately.\nDONE in the City of Manila this l~\nLord, Nineteen Hundred and Ninety-Nine.\n, in the year of our\nPMS LIBRARY\nBy the President:\n~\nRONALDO B. ZAMORA\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18306"] = {"id":"PH-H18306","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG TRANSFERRING THE PHILIPPINE NATIONAL STUD BOOK OF THE THEN NATIONAL STUD FARM, FROM THE DEPARTMENT OF AGRICULTURE TO THE OFFICE OF THE PRESIDENT AND RE-ASSIGNING IT TO THE PHILIPPINE RACING COMMISSION","orig":"MALACAÑANG TRANSFERRING THE PHILIPPINE NATIONAL STUD BOOK OF THE THEN NATIONAL STUD FARM, FROM THE DEPARTMENT OF AGRICULTURE TO THE OFFICE OF THE PRESIDENT AND RE-ASSIGNING IT TO THE PHILIPPINE RACING COMMISSION"},"level":"law","status":"active","docNumber":"Executive Order No. 177","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00177_2003.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00177_2003.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18306-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Transfer of the Philippine National Stud Book to the Office of the President.\nThe operations relevant to the maintenance of the Philippine National Stud Book, including the\nappropriate personnel, assets and resources, is hereby transferred from the Department of\nAgriculture to the Office of the President, and then re-assigning it to the Philippine Racing\nCommission."}},{"id":"PH-H18306-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Rules and regulations to Implement the Transfer. The Secretary of Agriculture\nand a Senior official from the Office of the President shall formulate the rules and regulations to\nimplement the transfer of the Philippine National Stud Book, and re-assignment thereof to the\nPhilippine Racing Commission."}},{"id":"PH-H18306-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Repealing Clause.- All Executive Orders, rules and regulations and other\nissuances or parts thereof which are inconsistent with the provisions of this Executive Order, are\nhereby revoked or modified accordingly.\nPOMA Hologram / 18278\n\nDONE in the City Manila, thid day of February\nin the year of our Lord, two\nthousand and three.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY BCODE009418"}}],"pack":"ph-p157"};
  FT["PH-H18307"] = {"id":"PH-H18307","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1938/eo_178_1938.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Prescribing the Procedure, Including Modes of Proof, in Cases Before Courts-Martial, Courts of Inquiry, Military Commissions and Other Military Tribunals of the Army of the Philippines","orig":"Prescribing the Procedure, Including Modes of Proof, in Cases Before Courts-Martial, Courts of Inquiry, Military Commissions and Other Military Tribunals of the Army of the Philippines"},"level":"law","status":"active","docNumber":"Executive Order No. 178","issuingBody":"President of the Philippines","promulgatedDate":"1938-12-17","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00178_1938_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00178_1938_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18307-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 178, December 17, 1938 ]\nPRESCRIBING THE PROCEDURE, INCLUDING MODES OF PROOF, IN CASES BEFORE\nCOURTS-MARTIAL, COURTS OF INQUIRY, MILITARY COMMISSIONS AND OTHER MILITARY\nTRIBUNALS OF THE ARMY OF THE PHILIPPINES\nPursuant to the authority vested in me by article 37 of Commonwealth Act No. 408, entitled “An Act for\nmaking further and more effectual provision for the national defense by establishing a system of military\njustice for persons subject to military law,” I, MANUEL L. QUEZON, President of the Philippines, do hereby\nprescribe the following rules of procedure, including modes of proof in cases before courts-martial, courts of\ninquiry, military commissions, and other military tribunals in the Army of the Philippines, and direct them to\nbe published for the government of all concerned. These rules shall be known and designated as the Manual\nfor Courts-Martial, Philippine Army, and shall be in force and effect from this date.\nDone at the City of Manila, this seventeenth day of December, in the year of Our Lord, nineteen hundred and\nthirty-eight, and of the Commonwealth of the Philippines, the fourth.\nMANUEL L. QUEZON\nPresident of the Philippines\nBy the President:\nJORGE B. VARGAS\nSecretary to the President"}}],"pack":"ph-p157"};
  FT["PH-H18308"] = {"id":"PH-H18308","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING A COMMISSION TO STUDY THE PROB- LEMS OF THE RICE INDUSTRY AND THE RE- CURRENT RICE SHORTAGE AND MAKE RECOM- MENDATIONS ON A CONSOLIDATED SOLUTION TO THE RICE PROBLEM.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES CREATING A COMMISSION TO STUDY THE PROB- LEMS OF THE RICE INDUSTRY AND THE RE- CURRENT RICE SHORTAGE AND MAKE RECOM- MENDATIONS ON A CONSOLIDATED SOLUTION TO THE RICE PROBLEM."},"level":"law","status":"active","docNumber":"Executive Order No. 178","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00178_1948.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00178_1948.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18308-A1","no":1,"noLabel":{},"text":{"en":"distributing and marketing cleaned rice to consumers all\nover the Philippines, and of determining various measures\nthat will promote the production of supplementary food\ncrops and the adoption of agricultural industries that will\nprovide off-season employment for the farm population.\nThe Commission shall also undertake a study of all laws\nand regulations affecting the rice industry and recommend\nareas of public and private lands suitable for immediate\ndevelopment; submit plans to bring these areas into im-\nmediate cultivation for the production of rice and other\nfood crops, and recommend means and method for the\nspeedy advancement of Philippine rice production.\nEach member of the Commission who is not in the gov-\nernment service shall receive a per diem to be fixed by\nthe President.\nThe Commission is hereby empowered and anthorized\nto call upon any Department, bureau, office, agency or\ninstrumentality of the Government, including the corpo-\nrations owned or controlled by it, for such assistance or\ninformation as it may need in the performance of its func-\ntions; and for the purpose of securing needed information,\nit shall have access to, and the right to examine, any\nbooks, documents, papers, or records thereof.\nAny clerical assistance or office supplies that may be\nneeded by the Commission shall be provided by the Na-\ntional Economic Council.\nThe Commission shall submit its report and recommenda-\ntions to the President of the Philippines not later than\nAdministrative Order No. 20, dated December 3, 1946,\nis hereby repealed.\nDone in the City of Manila, this Ist day of October, in\nthe year of Our Lord, nineteen hundred and forty-eight,\nand of the Independence of the Philippines, the third.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18309"] = {"id":"PH-H18309","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"M.A..LACANANG RESIDENCE) OF THE PRESIDENT OF. THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF SURABAY IN THE PROVINCE OF ZAMBOANGA DEL SUR","orig":"M.A..LACANANG RESIDENCE) OF THE PRESIDENT OF. THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF SURABAY IN THE PROVINCE OF ZAMBOANGA DEL SUR"},"level":"law","status":"active","docNumber":"Executive Order No. 178","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00178_1965.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00178_1965.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18309-A1","no":1,"noLabel":{},"text":{"en":"The municipality of Surabay shall begin to exist upon thb\nappointment and qualification of the Mayor, Vice-Mayor\nand a majority of the councilors thereof.\nDone in the City of Manila, this 9th day of October,\nin the year of Our Lord, nineteen hundred and sixty-five.\nBy the President:\nSALVADOR L. MARINO\nDroSDADO MACAP AGAL\nPTesident of the Philippines\nActing Executive SecTeta1'Y"}}],"pack":"ph-p157"};
  FT["PH-H18310"] = {"id":"PH-H18310","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRISIDENT OF THE PHILIPPINES CREATING THE FANAY DEVELOPMENT PLANNING BOARD","orig":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRISIDENT OF THE PHILIPPINES CREATING THE FANAY DEVELOPMENT PLANNING BOARD"},"level":"law","status":"active","docNumber":"Executive Order No. 178","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00178_1969.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00178_1969.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18310-A1","no":1,"noLabel":{},"text":{"en":"4.\n56\n6.\nview of affecting an integrated aad\nsystonatic coordination of plans and\nactivities in furtherance of the re-\ngional socio-econcnic developent\nTo nake recomendations to the Pre-\nsident through the Committee on Ro-\nfional Planing on any matter concer-\nning Panay regional planning or affec-\nting the plans and activities thereof;\nTo advise or assist the local planning\nboards within the region on phases of\norganization or operation or irl any\nother natter referred to it by such\nTo enlist and accept such technical\nassistance or finarcial support as it\nmay deem ossential to the proper dis-\ncharge of its task;\n7. To porform such other fictions as way\nbe directed by the President.\nThe Board, in the pursuit of its objectives,\nshall coordinate with the Connittce on Rogional\nIlamming created under Administrative Order No.\n, 1965.\nAll expenscs necossary for\nthe operations and projocts of the Panay Develop-\nment Planning Board shall be for the account of\nthe member provinces and cities unloss otherwise\nprovided for by law.\nThe Board shall bu composed of the Governors\nshall elect a Chairan and Vice Chairma from\nacne ticuselves.\nAlL departents offices, , burcaus, agencies,\nand other government ontities shall render assis-\ntance to and coordinate with the Panay Developont\nPlanning Board on such nattere affecting the dovelo\nDont of the Panoy region.\n201\nDone in the City of Manila, this 21st day of\nApril, in the vear of Our Lord,\nand sixty-nine.\n, nineteen hundred\n(SGD.) FERDINAND I. MARCOS\nPresident of the Philippines\nBy the Fresident:\n(SGD.) RAFAEL M. SALAS\nExecutive Secretary\n202"}}],"pack":"ph-p157"};
  FT["PH-H18311"] = {"id":"PH-H18311","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"EXECUTIVE ORDER l~O. THE STA1'UTORY DAILY ~1I~Ir-1U~1 WAGES AFTER Il~TEGRATING THE COST OF LIVIl-!G ALLO~'JANCES Ul'~DER \\~AGE ORf)ERS NOS.","orig":"EXECUTIVE ORDER l~O. THE STA1'UTORY DAILY ~1I~Ir-1U~1 WAGES AFTER Il~TEGRATING THE COST OF LIVIl-!G ALLO~'JANCES Ul'~DER \\~AGE ORf)ERS NOS."},"level":"law","status":"active","docNumber":"Executive Order No. 178","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00178_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00178_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18311-A1","no":1,"noLabel":{},"text":{"en":"1\nCOLAs under\n\\oJ.age Orders\n1987\n3,\nCOLA under Wage Ol-der No.October\n1,1987\nCOLAs under \\-Jage Orders\n..' SECTION 2. -The\nJ...abor and Employment,\nas Chairman\n1iJage~' Council,\npromulgate\nthe pecessary\nand regulations\nto implement\nthisExecutive-Order.\n;..\n-2\n::;:':;:'\n: ;:;!\n':.\nregulatio11S\ninconsistent\naccord-ingly.\n.\n-\nBy the President:\n.\n...'\n'..,/ ~~~\"'.7~\n-\n/J-'OKER P. AF.ROYO\n'.Je 'Secretary\n.~\n~\n:,. :\n\"\n,\n~~;"}}],"pack":"ph-p157"};
  FT["PH-H18312"] = {"id":"PH-H18312","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"CREATING THE NATIONAL POLICE TASK FORCE ON PROFESSIONAL SQUATTERS AND SQUATTING SYNDICATES","orig":"CREATING THE NATIONAL POLICE TASK FORCE ON PROFESSIONAL SQUATTERS AND SQUATTING SYNDICATES"},"level":"law","status":"active","docNumber":"Executive Order No. 178","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00178_1999.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00178_1999.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18312-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"FUNCTIONS.\nIn coordination with the National Committee\nSyndicates\nProfessional\nidentification\nof professional\nsquatting syndicates including the names of public officials\nindividuals\ntolerating the commission of the act;\nConduct surveillance\nactivities to check and verify initial\nintelligence information gathered concerning the identities of\nsuspected professional squatters and squatting syndicates\nthe names of public\nand/ or private\nindividuals\nabetting or tolerating the commission of the act;\nClosely coordinate\nProsecutor's office and the\nconcerned local government units in gathering evidence, as\nwell as testify during court proceedings to ensure the speedy\nprosecution\nidentified\nprofessional\nsquatting syndicates;\nProvide police protection to victims of squatter syndicates\nprofessional\nbeneficiaries of the government's housing program, who may\nhave been victimized in various forms such as collection of\nexorbitant\ndisinformation;\nDirect local police chiefs, through the PNP regional directors,\nto extend full support and assistance to the Local Committee\n.,\n.'1\n'\"\n\nAgainst.. Squatting\nSyndicates and Professional Squatters\ncreated pursuant\nto Executive Order No. 129, in line with\nintensified\nsyndicates\nprofessional squatters;\nSubmit regular report on its activities and accomplishments\nto the President, through the Presidential Commission on\nMass Housing (PCMH); and,\nother functions as may be directed by the\nCLAUSE. All executive orders,\nregulations and other isuuances or parts thereof inconsistent with this\nExecutive Order are hereby repealed or modified accordingly.\nimmediately.\nEFFECTIVITY.\nThis Executive Order shall take effect\nDone in the City of Manila, this 2~~day of November in the year of\nour Lord, nineteen hundred and ninety-nine.\n,/\nBy the President:\nRONALDO B. ZAMORA\nExecutive Secretary\nIIIIIIII !IIIIIIIIIIIIIIIIIIIIIIIIIIII\nPMS LIBRARY BCODECO4330"}}],"pack":"ph-p157"};
  FT["PH-H18313"] = {"id":"PH-H18313","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES DEVOLVING TO THE AUTONOMOUS REGIONAL GOVERNMENT OF THE AUTONOMOUS REGION IN MUSLIM MINDANAO CERTAIN POWERS AND FUNCTIONS OF THE DEPARTMENT OF SCIENCE AND TECHNOLOGY, AMENDING","orig":"MALACAÑANG PMS LIBRARY BY THE PRESIDENT OF THE PHILIPPINES DEVOLVING TO THE AUTONOMOUS REGIONAL GOVERNMENT OF THE AUTONOMOUS REGION IN MUSLIM MINDANAO CERTAIN POWERS AND FUNCTIONS OF THE DEPARTMENT OF SCIENCE AND TECHNOLOGY, AMENDING"},"level":"law","status":"active","docNumber":"Executive Order No. 178","issuingBody":"President of the Philippines","completenessNote":"全文，共 10 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00178_2003.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00178_2003.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18313-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Transfer of Powers and Functions. --- In addition to the\npowers and functions of the DOST previously devolved to the ARG pursuant to\nPOMA Hologram * 18371\n\nExecutive Order No. 425 (Series of 1991), the following powers and functions are\nhereby devolved from DOST to the ARG:\na) Administration of Scientific and Technological (S&T Scholarships,\nAwards and Grants;\nb) Development and Improvement of S&T Education and Training;\nc) Administration of S&T Incentive and Career System;\nd) Conduct of Research and Development (R&D) on Information Technology\nand Advanced Fields; and\ne) Venture Financing.\nThe identification and selection of scholars through nationwide competition\nshall be retained by the DOST National, while implementation and management\nthereof shall be undertaken by the ARG."}},{"id":"PH-H18313-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"S&T Programs and Projects. Consistent with the devolved powers\nand functions, the ARG shall formulate and develop S&T programs and projects, such\nas but not limited to the following:\na. Technology Transfer, Promotion and Commercialization;\nb. Research and Development;\nc. Science and Technology Services;\nd. S&T Culture;\ne. S&T Manpower and Infrastructure;\nf. Information Systems and Data Bank;\ng. S&T Institutional Linkages; and\nh. S&T Advocacy."}},{"id":"PH-H18313-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Planning and Programming. DOST shall involve DOST-ARMM in\nall its planning and programming activities to ensure that DOST-ARMM priorities are\ntaken into account and the standards are in accordance with the national $ & T Plan."}},{"id":"PH-H18313-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"Coordination of Programs and Projects. For purposes of\ndevelopmental activities in the region and to ensure consistency with the National\nS&T plan, the DOST-ARMM shall:\na. Coordinate with the DOST and DOST Councils and Institutes for technical\nassistance requirements and for S&T related activities;\nb. Be involved in the S&T programs and projects that are implemented in the\nregion (planning, programming and implementation stages) of DOST and\nDOST Councils and Institutes; and\nc. Be a member of the Mindanao DOST Cluster Organization (MindaDOST)\nas a component region in Mindanao.\n•\n21"}},{"id":"PH-H18313-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"Personnel. The following rules shall govern the personnel of the\nDOST assigned in the Province of Basilan, except Isabela City, and the City of\na. All plantilla positions, filled and unfilled effectively assigned to, or with\nthe Province of Basilan, (except Isabela City) and Marawi City as their\nofficial station, shall be placed immediately under the control and\nsupervision of the ARG.\nb. Personnel absorbed by the ARG shall retain their seniority rights,\ncompensation, and other benefits in accordance with Civil Service laws,\nrules and regulations.\nc. Personnel declining to be absorbed by the ARG shall have the following\nc. 1 Retirement - All affected personnel qualified for retirement may\nelect retirement, as may be provided by law. All benefits, including payment\nof accrued leave credits, that may be lawfully given to affected employees by\nvirtue of their transfer, retirement or separation from service shall be paid\nwithin one (1) month from the filing of the necessary clearance and other\npertinent documents.\nc.2 Transfer - Affected personnel shall be given priority in hiring\nfor existing vacant positions in other government agencies, subject to\ncompliance with established qualification standards set by the receiving\nResignation - Separated personnel not eligible for retirement\nunder existing laws shall be entitled to all benefits provided under existing\nCivil Service Laws."}},{"id":"PH-H18313-A6","no":6,"noLabel":{"en":"SEC 6"},"text":{"en":"Assets, Equipment and Budget. All assets, equipment, budgetary\nallocation and properties being utilized or programmed for use for the Province of\nBasilan and the City of Marawi shall be turned-over to the ARG of the ARMM, with\nthe exception of the budget allocation for teacher training which is fixed at the\nnational level."}},{"id":"PH-H18313-A7","no":7,"noLabel":{"en":"SEC 7"},"text":{"en":"Implementing Rules. DOST, in close coordination with the ARG,\nshall issue implementing rules and regulations to effect the devolution and turn-over\nwithin ninety (90) days from effectivity of this Executive Order."}},{"id":"PH-H18313-A8","no":8,"noLabel":{"en":"SEC 8"},"text":{"en":"Date of Transfer. The DOST shall effect full transfer of its\nfunctions, personnel, assets, equipment and judget within 90 days following the.\neffectivity of this Executive Order.\n31\nPORA Hologram / 18373"}},{"id":"PH-H18313-A9","no":9,"noLabel":{"en":"SEC 9"},"text":{"en":"Repealing Clause. All laws, decrees, orders, rules and regulations.\nand other issuances or parts thereof, which are inconsistent with this Executive Order\nare hereby repealed, modified and amended accordingly."}},{"id":"PH-H18313-A10","no":10,"noLabel":{"en":"SEC 10"},"text":{"en":"Effectivity. This Executive Order shall take effect fifteen (15) days\nafter its publication in a national newspaper of general circulation and one local\nnewspaper of general circulation in the ARMM.\nDONE in the City of Manila, this 2774 day of February in the year\nof our Lord, two thousand and three.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPMS LIBRARY BCODE009562\nPare Hologram • 18374\n4,"}}],"pack":"ph-p157"};
  FT["PH-H18314"] = {"id":"PH-H18314","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ADJUSTING THE DIVIDEND RATE OF THE FOOD TERMINAL, INC. FOR ITS 2012 NET","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES ADJUSTING THE DIVIDEND RATE OF THE FOOD TERMINAL, INC. FOR ITS 2012 NET"},"level":"law","status":"active","docNumber":"Executive Order No. 178","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00178_2015.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00178_2015.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18314-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The percentage of net earnings to be declared and remitted by the FTI\nas dividends to the National Government, as required under Section 5 of RA 7656, is\nauthorized to be adjusted downward from fifty percent (50%) to thirty-eight and 1/2 percent\n(38.5%), or an estimated total amount of PhP5.96 Billion for 2012."}},{"id":"PH-H18314-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"The adjusted dividend rate set forth in Section 1 above is only applicable\nto the 2012 net earnings of the FTI."}},{"id":"PH-H18314-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"This Order shall take effect immediately.\nDONE in the City of Manila, this 18 thday of February, in the year of our Lord, Two\nThousand and Fifteen.\nBy the President.\nPAQUITO N. OCHOA, JR.\nExecutive Secretary\nCERTIFIED COPY\ndefseo al the Brestven, duty\nTHE PRESIDENT OF THE PHILIPPINES\n81 2-2-749\nMARIANITO M. DIMAANDAL\nDIRECTON IN 2-25-26\nMALACARANG RECORDS@EFF"}}],"pack":"ph-p157"};
  FT["PH-H18315"] = {"id":"PH-H18315","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1938/eo_179_1938.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Designating a Chief of Staff Under the Provisions of Commonwealth Act No. 312","orig":"Designating a Chief of Staff Under the Provisions of Commonwealth Act No. 312"},"level":"law","status":"active","docNumber":"Executive Order No. 179","issuingBody":"President of the Philippines","promulgatedDate":"1938-12-31","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00179_1938_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00179_1938_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18315-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 179, December 31, 1938 ]\nDESIGNATING A CHIEF OF STAFF UNDER THE PROVISIONS OF COMMONWEALTH ACT NO. 312\nUnder the authority contained in section twenty-two of Commonwealth Act Numbered One, known as “The\nNational Defense Act,” as amended by Commonwealth Act Numbered Three hundred twelve, the following\nchanges in the General Staff Corps in the Army of the Philippines are hereby announced:\n(a) Major General Paulino Santos, Regular Force, is hereby relieved as Chief of Staff at the close of the day\non December thirty-first, nineteen hundred thirty-eight, and will be retired from active service as of the same\n(b) Major General Basilio J. Valdes, Regular Force, Deputy Chief of Staff, is hereby designated Chief of Staff\nVice Major General Paulino Santos, and will assume the duties prescribed for that Office in the National\nDefense Act and in pertinent executive orders, effective January first, nineteen hundred and thirty-nine."}}],"pack":"ph-p157"};
  FT["PH-H18316"] = {"id":"PH-H18316","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES FURTHER EXTENDING THE PERIOD FIXED IN AD. MINISTRATIVE ORDER NO. 54, DATED MAY 7,","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES FURTHER EXTENDING THE PERIOD FIXED IN AD. MINISTRATIVE ORDER NO. 54, DATED MAY 7,"},"level":"law","status":"active","docNumber":"Executive Order No. 179","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00179_1948.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00179_1948.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18316-A1","no":1,"noLabel":{},"text":{"en":".\n1948, AS EXTENDED BY EXECUTIVE ORDER\nNO. 163, DATED AUGUST 12, 1948, WITHIN\nWHICH THE COMMITTEE CREATED TO EXA-\nMINE THE ACTUAL CONDITIONS IN THE SUR-\nPLUS PROPERTY COMMISSION SHALL SUBMIT\nITS REPORT AND RECOMMENDATIONS.\nBy virtue of the powers vested in me by law, I, Elpidio\nQuirino, President of the Philippines, do hereby further\nextend up to October 31, 1948, the period fixed in Admin-\nistrative Order No. 54, dated May 7. 1948, as extended\nby Executive Order No. 163, dated August 12, 1948, with-\nin which the Committee therein created to examine the ac-\ntual conditions in the Surplus Property Commission shall\nsubmit its report and recommendations to the President.\nDone in the Citv of Manila, this 2nd day of October, in\nthe year of Our Lord, nineteen hundred and forty-eight,\nand of the Independence of the Philippines, the third.\nELPIDIO QUIRINO\nPresident of the Philippines\nBy the President:\nTEODORO EVANGELISTA\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18317"] = {"id":"PH-H18317","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF DITAY IN THE PROVINCE OF ZAMBOANGA DEL SUR","orig":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY THE PRESIDENT OF THE PHILIPPINES CREATING THE MUNICIPALITY OF DITAY IN THE PROVINCE OF ZAMBOANGA DEL SUR"},"level":"law","status":"active","docNumber":"Executive Order No. 179","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00179_1965.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00179_1965.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18317-A1","no":1,"noLabel":{},"text":{"en":"Engineer of Zamboanga del Sur based on the Map of said proposed\nmunicipality, scale 1 :100,000, now on file in this Office)\nThe municipality of Siay shall have its /present territory\nminus the portions thereof which are included in the ter-\nritory of the municipality of Ditay as delimited above.\nThe municipality of Ditay shall beg.in to exist upon the\nappointment and q.ualification of the Mayor, Vice-Mayor\nand a majority of the councilors thereof.\nDone in the City of Manila, this 9th day of October, in\nthe year of Our Lord, nineteen hundred and sixty-five.\nBy the Presdent:\nSALVADOR L. MARINO\nDroSDADO MACAPAGAL\nPresident of the Philippines\nActing Executive Sec1'etary"}}],"pack":"ph-p157"};
  FT["PH-H18318"] = {"id":"PH-H18318","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE FHILIFPINES BY THE PRESIDENT OF THE PHILIFFINES EXECUTIVE ORDER NO.","orig":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE FHILIFPINES BY THE PRESIDENT OF THE PHILIFFINES EXECUTIVE ORDER NO."},"level":"law","status":"active","docNumber":"Executive Order No. 179","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00179_1969.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00179_1969.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18318-A1","no":1,"noLabel":{},"text":{"en":"To provide a reservoir of qualified\nairmen, technicians and aviation\nmaterial and facilities from which\nthe government may readily draw during\npeace or wartime emergencies;\nTo promote national enthusiasm in\naviation, particularly among the youth\nTo encourage and provide qualified\nFilipino civilians such resources, in-\ncentives, or services for the develop-\nment of aviation throughout the length\nand breadth of the archipelago; and\nTo assist and cooperate with or other-\nwise provide effective assistance to\nvarious agencies of the government in\nthe interest of national welfare and\nThe, Chier or Staff,\nshall, with the ap-\nproval of the Secretary of National Defense, issue\nrules and regulations to implement this Order.\nAll Executive Orders in conflict herewith are\nhereby revoked or amended accordingly.\nDone in the City of Manila, this 24th day of\nApril, in the year of Our Lord, nineteen hundred\nand sixtr-nine.\n(SGD.) FERDINAND E. MARCOS\nPresident or the Philippines\nBy the President:\n(SGD.) RAFAEL M. SALAS\nExecutive Secretary\n204"}}],"pack":"ph-p157"};
