  FT["PH-H18330"] = {"id":"PH-H18330","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THE PHILIPPINES STRENGTHENING EXPORT DEVELOPMENT PURPOSE EXECUTIVE AMENDING E.O.","orig":"BY THE PRESIDENT OF THE PHILIPPINES STRENGTHENING EXPORT DEVELOPMENT PURPOSE EXECUTIVE AMENDING E.O."},"level":"law","status":"active","docNumber":"Executive Order No. 180","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00180_1994.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00180_1994.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18330-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Section\namended to read as follows:\n1.\nComQosition\nDevelopment\nbe composed of the following:\nof Trade and Industry\nrSecretary\n--Vice-Chairman\nof Agriculture\nand Employment\n& Technology\nof the National\nEconomic and Development\nof Bangko Sentral\n~residential\nPresidential\nen (10) Representatives\n~\n~~\n1\"\"\"\"\"\nimmediately.\nDONE in the City\nhundred and."}}],"pack":"ph-p157"};
