  FT["PH-H18378"] = {"id":"PH-H18378","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE FRESIDENT OF THE THILIPPINES BY THE PRESIDENT OF THE PHILIPPINES","orig":"MALACANANG RESIDENCE OF THE FRESIDENT OF THE THILIPPINES BY THE PRESIDENT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 186","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00186_1969.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00186_1969.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18378-A1","no":1,"noLabel":{},"text":{"en":"Done in the City of Manila, this 5th day of\nAugust, in the year of Our Lord, nineteen hundred\nand sixty-nine.\n(SGD.) FERDINAND E. MAliCOS\nPresident of the Philippines\nBy the Fresident:\n(SGD.) ERNESTO M. MACEDA\nExecutive Secretary\n224"}}],"pack":"ph-p157"};
