  FT["PH-H18446"] = {"id":"PH-H18446","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALAG ANANG RESIDENCE OF THE FRESIDENT OF THE PHILIPPINES BY THE FRESIDINT OF THE PHILIPPINES","orig":"MALAG ANANG RESIDENCE OF THE FRESIDENT OF THE PHILIPPINES BY THE FRESIDINT OF THE PHILIPPINES"},"level":"law","status":"active","docNumber":"Executive Order No. 194","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00194_1969.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00194_1969.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18446-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"of Title I, Executive Order No. 321\ndated June 12, january.?,\n1950, as revised by Executive Order\n1965, is hereby further\namended to read as follows:\n12. The Flag shall be permanently\nhoisted, day and night, in front of the\nat Malacarang, the official\nresidence of the President of the Philip-\npines; the Congross of the Philippines\nbuilding; Supreme Court building; at the\nplace of proclamation of the lst Fhilip-\npine Republic; at the Rizal Monument in\nLuneta; and at the Tomb of the Unknown\nSoldier, , Libingan ng nga Bayani.\nDone in the City of Manila, this 13th day of\nOctober, in the year of Our Lord, nineteen hundred\nand sixty-nine.\n(SOD.) FERDINAND D.\nPresident or the Philippines\nBy the Fresident:\n(SGD.) ERNESTO M. MACEDA\nExecutive Secretary\n237"}}],"pack":"ph-p157"};
  FT["PH-H18447"] = {"id":"PH-H18447","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑANG PMS LIBRARY RESTRUCTURING TH BUTION OF RBODIPIS EXECUIIVE ORDER LO. 194 AND PROVIDING FOR 033 DISAST MORSE LACING, AND FOR OTHER","orig":"MALACAÑANG PMS LIBRARY RESTRUCTURING TH BUTION OF RBODIPIS EXECUIIVE ORDER LO. 194 AND PROVIDING FOR 033 DISAST MORSE LACING, AND FOR OTHER"},"level":"law","status":"active","docNumber":"Executive Order No. 194","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00194_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00194_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18447-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"Tax on Winning-\n- Every person who wins in\nhorse races shall pay a tax equivalent to ten (107) per\ncent of his winnings or \"dividends,\" the tax to be based\non the actual amount paid to him for every winning ticket\nafter deducting the cost of the ticket:\nProvided, That\n\n2/\nin the case of winnings from double, forecast/quinella and\ntrifecta bets, the tax shall be four (4%) per cent.\nthe case of owners of winning race horses, the bax shall\nbe ten (10%) per cent of the prizes.\nThe tax herein prescribed shall be deducted from\nthe \"dividends\" corresponding to each winning ticket or\nthe \"prize\" of each winning race horse owner and withheld\nby the operator, manager, or person in charge of the horse\nraces before paying the dividends or prizes to the persons\nentitled thereto.\nor person in charge of horse\ntax was deducted and withheld in accordance with the\nsecond paragraph hereof, file a true and correct return\nwith the Commissioner of the Bureau of Internal Revenue\nin the manner or form to be prescribed by the Secretary\nof Finance, and pay within the same period the total\namount of tax so deducted and withheld.\n4. The taxes herein prescribed shall be subject\nto review by the Secretary of Finance after eighteen (18)\nmonths from the date of effectivity and implementation of\nthis Executive Order.\nIf, after review, the level of\ngovernment revenue from horse racing is equal to or higher\nthan that corresponding to the eighteen (18) months imme-\ndiately preceding the effectivity of this Executive Order\nthe tax structure for horse racing herein prescribed shall\nbecome permanent; otherwise;\nthe taxes imposed under the\nNational Internal Revenue Code, as amended, and the dis-\ntribution of gross receipts from the sale of betting\ntickets in horse races under Republic Act Nos. 6631 and\n6632 shall be automatically restored.\nThe Secretary of Finance shall promulgate\nthe necessary rules and regulations to implement this\nExecutive Order.\nSubject to the provisions of Section 4 hereof,\nSections 203 and 229 of the National Internal Revenue Code,\nas amended; and all laws, orders, issuances, and rules and\nregulations or parts thereof inconsistent with this Executive\nOrder are hereby repealed or modified accordingly.\nThis Executive Order shall take effect imme-\n\n3/\nDone in the City of Manila, this 16th day of June,\nin the year of our lord nineteen hundred and eighty-seven.\nbetraym to Agains\nBy the Fresident:"}}],"pack":"ph-p157"};
