  FT["PH-H18471"] = {"id":"PH-H18471","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE FRESIDENT OF THE FILIFPINES BY THE PRESIDENT OF THE IMILIFFINES AUTHORIZING THE DOCUMENTATION AND ADMISSION OF FOREION NATIONALS EMPLOYED UNDER REPUBLIC ACT","orig":"MALACANANG RESIDENCE OF THE FRESIDENT OF THE FILIFPINES BY THE PRESIDENT OF THE IMILIFFINES AUTHORIZING THE DOCUMENTATION AND ADMISSION OF FOREION NATIONALS EMPLOYED UNDER REPUBLIC ACT"},"level":"law","status":"active","docNumber":"Executive Order No. 197","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00197_1969.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00197_1969.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18471-A1","no":1,"noLabel":{},"text":{"en":"To carry out the provisions of this Order, the\nDepartment of Foreign Affairs and Bureau of Immig-\nration are hereby directed to issue implementing\nThis Order shall take effect immediately.\nDone in the City of Manila, this 14th day of\nOctobol, in the year of Our Lord, nineteen hundred\nand sixty-nine.\n(SGD.) FERDINAND B. MARCOS\nPresident of the Philippines\nBy the President:\n(SGD.) ERNESTO M. MACEDA\nExecutive Secretary\n243"}}],"pack":"ph-p157"};
  FT["PH-H18472"] = {"id":"PH-H18472","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Increasing the Composition of the Board of Trustees of the Metropolitan Waterworks and Sewerage System","orig":"Increasing the Composition of the Board of Trustees of the Metropolitan Waterworks and Sewerage System"},"level":"law","status":"active","docNumber":"Executive Order No. 197","issuingBody":"President of the Philippines","promulgatedDate":"1987-06-17","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00197_1987_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00197_1987_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18472-A1","no":1,"noLabel":{"en":"Sec 1"},"text":{"en":"The first and second paragraphs of Section 4 of Republic Act No. 6234, as amended, are hereby further\namended to read as follows:\n\"Sec. 4. The Board of Trustees, Composition; Qualifications; Tenure; Powers and Duties. The corporate\npowers and functions of the System shall be vested in and exercised by a Board of Trustees composed of nine\n(9) members consisting of the Secretary of Public Works and Highways as ex-officio Chairman, unless the\nPresident of the Philippines shall appoint another person as Chairman, the Administrator of the System as\nVice-Chairman, six (6) members who shall be appointed by the President of the Philippines, and the\nGovernment Corporate Counsel as ex-officio member who shall be the legal adviser of the Board.\"\nThe Chairman, if appointed, and the six (6) appointive members of the Board shall hold office for a period of\nfive (5) years, except that any person appointed to fill a vacancy shall serve only for the unexpired portion of\nthe term of the member whom he succeeds.\""}},{"id":"PH-H18472-A2","no":2,"noLabel":{"en":"Sec 2"},"text":{"en":"The Board of Trustees shall adopt rules and procedures in the conduct of its meetings. A majority of\nthe Board shall constitutes a quorum for the transaction of business and the affirmative vote of five (5)\nmembers shall be required for the adoption of any action."}},{"id":"PH-H18472-A3","no":3,"noLabel":{"en":"Sec 3"},"text":{"en":"All laws, executive or administrative orders, letters of instructions, rules and regulations, or parts\nthereof, inconsistent with this Executive Order, are hereby repealed, amended or modified accordingly."}},{"id":"PH-H18472-A4","no":4,"noLabel":{"en":"Sec 4"},"text":{"en":"This Executive Order shall take effect immediately.\nDone in the City of Manila, this 17th day of June, in the Year of Our Lord, Nineteen Hundred and\nEighty-Seven."}}],"pack":"ph-p157"};
