  FT["PH-H18492"] = {"id":"PH-H18492","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY HG FRESIDENT OF THE- FHILIPPINES PROMULGATING A MANUAL OF STUDENT RIGHTS AND RESPON- SIBILITIES.","orig":"MALACANANG RESIDENCE OF THE PRESIDENT OF THE PHILIPPINES BY HG FRESIDENT OF THE- FHILIPPINES PROMULGATING A MANUAL OF STUDENT RIGHTS AND RESPON- SIBILITIES."},"level":"law","status":"active","docNumber":"Executive Order No. 200","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00200_1969.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00200_1969.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18492-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"This Order shall take effect im-\nExecutive Order No. 170 dated February\n15, 1969, is hereby revoked.\nDone in the City of Manila, this 5th day of\nDecember, in the year of Our lord, nineteen hund-\nred and sixty-nine.\n(SGD.) FERDINAND B. MARCOS\nPresident of the Fhilippines\nBy the Fresident:\n(SGD.) ERNESTO M. MACEDA\nExecutive Secretary\n250"}}],"pack":"ph-p157"};
  FT["PH-H18493"] = {"id":"PH-H18493","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"P MS LIBRARY EXECUTIVE ORDER NO- 200 PROVIDING FOR IMB PUBLICATION OF LAWS DITHER IN THE OFFICIAL GAZETTE OR IN A NENSPAPER OF GENERAL CIRCULATION IN THE PHILIPPINES AS A REQUIRLMENT FOR TUBIR EFFECTIVITY.","orig":"P MS LIBRARY EXECUTIVE ORDER NO- 200 PROVIDING FOR IMB PUBLICATION OF LAWS DITHER IN THE OFFICIAL GAZETTE OR IN A NENSPAPER OF GENERAL CIRCULATION IN THE PHILIPPINES AS A REQUIRLMENT FOR TUBIR EFFECTIVITY."},"level":"law","status":"active","docNumber":"Executive Order No. 200","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00200_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00200_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18493-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Laws shall take effect after fifteen days\nfollowing the completion of their publication either in\nthe Official Gazette or in a newspaper of general circu-\nlation in the Philippines, unless it is otherwise provided."}},{"id":"PH-H18493-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"Article 2 of Republic Act No. 386, otherwise\nknown as the \"Civil Code of the Philippines,\" and all\nother laws inconsistent with this Executive Order are hereby\nrepealed or modified accordingly.\n\n27\nSeC. 3. This Executive Order Shall take effect imme-\ndiately after its publication in the Official Gazette.\nDone in the City of Manila, this 18th day of\nin the year of Our Lord, nineteen hundred and eighty-\nbraym b Aquint\nBy the President:\n1120\ndecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18494"] = {"id":"PH-H18494","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACANANG BY lHE PRESIDENT OF nIE PffiJ.lIPPINES INSTITUTIONALIZATION COMPUfERlZATION EXAMINATIONS ADWNISTERED REGULATORY SUPER'fISION PROFESSIONAL REGULATION COMMISSION","orig":"MALACANANG BY lHE PRESIDENT OF nIE PffiJ.lIPPINES INSTITUTIONALIZATION COMPUfERlZATION EXAMINATIONS ADWNISTERED REGULATORY SUPER'fISION PROFESSIONAL REGULATION COMMISSION"},"level":"law","status":"active","docNumber":"Executive Order No. 200","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00200_1994.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00200_1994.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18494-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"The Professional Regulation Commission, in coordination with the\nvarious Professional Regutatoty Boards, shall issue the necessary guidelines to implement\nthe full computerization of licensure examinations\nto cover the following matters:\nExamination Objective, Standards, and Nature;\nEstablishment\nand Operation of a Computerized Test\nColTection of Test Papers and Grading, Deliberating,\nDecoding, and Release of Test Pesults through"}},{"id":"PH-H18494-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"This Executi.le Order shall take effect tmmediately.\nin the year of\nDONE in the City of Manila, this 20th\nOur Lord, nineteen hundred and ninety-tom.\nPMS LIBRARY\nthe President..;..\n(-\nExecutive Secretaty"}}],"pack":"ph-p157"};
  FT["PH-H18495"] = {"id":"PH-H18495","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"BY THE PRESIDENT OF THE PffiLIPPINES AUTHORIZING THE ISSUANCE OF ONSHORE SPECIAL MINERALS EXTRACTION GOVERNMENT ENTITIES/INSTRUMENTALITIES FOR GOVERNMENT PROJECTS","orig":"BY THE PRESIDENT OF THE PffiLIPPINES AUTHORIZING THE ISSUANCE OF ONSHORE SPECIAL MINERALS EXTRACTION GOVERNMENT ENTITIES/INSTRUMENTALITIES FOR GOVERNMENT PROJECTS"},"level":"law","status":"active","docNumber":"Executive Order No. 200","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00200_2000.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00200_2000.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18495-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"of R.A. No. 7942 provides that the Department of\nEnvirornnent and Natural Resources (DENR) shall be the primary government agency\nresponsible for the conservation, management, development and proper use of the State's\nmineral resources, including those in reservations, watersheds areas and lands of public"}},{"id":"PH-H18495-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"of R.A. No. 7942 provides that the Mines and\nGeosciences Bureau (MGB) shall have direct charge in the administration and disposition\nof mineral lands and mineral resources, both offshore and onshore;\nWHEREAS, pursuant to Executive Order No. 786 dated March 19, 1982, the\nNatural Resources Development Corporation (NRDC), as a government corporation and\ncol-porate arm of the DENR, is mandated to help promote the development of the\ncountry's natural resources, including minerals;\nWHEREAS, quarry, sand, gravel, clay and related materials from onshore areas\nare highly suitable raw materials for government infrastructure projects, specially\nflagship projects, and other related civil works;\nWHEREAS, it is in the national interest to prioritize government projects in the\nutilization of these materials to enhance the delivery of services vital to the Government's\neconomic and social development programs;\n# 14761\n\nWHEREAS, it is necessary to ensure adequate, low-cost and continuous supply\nof these raw materials in order not to hamper or delay the implementation of government\nWHEREAS, the potential environmental impacts of mining/quarrying operations\nrequire appropriate safeguards and adequate mitigating measures to be set in place under\nthe strict supervision of the DENR;\nWHEREAS, Section 49 of R.A. No. 7942 provides for the issuance of\nGovernment Gratuitous Pennit to any government entity/instrumentality for the\nextraction of certain minerals for government projects, over an area of not more than two\n(2) hectares for a period co-terminous with the project;\nR.A. No. 7942 does not clearly provide for the appropriate\npermitting mechanisms in the extraction of quarry, gravel, sand, clay and other related\nmaterials needed for government projects over an area exceeding two (2) hectares;\nNOW, THEREFORE,\nI, JOSEPH EJERCITO ESTRADA, President of the\nRepublic of the Philippines, by virtue of the powers vested in me by law, do hereby\nSECTION 1. Authori\nor the Issuance 0 S ecial Minerals Extraction Permit\n(SMEP}. The DENR is hereby authorized to issue a Special Minerals Extraction Permit\nPermit to NRDC\nor any qualified\ngovernment\nentity/instrumentality for the exploration, development, utilization and/or disposition of\nquarry, sand, gravel, clay and other related materials needed for a government project.\nfrom onshore areas exceeding two (2) hectares, including areas covered by pending\nmining application(s). For this purpose, the Permittee may enter into a Memorandum of\nAgreement (MOA) with the concerned government entity/instrumentality and/or avail the\nservices of a qualified service contractor(s).\nSEC. 2. Issuance Qf Government Gratuitous Permit.\nFor the exploration,\ndevelopment, utilization and/or disposition of quarry, sand, gravel; clay and other related\nmaterials needed for a government project from onshore areas of not more than two (2)\nhectares, the issuance of a Government Gratuitous Permit by the concerned Provincial\nGovernor/City Mayor, thru the Provincial/City Mining Regulatory Board (P/CMRB),\nshall be in accordance with the pertinent provisions of R.A. No. 7942 and its Revised\nImplementing Rules and Regulations (DAO No. 96-40); Provided, That in no case shall\nthe Provincial Governor/City Mayor issue more than one (1) Government Gratuitous\nPermit for a single governm~nt project.\nSEC. 3. Authori~\nQf NRDC to Collect Certain Fees. In the case where the\nNRDC is the permittee, it is authorized to collect management, service, environmental\nuser's and other fees from the concerned government entity/instrumentality and/or\ncontractors/subcontractors. Such fees shall be shared in accordance with the sharing\nscheme to be provided for under the Implementing Rules and Regulations of this Order.\n\nSEC. 4. Implementing Rules and RegHlations. The DENR shall formulate and\nissue the necessary rules and regulations to implement this Order.\nSEC. 5. Reoealin!!: and Amending Clause. All orders, issuances, rules and\nregulations or parts thereof which are inconsistent with any of the provisions of this\nOrder are hereby repealed or amended accordingly.\nSEC. 6. gffectivi~. This Order shall take effect immediately.\nDONE in the City of Manila, this\nLord, two thousand.\nday of January, in the year of our\nBy the President:\n-~~\nRONALDO B. ZAMORA\nExecutive Secretary\nPMS LIBRARY"}}],"pack":"ph-p157"};
  FT["PH-H18496"] = {"id":"PH-H18496","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES ADJUSTING THE DIVIDEND RATE OF THE DEVELOPMENT BANK OF THE PHILIPPINES (DBP ON ITS 2001 and 2002 NET EARNINGS","orig":"MALACAÑANG BY THE PRESIDENT OF THE PHILIPPINES ADJUSTING THE DIVIDEND RATE OF THE DEVELOPMENT BANK OF THE PHILIPPINES (DBP ON ITS 2001 and 2002 NET EARNINGS"},"level":"law","status":"active","docNumber":"Executive Order No. 200","issuingBody":"President of the Philippines","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00200_2003.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00200_2003.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18496-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The percentage of dividends for year 2001 to be remitted\nby DBP to the National Government is adiusted to at least seven hundred fifty\nfive million pesos (P755 M) or equivalent to 25% net earnings."}},{"id":"PH-H18496-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"The percentage of dividends for year 2002 to be remitted by DBP\nto the National Government is adiusted to at least one billion pesos (P1 B) or\nequivalent to 23% of its 2002 net earnings.\nPaM) Hologram # 19324\n\n-2 -"}},{"id":"PH-H18496-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"This Executive Order shall take effect immediately.\nDONE in the City of Manila, this 21st day of April\nyear of our Lord, two thousand and three.\nBy the President:\nALBERTO G. ROMULO\nExecutive Secretary\nPOMP Hologram * 19325"}}],"pack":"ph-p157"};
  FT["PH-H18497"] = {"id":"PH-H18497","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE ORMOC PORT ZONE AND PLACING IT UNDER THE ADMINISTRATIVE JURISDICTION OF THE PHILIPPINE PORTS AUTHORITY (PPA)","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DECLARING AND DELINEATING THE ORMOC PORT ZONE AND PLACING IT UNDER THE ADMINISTRATIVE JURISDICTION OF THE PHILIPPINE PORTS AUTHORITY (PPA)"},"level":"law","status":"active","docNumber":"Executive Order No. 200","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00200_2016.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00200_2016.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18497-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"Port of Ormoc. The territorial jurisdiction of the Port of Ormoc\nsituated in Ormoc City, Province of Leyte, is hereby delineated and established\nparticularly described as follows:\nBeginning at a point marked 1 on the plan, being S. 40 deg. 48' W., 265.27 m.\nfrom BLLM No. 1, Cadastre 256, Ormoc City, thence:\n28'\n28'\n32'\n28'\n14'\n47'\n49'\n60'\n17'\n53'\n53'\n@ffice of the Bresident of the Philioines\nTHE PRESIDENT OF THE PHILIPPINES\n\n60'\n35'\n51'\n20\n13.93 m. to point of beginning;\nComprising a total area of THREE HUNDRED FIFTY THREE THOUSAND\nNINETY TWO SQUARE METERS (353,092.00), more or less."}},{"id":"PH-H18497-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"PPA Jurisdiction. The Ormoc Port Zone, as delineated, is\nhereby placed under the administrative jurisdiction of the PPA, which shall,\nconsistent with the regional industrial plans of the government, implement a program\nfor the proper zoning, planning, development and utilization of the port."}},{"id":"PH-H18497-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"Repeal. All issuances, orders, rules and regulations, or parts\nthereof, which are inconsistent with this Order are hereby repealed, amended or\nmodified accordingly."}},{"id":"PH-H18497-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"Separability. If any provision of this Order is declared invalid or\nunconstitutional, the other provisions not affected thereby shall remain valid and\nsubsisting."}},{"id":"PH-H18497-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"Effectivity. This Order shall take effect immediately upon\npublication in a newspaper of general circulation.\nDONE, in the City of Manila, this11th day of February\nour Lord, Two Thousand and Sixteen.\n, in the vear of\nBy the President:\nPAQUITO NOCHOA, JR.\nExecutive Secretary\n(ERTIFIED COPY:\n@flice ofthe President of the Philippines\n9 2-12-2816\nMARIANITO M. DIMAANDAL\nDIRECTOR IVar206\nMALACARANG RECORDS FFICI\n2"}}],"pack":"ph-p157"};
  FT["PH-H18498"] = {"id":"PH-H18498","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1939/eo_201_1939.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Amending Paragraph 1 of Executive Order No. 99, Dated June 14, 1937, Entitled Regulations Governing the Pay and Emoluments of Officials and Employees of the Government Called for Military Training or to Extended Tour of Active Duty in the Philippine Army","orig":"Amending Paragraph 1 of Executive Order No. 99, Dated June 14, 1937, Entitled Regulations Governing the Pay and Emoluments of Officials and Employees of the Government Called for Military Training or to Extended Tour of Active Duty in the Philippine Army"},"level":"law","status":"active","docNumber":"Executive Order No. 201","issuingBody":"President of the Philippines","promulgatedDate":"1939-04-15","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00201_1939_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00201_1939_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18498-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 201, April 15, 1939 ]\nAMENDING PARAGRAPH 1 OF EXECUTIVE ORDER NO. 99, DATED JUNE 14, 1937, ENTITLED\n“REGULATIONS GOVERNING THE PAY AND EMOLUMENTS OF OFFICIALS AND EMPLOYEES\nOF THE GOVERNMENT CALLED FOR MILITARY TRAINING OR TO EXTENDED TOUR OF\nACTIVE DUTY IN THE PHILIPPINE ARMY”\nParagraph one of Executive Order Numbered Ninety-nine, dated June fourteenth, nineteen hundred and\nthirty-seven, is hereby amended to read as follows:\n“1. No official or employee of the Government, while undergoing trainee instruction or who, upon completion\nthereof, shall have been selected for additional training to qualify him as a commissioned or\nnon-commissioned officer of the Reserve Force, or while undergoing service in the training cadre as R. O. T.\nC. student, or who shall have been called to regular annual active duty training, or to extended tour of active\nduty in the Philippine Army, in case he holds a commission in the Reserve Force, shall be compelled to lose\nhis position or to suffer any decrease of pay whatsoever due to his absence in the fulfillment of his military\nobligations.”"}}],"pack":"ph-p157"};
  FT["PH-H18499"] = {"id":"PH-H18499","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DECEMBER 3, 1947, ENTITLED \"PROHIBITING THE EXECUTION OF GOVERNMENT CON- TRACTS WHEREIN THE GOVERNMENT IS RE- QUIRED TO MAKE ADVANCE PAYMENT FOR SERVICES NOT YET RENDERED AND/OR SUP- PLIES AND MATERIALS NOT YET DELIVERED.","orig":"MALACAÑAN PALACE BY THE PRESIDENT OF THE PHILIPPINES DECEMBER 3, 1947, ENTITLED \"PROHIBITING THE EXECUTION OF GOVERNMENT CON- TRACTS WHEREIN THE GOVERNMENT IS RE- QUIRED TO MAKE ADVANCE PAYMENT FOR SERVICES NOT YET RENDERED AND/OR SUP- PLIES AND MATERIALS NOT YET DELIVERED."},"level":"law","status":"active","docNumber":"Executive Order No. 201","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00201_1949.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00201_1949.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18499-A1","no":1,"noLabel":{},"text":{"en":"in me by law, do hereby prescribe that, except with the\nprior approval of the President, no government con-\ntract for public services and or for furnishing supplies\nand materials to the Republic of the Philippines or any\nof its branches, subdivisions, agencies or instrumen-\n¡alities shall be entered into if by the terms thereof,\nthe Government is required to make an advance pay-\nment for services not yet rendered and/or supplics\nand materials not yet delivered.\n\"No payment, partial or final, shall be made on any\ncontract without a certificate on the voucher therefor\nto the effect that the services and/or süpplies and\nmaterials for which payment is contemplated have\nbeen rendered or delivered, as the case may be, in\naccordance with the terms of the contract and have\nbeen July inspected and accepted. Such certificate\nshall be signed by the Chief of the Office having full\nknowledge of the facts of the case.\n\"Notwithstanding the foregoing, the chief of any\nbureau, office, agency or instrumentality of tha Gov-\nernment may, with the approval of the Department\nhead concerned, or of the Chairman of the Control\nCommittee, Government Enterprises Council, in the\ncase of government-owned or controlled corporations,\nfurnish supplies and materials to any party who has a\ncontract with any bureau, office, agency or instrumen-\ntality, if such supplies and materials are needed in the\nperformance of the service and the value thereof does\nnot exceed in any one month ten per centum (10 %) of\nthe value of the services already rendered, due and un-\nsettled, as computed by the bureau, office, agency or\ninstrumentality concerned.\"\nDone in the City of Manila, this 14th day of Janary, in\nthe year of Our Lord, nineteen hundred and forty-nine, and\nof the Independence of the Philippines, the third.\nELPIDIO QUIRINO\nPresident of the Philixvines\nBy the President:\nTEODORO EVANgELISTA\nExecutive Secretary"}}],"pack":"ph-p157"};
  FT["PH-H18500"] = {"id":"PH-H18500","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"NALACAi1ANG RESIDENCE OF THE PRESllJENl' OF THE PHILIPPINES BY THE PHESIDEIJT OF THE PHILIPPINES EXECUTIVE ORDEH NO. 201 CREATIIiG THE MUNICIPALI'rY OF EVA I N THE Pli.OVINCE OF BOHOL","orig":"NALACAi1ANG RESIDENCE OF THE PRESllJENl' OF THE PHILIPPINES BY THE PHESIDEIJT OF THE PHILIPPINES EXECUTIVE ORDEH NO. 201 CREATIIiG THE MUNICIPALI'rY OF EVA I N THE Pli.OVINCE OF BOHOL"},"level":"law","status":"active","docNumber":"Executive Order No. 201","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00201_1965.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00201_1965.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18500-A1","no":1,"noLabel":{},"text":{"en":",\n.... 2 ...; '\n\"Bt:!cinninc !It point 1 in a stra:i[ ht line bearing\nS89° ObtE to .Point 2, a distance of 10.2 lans.; thence\"\nin a straight line bearing 821°30 Iy,J to Point 3, a dis.:..\ntance of 6.5 kills.; thence, in a strair ht line bearing\nS5u OOIW to Point 4, a distance of 6.3 lans.; thence,\nin a straight line bearine 855 0 30 f \\l[ t o Point 5, a\ndistance of 6 0 9 kills.; thence, in a strairrht line\nbearine N47° OOI\\V to Point 6, ,:1 distance of 6.75 lans.;\nthence, in a straight line bearine Nl5° 30'E to Point\n1, the point of becinning, a distance , of 12.4 kIDs.\n(Based on the map prepared by the Office of the Hieh-\nway District Engineer of Bohol, on file in this Office,\nThe municipalities of Balilihan, Catigbian, Datuan, Sagbayan-,\"\nBilar arrl Sevilla shilll have their present territories minus the\nportions thereof which are included in the territory of the munici-\npality of Eva, as ctelimited above o\nThe municipality of EVil shall heein to exist upon the appoint-\nment and qualification of the Nayor, Vice-M:ayor and amaj()rity of\nthe ccuncilors thereof.\nDone in the City ()f Maniln, this 18th day of November, in the\nyear of Our Lind, nineteen hundred and sixty-five.\nBy the Pres identt\n(SGD.) SALV A>,)OR L. lumn10\nActing Executtve Secretary\n(SGD.) DIOSDADO HACAPAGAL\nPresident of the Philippines\n\"\"'''~:;-,~\n\"\n/"}}],"pack":"ph-p157"};
  FT["PH-H18501"] = {"id":"PH-H18501","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"PMS LIBRARY MALACAÑANG GANIZING TIC MINISTRY OF TRANSPORTATION AND COM- MUNICATIONS AND FOR OTHER PURPOSES I DEFINING ITS POWERS AND FUNCTIONS,","orig":"PMS LIBRARY MALACAÑANG GANIZING TIC MINISTRY OF TRANSPORTATION AND COM- MUNICATIONS AND FOR OTHER PURPOSES I DEFINING ITS POWERS AND FUNCTIONS,"},"level":"law","status":"active","docNumber":"Executive Order No. 201","issuingBody":"President of the Philippines","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00201_1987.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00201_1987.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H18501-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"of Executive Order No. 125, dated\n, Is hereby amended to read as follows\nOffice of the Secretary.\nThe Office of the Secretary shall consist\nof the Secretary, his immediate staff, the\nFranchising Review Staff and the Investi-\ngation, Security and Law Enforcement Staff.\nThe Franchising Review Staff shall be\nheaded by a Review Staff Director with the\nsame rank, salary and privileges of a Depart-\nment Regional Director who shall be appointed\nby the President upon the recommendation of\nthe Secretary.\nThe Franchising Review Staff\nshall assist the Secretary in the review of\ncases and matters pertaining to, among others,\ngrants of franchises and the regulation thereof.\nThe Investigation, Security and Law\nEnforcement Staff shall be headed by a Staff\nDirector with the same rank, salary and pri-\nVileges of a Department Service Chief.\nInvestigation, Security and Law Enforcement\nStaff shall be responsible for (a) providing\nsecurity and intelligence for the Department;\n\n2 -\n(b) coordinating security and intelligence\nactivities of security units of its offices\nand attached agencies; (c) undertaking Law\nenforcement functions and activities relating\nto land transportation.\""}},{"id":"PH-H18501-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"of Executive Order No. 125,\ndated January 30, 1987, as amended, is hereby further amended\nby adding thereto a new paragraph to read as follows:\n\"The Offices of the Assistant Secretaries\nfor land Transportation, Postal Services,\nand Air Transportation,\n\"nascommunications, pandative \"pansportations hall\nassist the respective Assistant Secretaries in\nthe implementation and enforcement of the poli-\ncies, programs and projects, and the pertinent\nlaws on their respective areas of responsi-\nThis Executive Order shall take effect.\nimmediately.\nDone in the City of Manila, this 19th day of June;\nin the year of Our Lord, nineteen hundred and eighty-seven.\nbertagon b. Gains\nBy the President:"}}],"pack":"ph-p157"};
